window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["国家林草局"] = {"zhuyaolinmumulu-2":[],"zhuyaolinmumulu":[],"zhiwuxinpinzhongbaohuminglu-4":[],"zhiwuxinpinzhongbaohuminglu-5":[],"zhiwuxinpinzhongbaohuminglu-2":[],"zhiwuxinpinzhongbaohuminglu":[],"zhiwuxinpinzhongbaohuminglu-3":[],"zhiwuxinpinzhongbaohutiaolishishixize":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国植物新品种保护条例》（以下简称《条例》），制定本细则。"},{"i":2,"n":"第二条","txt":"本细则所称植物新品种，是指符合《条例》第二条规定的林木、竹、木质藤本、木本观赏植物（包括木本花卉）、果树（干果部分）及木本油料、饮料、调料、木本药材等植物品种。 植物品种保护名录由国家林业局确定和公布。"},{"i":3,"n":"第三条","txt":"国家林业局依照《条例》和本细则规定受理、审查植物新品种权的申请并授予植物新品种权（以下简称品种权）。 国家林业局植物新品种保护办公室（以下简称植物新品种保护办公室），负责受理和审查本细则第二条规定的植物新品种的品种权申请，组织与植物新品种保护有关的测试、保藏等业务，按国家有关规定承办与植物新品种保护有关的国际事务等具体工作。"},{"i":4,"n":"第四条","txt":"《条例》所称的繁殖材料，是指整株植物（包括苗木）、种子（包括根、茎、叶、花、果实等）以及构成植物体的任何部分（包括组织、细胞）。"},{"i":5,"n":"第五条","txt":"《条例》第七条所称的职务育种是指： （一）在本职工作中完成的育种； （二）履行本单位分配的本职工作之外的任务所完成的育种； （三）离开原单位后 3年内完成的与其在原单位承担的本职工作或者分配的任务有关的育种； （四）利用本单位的资金、仪器设备、试验场地、育种资源和其他繁殖材料及不对外公开的技术资料等所完成的育种。 除前款规定情形之外的，为非职务育种。"},{"i":6,"n":"第六条","txt":"《条例》所称完成植物新品种育种的人、品种权申请人、品种权人，均包括单位或者个人。"},{"i":7,"n":"第七条","txt":"两个以上申请人就同一个植物新品种在同一日分别提出品种权申请的，植物新品种保护办公室可以要求申请人自行协商确定申请权的归属；协商达不成一致意见的，植物新品种保护办公室可以要求申请人在规定的期限内提供证明自己是最先完成该植物新品种育种的证据；逾期不提供证据的，视为放弃申请。"},{"i":8,"n":"第八条","txt":"中国的单位或者个人就其在国内培育的植物新品种向外国人转让申请权或者品种权的，应当报国家林业局批准。 转让申请权或者品种权的，当事人应当订立书面合同，向国家林业局登记，并由国家林业局予以公告。 转让申请权或者品种权的，自登记之日起生效。"},{"i":9,"n":"第九条","txt":"依照《条例》第十一条规定，有下列情形之一的，国家林业局可以作出或者依当事人的请求作出实施植物新品种强制许可的决定： （一）为满足国家利益或者公共利益等特殊需要； （二）品种权人无正当理由自己不实施或者实施不完全，又不许可他人以合理条件实施的。 请求植物新品种强制许可的单位或者个人，应当向国家林业局提出强制许可请求书，说明理由并附具有关证明材料各一式两份。"},{"i":10,"n":"第十条","txt":"按照《条例》第十一条第二款规定，请求国家林业局裁决植物新品种强制许可使用费数额的，当事人应当提交裁决请求书，并附具不能达成协议的有关材料。国家林业局自收到裁决请求书之日起3个月内作出裁决并通知有关当事人。"},{"i":11,"n":"第十一条","txt":"授予品种权的，应当符合《条例》第十三条、第十四条、第十五条、第十六条、第十七条、第十八条和本细则第二条的规定。"},{"i":12,"n":"第十二条","txt":"依照《条例》第四十五条的规定，对《条例》施行前首批列入植物品种保护名录的和《条例》施行后新列入植物品种保护名录的属或者种的植物品种，自名录公布之日起一年内提出的品种权申请，经育种人许可，在中国境内销售该品种的繁殖材料不超过4年的，视为具有新颖性。"},{"i":13,"n":"第十三条","txt":"除《条例》第十八条规定的以外，有下列情形之一的，不得用于植物新品种命名： （一）违反国家法律、行政法规规定或者带有民族歧视性的； （二）以国家名称命名的； （三）以县级以上行政区划的地名或者公众知晓的外国地名命名的； （四）同政府间国际组织或者其他国际知名组织的标识名称相同或者近似的； （五）属于相同或者相近植物属或者种的已知名称的。"},{"i":14,"n":"第十四条","txt":"中国的单位和个人申请品种权的，可以直接或者委托代理机构向国家林业局提出申请。"},{"i":15,"n":"第十五条","txt":"中国的单位和个人申请品种权的植物品种，如涉及国家安全或者重大利益需要保密的，申请人应当在请求书中注明，植物新品种保护办公室应当按国家有关保密的规定办理，并通知申请人；植物新品种保护办公室认为需要保密而申请人未注明的，按保密申请办理，并通知有关当事人。"},{"i":16,"n":"第十六条","txt":"外国人、外国企业或者其他外国组织向国家林业局提出品种权申请和办理其他品种权事务的，应当委托代理机构办理。"},{"i":17,"n":"第十七条","txt":"申请人委托代理机构向国家林业局申请品种权或者办理其他有关事务的，应当提交委托书，写明委托权限。 申请人为两个以上而未委托代理机构代理的，应当书面确定一方为代表人。"},{"i":18,"n":"第十八条","txt":"申请人申请品种权时，应当向植物新品种保护办公室提交国家林业局规定格式的请求书、说明书以及符合本细则第十九条规定的照片各一式两份。"},{"i":19,"n":"第十九条","txt":"《条例》第二十一条所称的照片，应当符合以下要求： （一）有利于说明申请品种权的植物品种的特异性； （二）一种性状的对比应在同一张照片上； （三）照片应为彩色； （四）照片规格为8.5厘米×12.5厘米或者10厘米×15厘米。 照片应当附有简要文字说明；必要时，植物新品种保护办公室可以要求申请人提供黑白照片。"},{"i":20,"n":"第二十条","txt":"品种权的申请文件有下列情形之一的，植物新品种保护办公室不予受理： （一）内容不全或者不符合规定格式的； （二）字迹不清或者有严重涂改的； （三）未使用中文的。"},{"i":21,"n":"第二十一条","txt":"植物新品种保护办公室可以要求申请人送交申请品种权的植物品种和对照品种的繁殖材料，用于审查和检测。"},{"i":22,"n":"第二十二条","txt":"申请人应当自收到植物新品种保护办公室通知之日起3个月内送交繁殖材料。送交种子的，申请人应当送至植物新品种保护办公室指定的保藏机构；送交无性繁殖材料的，申请人应当送至植物新品种办公室指定的测试机构。 申请人逾期不送交繁殖材料的，视为放弃申请。"},{"i":23,"n":"第二十三条","txt":"申请人送交的繁殖材料应当依照国家有关规定进行检疫；应检疫而未检疫或者检疫不合格的，保藏机构或者测试机构不予接收。"},{"i":24,"n":"第二十四条","txt":"申请人送交的繁殖材料不能满足测试或者检测需要以及不符合要求的，植物新品种保护办公室可以要求申请人补交。 申请人三次补交繁殖材料仍不符合规定的，视为放弃申请。"},{"i":25,"n":"第二十五条","txt":"申请人送交的繁殖材料应当符合下列要求： （一）与品种权申请文件中所描述的该植物品种的繁殖材料相一致； （二）最新收获或者采集的； （三）无病虫害； （四）未进行药物处理。 申请人送交的繁殖材料已经进行了药物处理，应当附有使用药物的名称、使用的方法和目的。"},{"i":26,"n":"第二十六条","txt":"保藏机构或者测试机构收到申请人送交的繁殖材料的，应当向申请人出具收据。 保藏机构或者测试机构对申请人送交的繁殖材料经检测合格的，应当出具检验合格证明，并报告植物新品种保护办公室；经检测不合格的，应当报告植物新品种保护办公室，由其按照有关规定处理。"},{"i":27,"n":"第二十七条","txt":"保藏机构或者测试机构对申请人送交的繁殖材料，在品种权申请的审查期间和品种权的有效期限内，应当保密和妥善保管。"},{"i":28,"n":"第二十八条","txt":"在中国没有经常居所或者营业所的外国人、外国企业或者其他外国组织申请品种权或者要求优先权的，植物新品种保护办公室可以要求其提供下列文件： （一）国籍证明； （二）申请人是企业或者其他组织的，其营业所或者总部所在地的证明文件； （三）外国人、外国企业、外国其他组织的所属国承认中国的单位和个人可以按照该国国民的同等条件，在该国享有植物新品种的申请权、优先权和其他与品种权有关的证明文件。"},{"i":29,"n":"第二十九条","txt":"申请人向国家林业局提出品种权申请之后，又向外国申请品种权的，可以请求植物新品种保护办公室出具优先权证明文件；符合条件的，植物新品种保护办公室应当出具优先权证明文件。"},{"i":30,"n":"第三十条","txt":"申请人撤回品种权申请的，应当向国家林业局提出撤回申请，写明植物品种名称、申请号和申请日。"},{"i":31,"n":"第三十一条","txt":"中国的单位和个人将在国内培育的植物新品种向国外申请品种权的，应当向国家林业局登记。"},{"i":32,"n":"第三十二条","txt":"国家林业局对品种权申请进行初步审查时，可以要求申请人就有关问题在规定的期限内提出陈述意见或者予以修正。"},{"i":33,"n":"第三十三条","txt":"一件品种权申请包括二个以上品种权申请的，在实质审查前，植物新品种保护办公室应当要求申请人在规定的期限内提出分案申请；申请人在规定的期限内对其申请未进行分案修正或者期满未答复的，该申请视为放弃。"},{"i":34,"n":"第三十四条","txt":"依照本细则第三十三条规定提出的分案申请，可以保留原申请日；享有优先权的，可保留优先权日，但不得超出原申请的范围。 分案申请应当依照《条例》及本细则的有关规定办理各种手续。 分案申请的请求书中应当写明原申请的申请号和申请日。原申请享有优先权的，应当提交原申请的优先权文件副本。"},{"i":35,"n":"第三十五条","txt":"经初步审查符合《条例》和本细则规定条件的品种权申请，由国家林业局予以公告。 自品种权申请公告之日起至授予品种权之日前，任何人均可以对不符合《条例》和本细则规定的品种权申请向国家林业局提出异议，并说明理由。"},{"i":36,"n":"第三十六条","txt":"品种权申请文件的修改部分，除个别文字修改或者增删外，应当按照规定格式提交替换页。"},{"i":37,"n":"第三十七条","txt":"经实质审查后，符合《条例》规定的品种权申请，由国家林业局作出授予品种权的决定，向品种权申请人颁发品种权证书，予以登记和公告。 品种权人应当自收到领取品种权证书通知之日起3个月内领取品种权证书，并按照国家有关规定缴纳第一年年费。逾期未领取品种权证书并未缴纳年费的，视为放弃品种权，有正当理由的除外。 品种权自作出授予品种权的决定之日起生效。"},{"i":38,"n":"第三十八条","txt":"国家林业局植物新品种复审委员会（以下简称复审委员会）由植物育种专家、栽培专家、法律专家和有关行政管理人员组成。 复审委员会主任委员由国家林业局主要负责人指定。 植物新品种保护办公室根据复审委员会的决定办理复审的有关事宜。"},{"i":39,"n":"第三十九条","txt":"依照《条例》第三十二条第二款的规定向复审委员会请求复审的，应当提交符合国家林业局规定格式的复审请求书，并附具有关的证明材料。复审请求书和证明材料应当各一式两份。 申请人请求复审时，可以修改被驳回的品种权申请文件，但修改仅限于驳回申请的决定所涉及的部分。"},{"i":40,"n":"第四十条","txt":"复审请求不符合规定要求的，复审请求人可以在复审委员会指定的期限内补正；期满未补正或者补正后仍不符合规定要求的，该复审请求视为放弃。"},{"i":41,"n":"第四十一条","txt":"复审请求人在复审委员会作出决定前，可以撤回其复审请求。"},{"i":42,"n":"第四十二条","txt":"依照《条例》第三十六条规定，品种权在其保护期限届满前终止的，其终止日期为： （一）品种权人以书面声明放弃品种权的，自声明之日起终止； （二）品种权人未按照有关规定缴纳年费的，自补缴年费期限届满之日起终止； （三）品种权人未按照要求提供检测所需的该授权品种的繁殖材料或者送交的繁殖材料不符合要求的，国家林业局予以登记，其品种权自登记之日起终止； （四）经检测该授权品种不再符合被授予品种权时的特征和特性的，自国家林业局登记之日起终止。"},{"i":43,"n":"第四十三条","txt":"依照《条例》第三十七条第一款的规定，任何单位或者个人请求宣告品种权无效的，应当向复审委员会提交国家林业局规定格式的品种权无效宣告请求书和有关材料各一式两份，并说明所依据的事实和理由。"},{"i":44,"n":"第四十四条","txt":"已授予的品种权不符合《条例》第十四条、第十五条、第十六条和第十七条规定的，由复审委员会依据职权或者任何单位或者个人的书面请求宣告品种权无效。 宣告品种权无效，由国家林业局登记和公告，并由植物新品种保护办公室通知当事人。"},{"i":45,"n":"第四十五条","txt":"品种权无效宣告请求书中未说明所依据的事实和理由，或者复审委员会就一项品种权无效宣告请求已审理并决定仍维持品种权的，请求人又以同一事实和理由请求无效宣告的，复审委员会不予受理。"},{"i":46,"n":"第四十六条","txt":"复审委员会应当自收到无效宣告请求书之日起15日内将品种权无效宣告请求书副本和有关材料送达品种权人。品种权人应当在收到后3个月内提出陈述意见；逾期未提出的，不影响复审委员会审理。"},{"i":47,"n":"第四十七条","txt":"复审委员会对授权品种作出更名决定的，由国家林业局登记和公告，并由植物新品种保护办公室通知品种权人，更换品种权证书。 授权品种更名后，不得再使用原授权品种名称。"},{"i":48,"n":"第四十八条","txt":"复审委员会对无效宣告的请求作出决定前，无效宣告请求人可以撤回其请求。"},{"i":49,"n":"第四十九条","txt":"《条例》和本细则规定的各种事项，应当以书面形式办理。"},{"i":50,"n":"第五十条","txt":"按照《条例》和本细则规定提交的各种文件应当使用中文，并采用国家统一规定的科技术语。 外国人名、地名和没有统一中文译文的科技术语，应当注明原文。 依照《条例》和本细则规定提交的证明文件是外文的，应当附送中文译文；未附送的，视为未提交证明文件。"},{"i":51,"n":"第五十一条","txt":"当事人提交的各种文件可以打印，也可以使用钢笔或者毛笔书写，但要整齐清晰，纸张只限单面使用。"},{"i":52,"n":"第五十二条","txt":"依照《条例》和本细则规定，提交各种文件和有关材料的，当事人可以直接提交，也可以邮寄。邮寄时，以寄出的邮戳日为提交日。寄出的邮戳日不清晰的，除当事人能够提供证明外，以收到日为提交日。 依照《条例》和本细则规定，向当事人送达的各种文件和有关材料的，可以直接送交、邮寄或者以公告的方式送达。当事人委托代理机构的，送达代理机构；未委托代理机构的，送达当事人。 依本条第二款规定直接送达的，以交付日为送达日；邮寄送达的，自寄出之日起满15日，视为送达；公告送达的，自公告之日起满2个月，视为送达。"},{"i":53,"n":"第五十三条","txt":"《条例》和本细则规定的各种期限，以年或者月计算的，以其最后一月的相应日为期限届满日；该月无相应日的，以该月最后一日为期限届满日；期限届满日是法定节假日的，以节假日后的第一个工作日为期限届满日。"},{"i":54,"n":"第五十四条","txt":"当事人因不可抗力或者特殊情况耽误《条例》和本细则规定的期限，造成其权利丧失的，自障碍消除之日起2个月内，但是最多不得超过自期限届满之日起2年，可以向国家林业局说明理由并附具有关证明材料，请求恢复其权利。"},{"i":55,"n":"第五十五条","txt":"《条例》和本细则所称申请日，有优先权的，指优先权日。"},{"i":56,"n":"第五十六条","txt":"申请品种权的，应当按照规定缴纳申请费、审查费；需要测试的，应当缴纳测试费。授予品种权的，应当缴纳年费。"},{"i":57,"n":"第五十七条","txt":"当事人缴纳本细则第五十六条规定费用的，可以向植物新品种保护办公室直接缴纳，也可以通过邮局或者银行汇付，但不得使用电汇。 通过邮局或者银行汇付的，应当注明申请号或者品种权证书号、申请人或者品种权人的姓名或者名称、费用名称以及授权品种名称。 通过邮局或者银行汇付时，以汇出日为缴费日。"},{"i":58,"n":"第五十八条","txt":"依照《条例》第二十四条的规定，申请人可以在提交品种权申请的同时缴纳申请费，也可以在收到缴费通知之日起1个月内缴纳；期满未缴纳或者未缴足的，其申请视为撤回。 按照规定应当缴纳测试费的，自收到缴费通知之日起1个月内缴纳；期满未缴纳或者未缴足的，其申请视为放弃。"},{"i":59,"n":"第五十九条","txt":"第一次年费应当于领取品种权证书时缴纳，以后的年费应当在前一年度期满前1个月内预缴。"},{"i":60,"n":"第六十条","txt":"品种权人未按时缴纳第一年以后的年费或者缴纳数额不足的，植物新品种保护办公室应当通知品种权人自应当缴纳年费期满之日起6个月内补缴，同时缴纳金额为年费的25％的滞纳金。"},{"i":61,"n":"第六十一条","txt":"自本细则施行之日起3年内，当事人缴纳本细则第五十六条规定的费用确有困难的，经申请并由国家林业局批准，可以减缴或者缓缴。"},{"i":62,"n":"第六十二条","txt":"国家林业局定期出版植物新品种保护公报，公告品种权申请、授予、转让、继承、终止等有关事项。 植物新品种保护办公室设置品种权登记簿，登记品种权申请、授予、转让、继承、终止等有关事项。"},{"i":63,"n":"第六十三条","txt":"县级以上林业主管部门查处《条例》规定的行政处罚案件时，适用林业行政处罚程序的规定。"},{"i":64,"n":"第六十四条","txt":"《条例》所称的假冒授权品种，是指： （一）使用伪造的品种权证书、品种权号的； （二）使用已经被终止或者被宣告无效品种权的品种权证书、品种权号的； （三）以非授权品种冒充授权品种的； （四）以此种授权品种冒充他种授权品种的； （五）其他足以使他人将非授权品种误认为授权品种的。"},{"i":65,"n":"第六十五条","txt":"当事人因植物新品种的申请权或者品种权发生纠纷，已向人民法院提起诉讼并受理的，应当向国家林业局报告并附具人民法院已受理的证明材料。国家林业局按照有关规定作出中止或者终止的决定。"},{"i":66,"n":"第六十六条","txt":"在初步审查、实质审查、复审和无效宣告程序中进行审查和复审的人员，有下列情形之一的，应当申请回避；当事人或者其他有利害关系人也可以要求其回避： （一）是当事人或者其代理人近亲属的； （二）与品种权申请或者品种权有直接利害关系的； （三）与当事人或者其他代理人有其他可能影响公正审查和审理关系的。 审查人员的回避，由植物新品种保护办公室决定；复审委员会人员的回避，由国家林业局决定。在回避申请未被批准前，审查和复审人员不得终止履行职责。"},{"i":67,"n":"第六十七条","txt":"任何人经植物新品种保护办公室同意，可以查阅或者复制已经公告的品种权申请的案卷和品种权登记簿。 依照《条例》和本细则的规定，已被驳回、撤回或者视为放弃品种权申请的材料和已被放弃、无效宣告或者终止品种权的材料，由植物新品种保护办公室予以销毁。"},{"i":68,"n":"第六十八条","txt":"请求变更品种权申请人和品种权人的，应当向植物新品种保护办公室办理著录事项变更手续，并提出变更理由和证明材料。"},{"i":69,"n":"第六十九条","txt":"本细则由国家林业局负责解释。"},{"i":70,"n":"第七十条","txt":"本细则自发布之日起施行。"}],"zhuyaolinmupinzhongshendingbanfa":[{"i":1,"n":"第一条","txt":"为规范主要林木品种审定工作，公正、公开、科学、效率地审定林木品种，根据《中华人民共和国种子法》（以下简称《种子法》）的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国家对主要林木实行品种审定制度。主要林木品种在推广前应当通过国家级或者省级审定。 从事主要林木品种审定活动，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称主要林木品种，是指按照《种子法》第九十二条规定确定的主要林木品种，包括品种、家系、无性系以及种子园、母树林和优良种源区的种子等。"},{"i":4,"n":"第四条","txt":"国家林业局设立国家级林木品种审定委员会，承担在全国适宜生态区域推广的林木品种审定工作；省、自治区、直辖市人民政府林业主管部门设立省级林木品种审定委员会，承担在本行政区内适宜生态区域推广的林木品种审定工作。 林木品种审定委员会由科研、教学、生产、推广、管理和使用等方面的专业人员组成，每届任期5年。"},{"i":5,"n":"第五条","txt":"林木品种审定委员会设立主任委员会，负责林木品种审定的组织和结论公布工作。主任委员会设主任委员1名，副主任委员8—10名。"},{"i":6,"n":"第六条","txt":"林木品种审定委员会按照林木用途分别设立专业委员会，承担林木品种审定的初审工作。各专业委员会设主任委员1名，副主任委员1—2名。委员应当具有高级专业技术职称。"},{"i":7,"n":"第七条","txt":"林木品种审定委员会设立秘书处，由同级人民政府林业主管部门林木种苗管理机构承担，负责林木品种审定委员会的日常工作。秘书处设秘书长1名，副秘书长1—2名。"},{"i":8,"n":"第八条","txt":"林木品种审定委员会委员可以连任。委员不履行职责或者不宜继续履职者，由委员本人或者秘书处提出申请，主任委员会主任委员批准后，予以更换。"},{"i":9,"n":"第九条","txt":"由国家林业局确定的主要林木，其品种可以申请国家级或者省级审定；但仅在一个省、自治区、直辖市完成区域试验的，应当申请省级审定。 由省、自治区、直辖市人民政府林业主管部门确定的主要林木，其品种应当申请省级审定。 同一林木品种不能同时申报国家级和省级审定。"},{"i":10,"n":"第十条","txt":"提出林木品种审定申请的，申请人应当向林木品种审定委员会提交下列材料: （一）主要林木品种审定申请表。 （二）林木品种选育报告，内容应当包括：品种的亲本来源及特性、选育过程、区域试验规模与结果、主要技术指标、经济指标、品种特性、繁殖栽培技术要点、主要缺陷、主要用途、抗性、适宜种植范围等，同时提出拟定的品种名称；以品质、特殊使用价值等作为主要申报理由的，应当对品质、特殊使用价值作出详细说明并提供相关检测数据。 （三）品种及无性系应当对特异性、一致性、稳定性进行详细描述。 （四）区域试验证明表。跨省、自治区、直辖市完成区域试验的品种，应当提供至少3个在生态上具有显著差异的区域试验点数据；在一个省、自治区、直辖市完成区域试验的品种，应当提供本省、自治区、直辖市内至少3个区域试验点数据。 （五）林木品种特征（叶、茎、根、花、果实、种子、整株植物、试验林分）的图像资料或者图谱。 （六）申请材料真实"},{"i":11,"n":"第十一条","txt":"申请审定的林木品种已经获得植物新品种权的，可以不提交本办法第十条第一款规定的第三项材料，但应当提交品种权证书材料。"},{"i":12,"n":"第十二条","txt":"在中国境内没有经常居所或者营业场所的境外机构、个人在境内申请林木品种审定的，应当委托具有法人资格的境内种子企业代理，并签订委托书。"},{"i":13,"n":"第十三条","txt":"林木品种审定委员会收到申请材料后，应当对申请人提交的申请材料进行形式审查，并根据下列情况作出处理： （一）申请材料存在可以当场更正的错误的，应当允许申请人当场更正。 （二）申请材料不齐全或者不符合法定形式的，应当当场或者在5个工作日内一次告知申请人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理。 （三）申请材料齐全且符合法定形式，或者申请人按照要求提交全部补正材料的，应当受理。"},{"i":14,"n":"第十四条","txt":"县级以上人民政府林业主管部门对选育人不清，但在生产上有较高使用价值、性状优良的林木品种，可以直接向林木品种审定委员会提出审定申请；对选育人不申请审定的林木品种，可以根据与选育人签订的协议，直接向林木品种审定委员会提出审定申请。"},{"i":15,"n":"第十五条","txt":"已通过审定的林木良种，适宜种植范围发生变化的，应当按照变化后相应的适宜种植范围和本办法第九条的规定，重新申请国家级或者省级审定。"},{"i":16,"n":"第十六条","txt":"隐瞒有关情况或者提供虚假材料申请审定的，申请人在一年内不得再次申请。"},{"i":17,"n":"第十七条","txt":"林木品种审定执行国家、行业和地方有关标准；暂无标准的，应当执行省级以上人民政府林业主管部门制定的相关技术规定。"},{"i":18,"n":"第十八条","txt":"受理林木品种审定申请后，由专业委员会进行初审。 参加初审的专业委员会委员应当为单数，其中国家级林木品种审定委员会参加审定的专业委员会委员应当不少于7人，省级林木品种审定委员会参加审定的专业委员会委员应当不少于5人。 根据年度审定工作需要，专业委员会可以聘请临时委员。临时委员比例不得超过专业委员会委员总数的30%。 初审结果采用记名投票方式表决，三分之二以上的委员赞成的，即为通过。"},{"i":19,"n":"第十九条","txt":"专业委员会应当按照是否符合以下条件进行初审: （一）经区域试验证实，在一定区域内生产上有较高使用价值、性状优良的林木品种。 （二）优良种源区的优良林分或者良种基地生产的种子。 （三）有特殊使用价值的种源、家系、无性系、品种。 （四）引种驯化成功的树种及其优良种源、家系、无性系、品种。"},{"i":20,"n":"第二十条","txt":"初审通过审定的林木品种，专业委员会应当提出该林木品种的特性、栽培技术要点、主要用途和适宜种植范围。 初审未通过审定的林木品种，确实为林业生产所需，专业委员会可以提出认定建议，同时还应当提出该林木品种有效期限。 同一品种只能认定一次。"},{"i":21,"n":"第二十一条","txt":"经专业委员会初审通过的林木品种，应当由秘书处在同级人民政府林业主管部门网站进行公示，公示期限不少于30日。 公示的主要内容包括：名称、树种、学名、类别、品种特性、适宜种植范围、栽培技术要点、主要用途、申请人、选育人等。"},{"i":22,"n":"第二十二条","txt":"公示期满后，秘书处应当将初审结论和公示结果报主任委员会。主任委员会审核同意的，通过审（认）定。"},{"i":23,"n":"第二十三条","txt":"林木品种审定委员会可以委托有资质机构开展品质或者特殊价值检测、品种和无性系的DNA指纹检测。 林木品种审定委员会可以根据审定工作需要考察林木品种选育现场，对品种和无性系开展特异性、一致性、稳定性的现场查定，或者要求申请人介绍具体选育过程、区域试验测试、品质鉴定等有关情况。"},{"i":24,"n":"第二十四条","txt":"林木品种审定委员会应当对审（认）定通过的林木良种统一命名、编号，颁发林木良种证书，并由同级人民政府林业主管部门公告。 公告的主要内容包括：名称、树种、学名、类别、林木良种编号、品种特性、适宜种植范围、栽培技术要点、主要用途、申请人、选育人等；认定通过的林木良种还应当公告林木良种有效期限。 同一林木品种因改变适宜种植范围再次通过审定的，林木品种审定委员会应当在颁发新的林木良种证书前收回原林木良种证书；新的林木良种证书由原林木品种审定委员会颁发的，林木良种编号不变。"},{"i":25,"n":"第二十五条","txt":"通过国家级审定的林木良种，可以在全国适宜的生态区域推广；通过省级审定的林木良种可以在本行政区域内适宜的生态区域推广。"},{"i":26,"n":"第二十六条","txt":"省级林木品种审定委员会审（认）定通过的林木良种，应当在公告后30日内报国家级林木品种审定委员会备案。"},{"i":27,"n":"第二十七条","txt":"林木品种审定委员会对审（认）定未通过的林木品种，应当书面通知申请人；申请人有异议的，可以自接到通知之日起90日内向原林木品种审定委员会或者国家级林木品种审定委员会申请复审。"},{"i":28,"n":"第二十八条","txt":"林木品种审定委员会对于申请复审的，应当自接到复审申请一年内，按照本办法关于审（认）定的规定进行复审。 复审仍未通过审（认）定的，林木品种审定委员会不再进行第二次复审。"},{"i":29,"n":"第二十九条","txt":"认定通过的林木品种在林木良种有效期限届满后，林木良种资格自动失效，不得再作为林木良种进行推广、销售，但可以重新申请审定。"},{"i":30,"n":"第三十条","txt":"林木品种审定实行回避制度。 申请人或者相关利害关系人认为参加审定的委员可能影响审定结果公正的，可以向林木品种审定委员会提出回避申请；参加审定的委员认为有利害关系的，应当自行提出回避申请。"},{"i":31,"n":"第三十一条","txt":"林木品种审定委员会委员为申请人的，应当对本年度的林木品种审定自行回避；未回避的，其申请审定品种的审（认）定通过结果无效。 对专业委员会委员的回避申请由专业委员会主任委员决定；对专业委员会主任委员的回避申请由主任委员会主任委员决定。 对主任委员会委员的回避申请由主任委员会主任委员决定；对主任委员会主任委员的回避申请由主任委员会会议决定。"},{"i":32,"n":"第三十二条","txt":"林木品种审定委员会应当建立包括申请表、区域试验证明表、品种选育报告、林木品种特征图谱、品质鉴定报告、种子样品、审定意见和公告等内容的审定档案，保证可追溯。"},{"i":33,"n":"第三十三条","txt":"林木良种的编号由林木品种审定委员会简称、审定或者认定标志、林木良种类别代码、树种代号、林木良种顺序编号和审（认）定年份等6部分组成： （一）林木品种审定委员会简称：国家级林木品种审定委员会简称为“国”；省级林木品种审定委员会简称为各省、自治区、直辖市的简称。 （二）审定或者认定标志：S代表审定通过，R代表认定通过。 （三）林木良种类别代码用英文缩写表示，分别为：引种驯化品种ETS；优良种源SP；优良家系SF；优良无性系SC；优良品种SV；母树林SS；实生种子园SSO；无性系种子园CSO。 种子园代码后用加括号的阿拉伯数字表示育种代数，如（1）为一代种子园，（1.5）为一代改良种子园，依次类推。 （四）树种代号：由树种属名、种名（拉丁名）的第一个字母组成，与其他树种有重复的，加种名的第二个及以后的字母至相区别为止。 （五）林木良种顺序编号：由3位阿拉伯数字组成。 （六）审（认）定年份：由"},{"i":34,"n":"第三十四条","txt":"认定通过的林木良种有效期限表示为X年（XXXX年XX月XX日—XXXX年XX月XX日）。"},{"i":35,"n":"第三十五条","txt":"林木良种名称中不得含有速生、优质、高产等字样或者其他暗示林木品种速生、优质、高产、抗逆性强等描述或者其他夸大性词语。 林木良种名称应当和获得的植物新品种权的植物新品种名称一致。"},{"i":36,"n":"第三十六条","txt":"建立同一适宜生态区省际间良种试验数据共享互认机制，开展引种备案。"},{"i":37,"n":"第三十七条","txt":"通过省级审定的林木良种，引种至其他省、自治区、直辖市属于同一适宜生态区的，引种者应当将引种的林木良种和区域报所在省、自治区、直辖市人民政府林业主管部门备案。 引种者应当对引进品种的适应性负责。"},{"i":38,"n":"第三十八条","txt":"引种者应当向引种所在地省、自治区、直辖市人民政府林业主管部门提交以下引种备案材料： （一）引种备案表，包括林木良种名称、良种编号、树种、类别、引种者名称、联系方式、审定品种适宜种植区域（包括地理、气候、环境等）、拟引种区域（包括地理、气候、环境等）等信息。 （二）引种林木良种的审定公告及林木良种证书复印件。 （三）拟引种地区能够证明品种适应性的试验报告。 （四）引种备案材料的真实性承诺书。 引种的林木品种具有植物新品种权的，还应当提交品种权人同意的书面材料。"},{"i":39,"n":"第三十九条","txt":"省、自治区、直辖市人民政府林业主管部门应当自收到引种备案材料之日起30日内发布引种备案公告，公告号格式为：（X）引种〔X〕第X号，其中，第一个“X”为省、自治区、直辖市简称，第二个“X”为年号，第三个“X”为序号。"},{"i":40,"n":"第四十条","txt":"通过省级审定的林木良种的同一适宜生态区，由引种所在地省级林木品种审定委员会确定。"},{"i":41,"n":"第四十一条","txt":"审（认）定的林木良种，有下列情形之一的，可以撤销审定： （一）在使用过程中出现不可克服的严重缺陷的。 （二）以欺骗、伪造试验数据等不正当方式通过审定的。 以欺骗、贿赂等不正当手段通过审定的，申请人在3年内不得再次申请。"},{"i":42,"n":"第四十二条","txt":"属于第四十一条规定情形的，有关利害关系人或者县级以上人民政府林业主管部门可以向原林木品种审定委员会提出撤销林木良种资格申请。 拟撤销审（认）定的林木良种，由秘书处征求有关当事人意见后提出建议，经专业委员会初审后，在同级人民政府林业主管部门网站进行公示，公示期限不少于30日。 公示期满后，秘书处应当将初审意见、公示结果，提交主任委员会审核。审核同意撤销审定的，由同级人民政府林业主管部门发布撤销审（认）定公告。 林木品种审定委员会作出不予撤销林木良种资格决定的，应当书面告知申请人并说明理由。"},{"i":43,"n":"第四十三条","txt":"公告撤销审（认）定的林木良种，自公告发布之日起30日后不得作为林木良种推广、销售。 省级林木品种审定委员会应当自撤销公告发布之日起30日内报国家级林木品种审定委员会备案。"},{"i":44,"n":"第四十四条","txt":"林木品种审定所需工作经费，应当纳入同级财政预算，不得向申请人收取。"},{"i":45,"n":"第四十五条","txt":"主要林木品种审定申请表、引种备案表的格式由国家林业局制定。"},{"i":46,"n":"第四十六条","txt":"本办法自2017年12月1日起施行。"}],"guojiabaohudeyouyidehuozheyouzhongyaojingjikexueya9f09e3":[],"guojialinyejuweituoshishilinyexingzhengxukeshixian69e888":[{"i":1,"n":"第一条","txt":"为了规范委托实施林业行政许可事项行为，根据《中华人民共和国行政许可法》等法律法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国家林业局委托实施林业行政许可事项，适用本办法。 委托实施林业行政许可事项，应当遵循合法、公开、公平、公正、便民、高效的原则。"},{"i":3,"n":"第三条","txt":"法律、行政法规规定由国家林业局实施的林业行政许可事项，国家林业局可以委托省、自治区、直辖市人民政府林业主管部门或者符合法律规定的其他机关实施。"},{"i":4,"n":"第四条","txt":"国家林业局行政许可管理机构可以根据行政许可承办机构工作需要和地方行政审批制度改革要求，提出委托实施林业行政许可事项的建议，报请国家林业局局务会议审议。 国家林业局委托实施林业行政许可事项，应当考虑拟受委托机关的承接能力，并征求拟受委托机关的意见。"},{"i":5,"n":"第五条","txt":"国家林业局委托实施林业行政许可事项，应当以国家林业局公告的形式向社会公布以下内容： （一）受委托机关的名称、地址、联系方式； （二）委托实施行政许可的具体事项、委托权限、委托期限等； （三）国家林业局的地址、联系方式。"},{"i":6,"n":"第六条","txt":"国家林业局委托实施林业行政许可事项，应当与受委托机关签订委托实施林业行政许可事项的书面协议。 国家林业局对受委托机关实施行政许可行为的后果承担法律责任。"},{"i":7,"n":"第七条","txt":"受委托机关应当以国家林业局的名义，实施受委托的林业行政许可事项。 受委托机关不得将国家林业局委托的林业行政许可事项再委托其他组织或者个人实施。"},{"i":8,"n":"第八条","txt":"受委托机关应当在书面协议委托的权限范围内，按照国家林业局规定的条件和程序，依法受理、审查行政许可申请并作出行政许可决定。 受委托机关应当按照国家林业局规定的格式制作行政许可文书，颁发的行政许可决定书和其他行政许可文书应当加盖国家林业局行政许可专用印章；颁发的行政许可证书应当加盖国家林业局印章。 受委托机关应当公开行政许可决定，公众有权依法查阅。"},{"i":9,"n":"第九条","txt":"林业行政许可事项委托实施后，申请人应当按照国家林业局公告的要求向受委托机关提交申请材料。申请人仍向国家林业局提交申请材料的，国家林业局应当告知其具体的受委托机关。"},{"i":10,"n":"第十条","txt":"国家林业局应当对受委托机关实施行政许可工作予以经费支持，加强业务指导和培训，并依法对受委托机关实施林业行政许可事项的行为进行监督检查，及时纠正林业行政许可实施中的违法行为。 国家林业局和受委托机关应当依法对被许可人从事的行政许可活动进行监督检查，并将监督检查的情况和处理结果予以记录归档。公众有权依法查阅监督检查记录。"},{"i":11,"n":"第十一条","txt":"受委托机关应当建立健全受委托实施林业行政许可决定文件的档案管理制度。 受委托机关作出的不予受理、准予或者不准予行政许可决定以及受委托实施行政许可的汇总情况，应当于次年1月15日前报国家林业局。"},{"i":12,"n":"第十二条","txt":"在林业行政许可事项委托期限届满前6个月，国家林业局应当根据委托实施情况，决定是否继续委托。继续委托的，国家林业局应当和原受委托机关重新签订委托实施林业行政许可事项的书面协议；不再继续委托的，国家林业局应当及时向社会公告。"},{"i":13,"n":"第十三条","txt":"国家林业局在林业行政许可事项委托期限内需要变更、中止或者终止委托的，应当及时向社会公告。"},{"i":14,"n":"第十四条","txt":"国家林业局和受委托机关及其工作人员在实施受委托林业行政许可和监督检查中存在违法行为的，应当依法承担法律责任。"},{"i":15,"n":"第十五条","txt":"本办法自2017年12月1日起施行。2013年1月22日发布的《国家林业局委托实施野生动植物行政许可事项管理办法》（国家林业局令第30号）同时废止。"}],"guojiazhongdianbaohuyeshengdongwuminglu":[],"guojiazhongdianbaohuyeshengdongwuxunyangfanzhixukeb76c7c":[{"i":1,"n":"第一条","txt":"为保护、发展和合理利用野生动物资源，加强野生动物驯养繁殖管理工作，维护野生动物驯养繁殖单位和个人的合法权益，根据《中华人民共和国野生动物保护法》第十七条规定，制定本办法。"},{"i":2,"n":"第二条","txt":"从事驯养繁殖野生动物的单位和个人，必须取得《国家重点保护野生动物驯养繁殖许可证》（以下简称《驯养繁殖许可证》）。没有取得《驯养繁殖许可证》的单位和个人，不得从事野生动物驯养繁殖活动。 本办法所称野生动物，是指国家重点保护的陆生野生动物；所称驯养繁殖，是指在人为控制条件下，为保护、研究、科学实验、展览及其他经济目的而进行的野生动物驯养繁殖活动。"},{"i":3,"n":"第三条","txt":"具备下列条件的单位和个人，可以申请《驯养繁殖许可证》： （一）有适宜驯养繁殖野生动物的固定场所和必需的设施； （二）具备与驯养繁殖野生动物种类、数量相适应的人员和技术； （三）驯养繁殖野生动物的饲料来源有保证。"},{"i":4,"n":"第四条","txt":"有下列情况之一的，可以不批准发放《驯养繁殖许可证》： （一）野生动物资源不清； （二）驯养繁殖尚未成功或技术尚未过关； （三）野生动物资源极少，不能满足驯养繁殖种源要求。"},{"i":5,"n":"第五条","txt":"驯养繁殖野生动物的单位和个人，必须向所在地县级政府野生动物行政主管部门提出书面申请，并填写《国家重点保护野生动物驯养繁殖许可证申请表》。? 凡驯养繁殖国家一级保护野生动物的，由省、自治区、直辖市政府林业行政主管部门报林业部审批；凡驯养繁殖国家二级保护野生动物的，由省、自治区、直辖市政府林业行政主管部门审批。 批准驯养繁殖野生动物的，作出行政许可决定的林业行政主管部门应当核发《驯养繁殖许可证》。 《驯养繁殖许可证》和《国家重点保护野生动物驯养繁殖许可证申请表》由林业部统一印制。"},{"i":6,"n":"第六条","txt":"驯养繁殖野生动物的单位和个人，应当遵守以下规定： （一）遵守国家和地方有关野生动物保护管理政策和法规，关心和支持野生动物保护事业； （二）用于驯养繁殖的野生动物来源符合国家规定； （三）接受野生动物的行政主管部门的监督检查和指导； （四）建立野生动物驯养繁殖档案和统计制度； （五）按有关规定出售、利用其驯养繁殖野生动物及其产品。"},{"i":7,"n":"第七条","txt":"驯养繁殖野生动物的单位和个人，必须按照《驯养繁殖许可证》规定的种类进行驯养繁殖活动。需要变更驯养繁殖野生动物种类的，应当比照本办法第五条的规定，在2个月内向原批准机关申请办理变更手续；需要终止驯养繁殖野生动物活动的，应当在2个月内向原批准机关办理终止手续，并交回原《驯养繁殖许可证》。"},{"i":8,"n":"第八条","txt":"因驯养繁殖野生动物需要从野外获得种源的，必须按照《中华人民共和国野生动物保护法》第十六条及有关规定办理。"},{"i":9,"n":"第九条","txt":"取得《驯养繁殖许可证》的单位和个人，需要出售、利用其驯养繁殖的国家一级保护野生动物及其产品的，必须经林业部或其授权的单位批准；需要出售、利用其驯养繁殖的国家二级保护野生动物及其产品的，必须经省、自治区、直辖市政府林业行政主管部门或其授权的单位批准。 取得《驯养繁殖许可证》的单位和个人未经批准不得出售、利用其驯养繁殖的野生动物及其产品。"},{"i":10,"n":"第十条","txt":"县级以上政府野生动物行政主管部门或其授权的单位应当定期查验《驯养繁殖许可证》。对未取得《驯养繁殖许可证》的单位和个人进行野生动物驯养繁殖活动的，由县级以上政府野生动物行政主管部门没收其驯养繁殖的野生动物。"},{"i":11,"n":"第十一条","txt":"取得《驯养繁殖许可证》的单位和个人，有下列情况之一的，除按野生动物保护法律、法规的有关规定处理外，批准驯养繁殖野生动物或核发《驯养繁殖许可证》的机关可以注销其《驯养繁殖许可证》，并可建议工商行政管理部门吊销其《企业法人营业执照》或《营业执照》： （一）超出《驯养繁殖许可证》的规定驯养繁殖野生动物种类的； （二）隐瞒、虚报或以其他非法手段取得《驯养繁殖许可证》的； （三）伪造、涂改、转让或倒卖《驯养繁殖许可证》的； （四）非法出售、利用其驯养繁殖的野生动物及其产品的； （五）取得《驯养繁殖许可证》以后在1年内未从事驯养繁殖活动的。 被注销《驯养繁殖许可证》的单位和个人，应立即停止驯养繁殖野生动物活动，其驯养繁殖的野生动物由县级以上政府野生动物行政主管部门或其授权单位按有关规定处理。"},{"i":12,"n":"第十二条","txt":"省、自治区、直辖市政府林业行政主管部门要建立《驯养繁殖许可证》审批、核发制度，配备专人管理，使用野生动物管理专用章。"},{"i":13,"n":"第十三条","txt":"本办法由林业部负责解释。"},{"i":14,"n":"第十四条","txt":"本办法自1991年4月1日起施行。"}],"guojiazhongdianbaohuyeshengzhiwuminglu":[],"zaiguojiajiziranbaohuquxiuzhusheshishenpiguanlizan663dae":[{"i":1,"n":"第一条","txt":"为了规范在国家级自然保护区修筑设施审批事项，加强对修筑设施的事中事后监督管理，根据《中华人民共和国自然保护区条例》、《森林和野生动物类型自然保护区管理办法》等法律法规和国务院有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在国家级自然保护区修筑设施，应当遵守本办法。 本办法所称国家级自然保护区，是指林业主管部门主管的国家级自然保护区。 本办法所称修筑设施，是指以穿越或者占用国家级自然保护区的方式开展设施建设，包括修筑临时设施和永久设施。"},{"i":3,"n":"第三条","txt":"在国家级自然保护区修筑设施，应当经国家林业局审查批准。"},{"i":4,"n":"第四条","txt":"严格限制在国家级自然保护区修筑设施。必须修筑设施的，应当严格控制建设区域、面积和方式，并采取有效措施保护生态环境，确保不对主要保护对象产生重大影响，确保不改变自然生态系统基本特征和结构完整性，最大限度减少对国家级自然保护区的不利影响。 禁止在国家级自然保护区修筑以下设施： （一）光伏发电、风力发电、火力发电等项目的设施。 （二）高尔夫球场开发、房地产开发、会所建设等项目的设施。 （三）社会资金进行商业性探矿勘查，以及不属于国家紧缺矿种资源的基础地质调查和矿产公益性远景调查的设施。 （四）污染环境、破坏自然资源或者自然景观的设施。 （五）国家禁止修筑的其他设施。"},{"i":5,"n":"第五条","txt":"修筑设施的单位或者个人应当向国家林业局提出申请，并提交以下申请材料： （一）申请表。 （二）拟修筑设施必须建设且无法避让国家级自然保护区的说明材料。包括：拟修筑设施项目批准文件及规划或者工程设计文件等；机场、铁路、公路、水利水电、围堰、围填海等建设项目，还应当提供修筑设施在选址选线上无法避让国家级自然保护区的比选方案。 （三）拟修筑设施对自然生态影响的说明材料。包括：拟修筑设施对国家级自然保护区主要保护对象和自然生态系统影响的评价报告或者评价登记表，以及减轻影响和恢复生态的补救性措施。国家级自然保护区属于湿地类型的，应当按照“先补后占、占补平衡”的原则，提供湿地恢复或者重建方案；机场、铁路、公路、水利水电、围堰、围填海等建设项目，还应当提供修建野生动物通道、过鱼设施等消除或者减少对野生动物不利影响的方案。 （四）相关主体的意见材料。包括：省级人民政府林业主管部门的初审意见。 （五）国家"},{"i":6,"n":"第六条","txt":"国家林业局对申请材料不全或者不符合法定形式的，应当一次性告知申请人限期补正。对依法不予受理的，应当告知申请人并说明理由。"},{"i":7,"n":"第七条","txt":"国家林业局应当自受理之日起20日内作出是否准予行政许可的决定，出具准予行政许可决定书或者不予行政许可决定书，并告知申请人。20日内不能作出决定的，经本行政机关负责人批准，可以延长10日，并将延长期限的理由告知申请人。"},{"i":8,"n":"第八条","txt":"符合本办法规定的，国家林业局应当作出准予修筑设施的行政许可决定；不符合的，国家林业局应当作出不予修筑设施的行政许可决定，并告知不予许可理由。"},{"i":9,"n":"第九条","txt":"国家林业局作出行政许可决定，需要组织专家评审的，应当将所需时间书面告知申请人。专家评审所需时间不得超过30日。 专家评审时间不计算在作出行政许可决定的期限内。"},{"i":10,"n":"第十条","txt":"在国家级自然保护区修筑设施，依法需要办理用地手续或者变更国家级自然保护区的范围和规划的，按照有关法律法规的规定办理。"},{"i":11,"n":"第十一条","txt":"国家林业局负责全国国家级自然保护区修筑设施的监督检查工作；县级以上地方人民政府林业主管部门负责本行政区域内国家级自然保护区修筑设施的监督检查工作。 对批准在国家级自然保护区修筑设施的，县级以上人民政府林业主管部门应当加强对修筑设施施工期和运营期的监督检查。 国家级自然保护区管理机构应当对修筑设施情况进行跟踪监督并开展生态监测，检查生态保护或者恢复措施落实情况，发现问题及时处理，并报告所属林业主管部门。"},{"i":12,"n":"第十二条","txt":"准予修筑设施的行政许可决定的有效期为两年。确需延期的，修筑设施的单位和个人应当在有效期届满前3个月向国家林业局提出延期申请，国家林业局应当在准予行政许可决定书有效期届满前作出是否准予延期的决定。"},{"i":13,"n":"第十三条","txt":"国家级自然保护区实验区居民，在遵守国家级自然保护区有关规定和不破坏自然资源、生态环境的前提下，在固定生产生活活动范围内修筑必要的种植、养殖和生活用房设施的，应当在修筑设施前向所在地国家级自然保护区管理机构报告，并接受指导和监督。国家林业局不再审批。"},{"i":14,"n":"第十四条","txt":"违反本办法规定，未经批准擅自在国家级自然保护区修筑设施的，县级以上人民政府林业主管部门应当责令停止建设或者使用设施，并采取补救措施。"},{"i":15,"n":"第十五条","txt":"在国家级自然保护区修筑设施对自然保护区造成破坏的，县级以上人民政府林业主管部门应当依法给予行政处罚或者作出其他处理决定。 林业主管部门在对国家级自然保护区监督检查中，发现有关工作人员有违法行为，依法应当给予处分的，应当向其任免机关或者监察机关提出处分建议。"},{"i":16,"n":"第十六条","txt":"在国家级自然保护区修筑设施申请表的格式由国家林业局制定。"},{"i":17,"n":"第十七条","txt":"本办法自2018年4月15日起施行。"}],"daxiongmaoguoneijiezhanguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强大熊猫保护，规范大熊猫国内借展管理，保障大熊猫圈养种群健康发展，提高公众保护野生动物意识，促进生态文明建设，根据《中华人民共和国野生动物保护法》等有关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称借展是指以文化交流、科普宣传或者公众教育等为目的，借出或者借入大熊猫进行展览的行为。"},{"i":3,"n":"第三条","txt":"借展大熊猫应当遵循科学、适度的原则，不得危及大熊猫圈养种群的发展，不得以单纯营利为目的。"},{"i":4,"n":"第四条","txt":"借展大熊猫的借入方应当具备与驯养繁殖大熊猫相适应的资金、设施和人员等条件，取得具有大熊猫物种的国家重点保护野生动物驯养繁殖许可证。"},{"i":5,"n":"第五条","txt":"用于借展的大熊猫应当是人工繁殖的健康个体，年龄在2岁以上25岁以下。 禁止将非人工繁殖或者野外救护的大熊猫用于借展；禁止将2岁以下和25岁以上的大熊猫用于借展。"},{"i":6,"n":"第六条","txt":"借展双方应当签订书面协议，对大熊猫生活条件、医疗条件、应急保障条件及应急预案、借展期限、费用、借展结束后大熊猫送返以及违约责任等进行约定。 借展大熊猫的期限不得少于1年，但因不可抗力等特殊情况除外。"},{"i":7,"n":"第七条","txt":"申请借展大熊猫，应当提交下列书面材料： （一）野生动物保护管理行政许可事项申请表； （二）借展双方的单位证明材料； （三）借展双方具有大熊猫物种的国家重点保护野生动物驯养繁殖许可证； （四）借展双方签订的借展协议； （五）借出方大熊猫圈养种群状况说明材料； （六）借展大熊猫个体谱系号、标记等身份证明材料； （七）借入方借展活动及大熊猫饲养管理、科普教育方案。"},{"i":8,"n":"第八条","txt":"申请借展大熊猫按照下列程序办理： （一）由借出方向国家林业局提出申请。 （二）国家林业局依法受理后，应当对申请材料进行审查。经过审查，符合本规定条件的，国家林业局应当在20个工作日内作出准予行政许可的决定。必要时，国家林业局可以组织专家在30日内对借入方借展活动、大熊猫饲养管理方案以及场馆设施进行论证或者实地检验。 （三）国家林业局作出行政许可决定后，借出、借入方所在地省级人民政府林业行政主管部门分别在借展开始前和结束后依据国家林业局行政许可文书核发大熊猫离开借出方、借入方的运输证件。"},{"i":9,"n":"第九条","txt":"借展期间，借入方应当提供满足大熊猫生活、生理健康的饲养和医疗条件。 借展期间，借入方应当建立大熊猫病例档案和饲养日志，载明大熊猫饲养管理、医疗健康情况等内容。 借展期间，禁止采集借展大熊猫的血液、精液等样品，但是对大熊猫进行健康检查的除外。法律法规另有规定的，从其规定。 借展期间，借入方不得将借展大熊猫转借第三方。"},{"i":10,"n":"第十条","txt":"借展期间，借出方应当对借入方的借展大熊猫的饲养管理和疫病防治等进行指导，并应当每年对借展大熊猫进行一次以上健康检查。"},{"i":11,"n":"第十一条","txt":"国家林业局和借展双方所在地人民政府野生动物行政主管部门应当对大熊猫借展活动的情况进行监督检查，督促借展双方完善应急处置机制。 借展双方应当配合监督检查，如实提供有关材料。"},{"i":12,"n":"第十二条","txt":"借展期间，借展大熊猫发生受伤、患病等突发事件的，借入方应当通知借出方，及时采取救护措施，并报告所在地县级以上地方人民政府野生动物行政主管部门；借展大熊猫发生致残、死亡等重大突发事件的，借入方应当立即通知借出方并报告所在地省级人民政府林业行政主管部门和国家林业局。 有关人民政府野生动物行政主管部门应当监督借展双方在发生突发事件时按照应急预案进行妥善处理。"},{"i":13,"n":"第十三条","txt":"在借展期间，借出方或者借入方违反本规定的，由县级以上人民政府野生动物行政主管部门依照野生动物保护法律法规给予处罚；野生动物保护法律法规没有规定的，可以根据情节轻重作出如下处理： （一）给予警告、责令限期改正； （二）有违法所得的，处以违法所得一倍以上三倍以下且不超过三万元的罚款；没有违法所得的，处以一万元以下的罚款。 经责令改正仍拒不改正的，国家林业局可以责令终止借展活动，限期将大熊猫送返借出方。 借展期间，借出方或者借入方有违法行为、构成犯罪的，依法追究刑事责任。"},{"i":14,"n":"第十四条","txt":"借出方或者借入方存在下列情形之一的，国家林业局1年内不予批准开展大熊猫借展活动： （一）申请行政许可过程中隐瞒有关情况或者提供虚假材料的； （二）擅自借出或者转借大熊猫的； （三）重大过失造成大熊猫死亡的； （四）拒不配合各级人民政府野生动物行政主管部门监督检查或者拒不执行野生动物行政主管部门处罚决定的。 借出方或者借入方以欺骗、贿赂等不正当手段取得行政许可的，国家林业局3年内不予批准开展大熊猫借展活动。"},{"i":15,"n":"第十五条","txt":"各级人民政府野生动物行政主管部门有关工作人员在大熊猫借展管理过程中，滥用职权、徇私舞弊的，依法给予处分；情节严重、构成犯罪的，依法追究刑事责任。"},{"i":16,"n":"第十六条","txt":"本规定所称“以上”包括本数，“以下”不包括本数。"},{"i":17,"n":"第十七条","txt":"本规定自2011年9月1日起施行。"}],"jianshexiangmushiyonglindishenheshenpiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范建设项目使用林地审核和审批，严格保护和合理利用林地，促进生态林业和民生林业发展，根据《中华人民共和国森林法》、《中华人民共和国行政许可法》、《中华人民共和国森林法实施条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称建设项目使用林地，是指在林地上建造永久性、临时性的建筑物、构筑物，以及其他改变林地用途的建设行为。包括： （一）进行勘查、开采矿藏和各项建设工程占用林地。 （二）建设项目临时占用林地。 （三）森林经营单位在所经营的林地范围内修筑直接为林业生产服务的工程设施占用林地。"},{"i":3,"n":"第三条","txt":"建设项目应当不占或者少占林地，必须使用林地的，应当符合林地保护利用规划，合理和节约集约利用林地。 建设项目使用林地实行总量控制和定额管理。 建设项目限制使用生态区位重要和生态脆弱地区的林地，限制使用天然林和单位面积蓄积量高的林地，限制经营性建设项目使用林地。"},{"i":4,"n":"第四条","txt":"占用和临时占用林地的建设项目应当遵守林地分级管理的规定： （一）各类建设项目不得使用Ⅰ级保护林地。 （二）国务院批准、同意的建设项目，国务院有关部门和省级人民政府及其有关部门批准的基础设施、公共事业、民生建设项目，可以使用Ⅱ级及其以下保护林地。 （三）国防、外交建设项目，可以使用Ⅱ级及其以下保护林地。 （四）县（市、区）和设区的市、自治州人民政府及其有关部门批准的基础设施、公共事业、民生建设项目，可以使用Ⅱ级及其以下保护林地。 （五）战略性新兴产业项目、勘查项目、大中型矿山、符合相关旅游规划的生态旅游开发项目，可以使用Ⅱ级及其以下保护林地。其他工矿、仓储建设项目和符合规划的经营性项目，可以使用Ⅲ级及其以下保护林地。 （六）符合城镇规划的建设项目和符合乡村规划的建设项目，可以使用Ⅱ级及其以下保护林地。 （七）符合自然保护区、森林公园、湿地公园、风景名胜区等规划的建设项目，可以使用自然保护"},{"i":5,"n":"第五条","txt":"建设项目占用林地的审核权限，按照《中华人民共和国森林法实施条例》的有关规定执行。 建设项目占用林地，经林业主管部门审核同意后，建设单位和个人应当依照法律法规的规定办理建设用地审批手续。"},{"i":6,"n":"第六条","txt":"建设项目临时占用林地和森林经营单位在所经营的林地范围内修筑直接为林业生产服务的工程设施占用林地的审批权限，由县级以上地方人民政府林业主管部门按照省、自治区、直辖市有关规定办理。其中，重点国有林区内的建设项目，由省级林业主管部门审批。"},{"i":7,"n":"第七条","txt":"占用林地和临时占用林地的用地单位或者个人提出使用林地申请，应当填写《使用林地申请表》，同时提供下列材料： （一）用地单位的资质证明或者个人的身份证明。 （二）建设项目有关批准文件。包括：可行性研究报告批复、核准批复、备案确认文件、勘查许可证、采矿许可证、项目初步设计等批准文件；属于批次用地项目，提供经有关人民政府同意的批次用地说明书并附规划图。 （三）拟使用林地的有关材料。包括：林地权属证书、林地权属证书明细表或者林地证明；属于临时占用林地的，提供用地单位与被使用林地的单位、农村集体经济组织或者个人签订的使用林地补偿协议或者其他补偿证明材料；涉及使用国有林场等国有林业企事业单位经营的国有林地，提供其所属主管部门的意见材料及用地单位与其签订的使用林地补偿协议；属于符合自然保护区、森林公园、湿地公园、风景名胜区等规划的建设项目，提供相关规划或者相关管理部门出具的符合规划的证明材料，其中，涉"},{"i":8,"n":"第八条","txt":"修筑直接为林业生产服务的工程设施的森林经营单位提出使用林地申请，应当填写《使用林地申请表》，提供相关批准文件或者修筑工程设施必要性的说明，并提供工程设施内容、使用林地面积等情况说明。"},{"i":9,"n":"第九条","txt":"建设项目需要使用林地的，用地单位或者个人应当向林地所在地的县级人民政府林业主管部门提出申请；跨县级行政区域的，分别向林地所在地的县级人民政府林业主管部门提出申请。"},{"i":10,"n":"第十条","txt":"县级人民政府林业主管部门对材料齐全、符合条件的使用林地申请，应当在收到申请之日起10个工作日内，指派2名以上工作人员进行用地现场查验，并填写《使用林地现场查验表》。"},{"i":11,"n":"第十一条","txt":"县级人民政府林业主管部门对建设项目拟使用的林地，应当在林地所在地的村（组）或者林场范围内将拟使用林地用途、范围、面积等内容进行公示，公示期不少于5个工作日。但是，依照相关法律法规的规定不需要公示的除外。"},{"i":12,"n":"第十二条","txt":"按照规定需要报上级人民政府林业主管部门审核和审批的建设项目，下级人民政府林业主管部门应当将初步审查意见和全部材料报上级人民政府林业主管部门。 审查意见中应当包括以下内容:项目基本情况，拟使用林地和采伐林木情况，符合林地保护利用规划情况，使用林地定额情况，以及现场查验、公示情况等。"},{"i":13,"n":"第十三条","txt":"有审核审批权的林业主管部门对申请材料不全或者不符合法定形式的，应当一次性书面告知用地单位或者个人限期补正；逾期未补正的，退还申请材料。"},{"i":14,"n":"第十四条","txt":"符合本办法第三条、第四条规定的条件，并且符合国家供地政策，对生态环境不会造成重大影响，有审核审批权的人民政府林业主管部门应当作出准予使用林地的行政许可决定，按照国家规定的标准预收森林植被恢复费后，向用地单位或者个人核发准予行政许可决定书。不符合上述条件的，有关人民政府林业主管部门应当作出不予使用林地的行政许可决定，向用地单位或者个人核发不予行政许可决定书，告知不予许可的理由。 有审核审批权的人民政府林业主管部门对用地单位和个人提出的使用林地申请，应当在《中华人民共和国行政许可法》规定的期限内作出行政许可决定。"},{"i":15,"n":"第十五条","txt":"建设项目需要使用林地的，用地单位或者个人应当一次申请。严禁化整为零、规避林地使用审核审批。 建设项目批准文件中已经明确分期或者分段建设的项目，可以根据分期或者分段实施安排，按照规定权限分次申请办理使用林地手续。 采矿项目总体占地范围确定，采取滚动方式开发的，可以根据开发计划分阶段按照规定权限申请办理使用林地手续。 公路、铁路、水利水电等建设项目配套的移民安置和专项设施迁建工程，可以分别具体建设项目，按照规定权限申请办理使用林地手续。 需要国务院或者国务院有关部门批准的公路、铁路、油气管线、水利水电等建设项目中的桥梁、隧道、围堰、导流（渠）洞、进场道路和输电设施等控制性单体工程和配套工程，根据有关开展前期工作的批文，可以由省级林业主管部门办理控制性单体工程和配套工程先行使用林地审核手续。整体项目申请时，应当附具单体工程和配套工程先行使用林地的批文及其申请材料，按照规定权限一次申请办理使用"},{"i":16,"n":"第十六条","txt":"国家或者省级重点的公路、铁路跨多个市（县），已经完成报批材料并且具备动工条件的，可以地级市为单位，由具有整体项目审核权限的人民政府林业主管部门分段审核。 大中型水利水电工程可以分别坝址、淹没区，由具有整体项目审核权限的人民政府林业主管部门分别审核。"},{"i":17,"n":"第十七条","txt":"公路、铁路、输电线路、油气管线和水利水电、航道建设项目临时占用林地的，可以根据施工进展情况，一次或者分批次由具有整体项目审批权限的人民政府林业主管部门审批临时占用林地。"},{"i":18,"n":"第十八条","txt":"抢险救灾等急需使用林地的建设项目，依据土地管理法律法规的有关规定，可以先行使用林地。用地单位或者个人应当在灾情结束后6个月内补办使用林地审核手续。属于临时用地的，灾后应当恢复林业生产条件，依法补偿后交还原林地使用者，不再办理用地审批手续。"},{"i":19,"n":"第十九条","txt":"建设项目因设计变更等原因需要增加使用林地面积的，依据规定权限办理用地审核审批手续；需要改变使用林地位置或者减少使用林地面积的，向原审核审批机关申请办理变更手续。"},{"i":20,"n":"第二十条","txt":"公路、铁路、水利水电、航道等建设项目临时占用的林地在批准期限届满后仍需继续使用的，应当在届满之日前3个月，由用地单位向原审批机关提出延续临时占用申请，并且提供本办法第七条第三项规定的有关补偿材料。原审批机关应当按照本办法规定的条件进行审查，作出延续行政许可决定。"},{"i":21,"n":"第二十一条","txt":"国家依法保护林权权利人的合法权益。建设项目使用林地的，应当对涉及单位和个人的森林、林木、林地依法给予补偿。"},{"i":22,"n":"第二十二条","txt":"建设项目临时占用林地期满后，用地单位应当在一年内恢复被使用林地的林业生产条件。 县级人民政府林业主管部门应当加强对用地单位使用林地情况的监管，督促用地单位恢复林业生产条件。"},{"i":23,"n":"第二十三条","txt":"上级人民政府林业主管部门可以委托下级人民政府林业主管部门对建设项目使用林地实施行政许可。"},{"i":24,"n":"第二十四条","txt":"经审核同意使用林地的建设项目，依照有关规定批准用地后，县级以上人民政府林业主管部门应当及时变更林地管理档案。"},{"i":25,"n":"第二十五条","txt":"经审核同意使用林地的建设项目，准予行政许可决定书的有效期为两年。建设项目在有效期内未取得建设用地批准文件的，用地单位应当在有效期届满前3个月向原审核机关提出延期申请，原审核同意机关应当在准予行政许可决定书有效期届满前作出是否准予延期的决定。建设项目在有效期内未取得建设用地批准文件也未申请延期的，准予行政许可决定书失效。"},{"i":26,"n":"第二十六条","txt":"《使用林地申请表》、《使用林地现场查验表》式样，由国家林业局统一规定。"},{"i":27,"n":"第二十七条","txt":"本办法所称Ⅰ、Ⅱ、Ⅲ、Ⅳ级保护林地，是指依据县级以上人民政府批准的林地保护利用规划确定的林地。 本办法所称国家级公益林林地，是指依据国家林业局、财政部的有关规定确定的公益林林地。"},{"i":28,"n":"第二十八条","txt":"本办法所称“以上”均包含本数，“以下”均不包含本数。"},{"i":29,"n":"第二十九条","txt":"本办法自2015年5月1日起施行。国家林业局于2001年1月4日发布、2011年1月25日修改的《占用征收征用林地审核审批管理办法》同时废止。"}],"kaizhanlinmuzhuanjiyingongchenghuodongshenpiguanli2dc4ef":[{"i":1,"n":"第一条","txt":"为了规范林木转基因工程活动审批行为，根据《中华人民共和国行政许可法》、《国务院对确需保留的行政审批项目设定行政许可的决定》（国务院令第412号），制定本办法。"},{"i":2,"n":"第二条","txt":"实施林木转基因工程活动的行政许可，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"本办法所称林木转基因工程活动，包括转基因林木的研究、试验、生产、经营和进出口活动。 本办法所称转基因林木，是指利用基因工程技术改变基因组构成，用于林业生产或者林产品加工的森林植物，主要包括： （一）转基因森林植物； （二）转基因森林植物产品； （三）转基因森林植物的直接加工品； （四）含有转基因森林植物及其产品成分的其他相关产品。"},{"i":4,"n":"第四条","txt":"国家林业局负责全国林木转基因工程活动安全监督管理工作；县级以上地方人民政府林业主管部门在上级林业主管部门的指导下负责本行政区域林木转基因工程活动安全监督管理工作。"},{"i":5,"n":"第五条","txt":"国家林业局成立林业生物基因安全委员会，为林木转基因工程活动的安全评价和监督管理提供科学咨询。"},{"i":6,"n":"第六条","txt":"开展林木转基因工程活动，应当符合林木转基因工程活动安全技术标准和技术规范，具备相适应的安全设施和措施，确保林木转基因工程活动的安全。 林木转基因工程活动安全的技术标准和技术规范由国家林业局制定。"},{"i":7,"n":"第七条","txt":"转基因林木的安全等级按照其对人类、动植物、微生物和生态环境可能造成的危险程度，分为以下三级： Ⅰ级：未发现危险； Ⅱ级：具有低度危险； Ⅲ级：具有高度危险。"},{"i":8,"n":"第八条","txt":"从事转基因林木研究和试验的单位，应当具备下列条件： （一）有从事转基因林木研究和试验的专业技术人员； （二）具备与研究和试验相适应的仪器设备和设施条件。 从事转基因林木研究和试验的单位应当制定本单位转基因林木安全管理制度，并成立转基因林木安全管理组织，负责本单位转基因林木研究和试验的安全工作。"},{"i":9,"n":"第九条","txt":"从事安全等级为Ⅲ级的转基因林木研究的，研究单位应当在研究开始前向国家林业局提出申请，并提交下列材料： （一）申请书； （二）转基因林木的安全等级和确定安全等级的依据； （三）与安全等级相适应的安全设施、安全管理和防范措施等情况的说明材料。"},{"i":10,"n":"第十条","txt":"转基因林木试验，一般分为中间试验、环境释放和生产性试验3个阶段。中间试验，是指在控制系统内或者控制条件下进行的小规模的试验。环境释放，是指在自然条件下采取相应安全措施所进行的中规模的试验。生产性试验，是指在生产和应用前进行的较大规模的试验。 转基因林木的环境释放和生产性试验可以同步进行。"},{"i":11,"n":"第十一条","txt":"转基因林木研究结束后，需要转入中间试验的，试验单位应当向国家林业局提出申请，并提交下列材料： （一）申请书； （二）研究总结报告（含分子鉴定、目标性状检测报告）； （三）转基因林木的安全等级和确定安全等级的依据； （四）相应的安全研究内容、安全管理和防范措施等情况的说明材料； （五）土地所有权人或者使用权人同意使用土地进行试验的证明材料。"},{"i":12,"n":"第十二条","txt":"转基因林木中间试验结束后，需要进行环境释放，或者同步进行环境释放和生产性试验的，以及在环境释放结束后需要转入生产性试验的，试验单位应当向国家林业局提出申请，并提交下列材料： （一）申请书； （二）转基因林木的安全等级和确定安全等级的依据； （三）相应的安全研究内容、安全管理和防范措施等情况的说明材料； （四）上一试验阶段总结报告（含试验情况、对生态环境等的影响）； （五）土地所有权人或者使用权人同意使用土地进行试验的证明材料。"},{"i":13,"n":"第十三条","txt":"申请安全等级为Ⅲ级的转基因林木研究，或者申请进行转基因林木试验，符合下列条件的，应当予以批准： （一）具有可靠的安全性评价； （二）具有符合安全等级要求的安全控制措施； （三）符合本办法第八条规定的条件； （四）符合国家有关法律、法规的规定。 批准开展转基因林木研究和试验的，应当对研究和试验的条件、步骤等作出具体规定。"},{"i":14,"n":"第十四条","txt":"生产性试验结束后，需要申请转基因林木安全证书的，试验单位应当向国家林业局提出申请，并提交下列材料： （一）申请书； （二）转基因林木的安全等级和确定安全等级的依据； （三）生产性试验阶段的总结报告（含试验情况、对生态环境的影响等）； （四）国家林业局公告规定的其他有关材料。 国家林业局应当组织林业生物基因安全委员会对转基因林木进行安全性评价。安全性评价合格的，经国家林业局综合考虑技术、经济、社会等因素后，发放转基因林木安全证书。"},{"i":15,"n":"第十五条","txt":"转基因林木安全证书应当载明证书编号、单位名称、转基因林木名称、外源基因、安全等级、规模范围、安全措施、安全责任人、有效期等内容。"},{"i":16,"n":"第十六条","txt":"用于生产、经营的转基因林木，应当取得转基因林木安全证书。 生产、经营转基因林木的单位和个人，应当按照转基因林木安全证书的要求从事生产、经营活动，并应当遵守《中华人民共和国种子法》、《中华人民共和国植物新品种保护条例》、《植物检疫条例》等相关法律法规的规定。 销售转基因林木种子的，应当用明显的文字标注，并提示使用时的安全控制措施。"},{"i":17,"n":"第十七条","txt":"拟从境外引进转基因林木用于研究、试验、生产或者经营的，应当向国家林业局提出申请，并提交下列材料： （一）申请书； （二）进口转基因林木安全管理登记表； （三）拟引进的转基因林木在境外已经进行相应研究、试验、生产或者经营的证明文件； （四）引进过程中拟采取的安全管理和防范措施，以及本单位转基因林木安全管理制度。 拟引进转基因林木用于生产、经营的，还应当提交输出国家或者地区经过科学试验未发现其对人类、动植物、微生物和生态环境有害的资料。 国家林业局应当组织林业生物基因安全委员会对拟从境外引进的转基因林木进行安全性评价后，作出行政许可决定。"},{"i":18,"n":"第十八条","txt":"从境外引进的转基因林木用于研究、试验、生产、经营，应当依照本办法的规定执行。"},{"i":19,"n":"第十九条","txt":"向境外出口转基因林产品，确需提供有关转基因林木证明的，国家林业局可以提供相关转基因林木的审批信息。"},{"i":20,"n":"第二十条","txt":"国家林业局收到开展林木转基因工程活动的有关申请后，对申请材料齐全、符合法定形式的，应当受理并出具《国家林业局行政许可受理通知书》；对不予受理的，应当告知申请人并说明理由，出具《国家林业局行政许可不予受理通知书》；对申请材料不齐或者不符合法定形式的，应当在5日内一次性告知申请人需要补正的全部内容，出具《国家林业局行政许可补正材料通知书》。"},{"i":21,"n":"第二十一条","txt":"国家林业局作出行政许可决定，需要组织专家评审论证或者委托检测机构对转基因林木进行检测的，应当自受理之日起10日内，出具《国家林业局行政许可需要听证、招标、拍卖、检验、检测、检疫、鉴定和专家评审通知书》，将专家评审论证和检测所需时间告知申请人。 专家评审论证和检测所需时间不计算在作出行政许可决定的期限内。"},{"i":22,"n":"第二十二条","txt":"国家林业局应当自受理之日起20日内作出是否准予行政许可的决定，出具《国家林业局准予行政许可决定书》或者《国家林业局不予行政许可决定书》，并告知申请人。"},{"i":23,"n":"第二十三条","txt":"在法定期限内不能作出行政许可决定的，经国家林业局主管负责人批准，国家林业局应当在法定期限届满前5个工作日办理《国家林业局行政许可延期通知书》，并告知申请人。"},{"i":24,"n":"第二十四条","txt":"开展林木转基因工程活动的行政许可工作，应当按照有关规定公示、公告。"},{"i":25,"n":"第二十五条","txt":"国家林业局应当组织县级以上地方人民政府林业主管部门对被许可人开展林木转基因工程活动的情况进行监督检查，并不定期组织专家进行安全监测。 国家林业局应当将开展林木转基因工程活动有关审批文件抄送相关省级人民政府林业主管部门，明确监督重点。县级以上地方人民政府林业主管部门应当按照要求开展监督工作，报告监督结果。 有关单位和个人对林业主管部门的监督检查，应当予以支持、配合，不得拒绝、阻碍监督检查人员依法执行职务。"},{"i":26,"n":"第二十六条","txt":"被许可人以欺骗、贿赂等不正当手段取得批准的，国家林业局应当依法撤销其开展林木转基因工程活动的行政许可，并予以公示、公告。 作出撤销行政许可决定的，国家林业局应当以书面形式通知被许可人，并告知其享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":27,"n":"第二十七条","txt":"违反本办法规定，开展林木转基因工程活动的，县级以上人民政府林业主管部门应当责令整改、给予警告，有违法所得的，可以并处违法所得1倍以上3倍以下且不超过3万元的罚款；没有违法所得的，属于非经营活动的，可以并处1千元以下罚款，属于经营活动的，可以并处1万元以下罚款。"},{"i":28,"n":"第二十八条","txt":"违反本办法规定开展林木转基因工程活动、拒不整改的，或者发现林木转基因工程活动对人类、动植物和生态环境存在危险时，国家林业局应当责令停止相关活动，撤销相关许可决定，注销转基因林木安全证书，销毁有关存在危险的转基因林木。"},{"i":29,"n":"第二十九条","txt":"国家林业局的有关工作人员在实施开展林木转基因工程活动审批的行政许可中，滥用职权、徇私舞弊的，依法给予处分；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"申请书等相关材料的格式，由国家林业局制定。"},{"i":31,"n":"第三十一条","txt":"本办法自2018年3月1日起施行。"}],"yinjinlushengyeshengdongwuwailaiwuzhongzhongleijis78aa4c":[{"i":1,"n":"第一条","txt":"为了加强陆生野生动物外来物种管理，防止陆生野生动物外来物种入侵，保护生物多样性，维护国土生态安全，根据《中华人民共和国行政许可法》、《国务院对确需保留的行政审批项目设定行政许可的决定》（国务院令第412号）和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"实施引进陆生野生动物外来物种种类及数量审批的行政许可事项，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"本办法所称陆生野生动物外来物种，是指自然分布在境外的陆生野生动物活体及繁殖材料。"},{"i":4,"n":"第四条","txt":"引进陆生野生动物外来物种的，应当采取安全可靠的防范措施，防止其逃逸、扩散，避免对自然生态造成危害。"},{"i":5,"n":"第五条","txt":"需要从境外引进陆生野生动物外来物种的，申请人应当提交下列材料： （一）申请报告、进出口申请表及进口目的的说明； （二）当事人签订的合同或者协议，属于委托引进的，还应当提供委托代理合同或者协议； （三）证明具备与引进陆生野生动物外来物种种类及数量相适应的人员和技术的有效文件或者材料，以及安全措施的说明。 申请首次引进境外陆生野生动物外来物种的，申请人还应当提交证明申请人身份的有效文件和拟进行隔离引种试验的实施方案。"},{"i":6,"n":"第六条","txt":"申请材料齐全且符合下列条件的，国家林业局应当作出准予行政许可的决定： （一）具备与引进陆生野生动物外来物种种类及数量相适应的人员和技术； （二）具备适宜商业性经营利用和科学研究外来物种的固定场所和必要设施； （三）有安全可靠的防逃逸管理措施； （四）具有相应的紧急事件处置措施。"},{"i":7,"n":"第七条","txt":"国家林业局在收到引进陆生野生动物外来物种种类及数量审批的申请后，对申请材料齐全、符合法定形式的，即时出具《国家林业局行政许可受理通知书》；对不予受理的，应当即时告知申请人并说明理由，出具《国家林业局行政许可不予受理通知书》；对申请材料不齐或者不符合法定形式的，应当在5日内出具《国家林业局行政许可补正材料通知书》，并一次性告知申请人需要补正的全部内容。"},{"i":8,"n":"第八条","txt":"国家林业局作出行政许可决定，需要举行听证或者组织专家评审的，应当自受理之日起10日内，出具《国家林业局行政许可需要听证、招标、拍卖、检验、检测、检疫、鉴定和专家评审通知书》，并将听证或者专家评审所需时间告知申请人。 听证和专家评审所需时间不计算在作出行政许可决定的期限内。"},{"i":9,"n":"第九条","txt":"国家林业局应当自受理之日起20日内作出是否准予行政许可的决定，出具《国家林业局准予行政许可决定书》或者《国家林业局不予行政许可决定书》，并告知申请人。 在法定期限内不能作出行政许可决定的，经国家林业局主管负责人批准，国家林业局应当在法定期限届满前5日办理《国家林业局行政许可延期通知书》，并告知申请人。"},{"i":10,"n":"第十条","txt":"准予首次引进境外陆生野生动物外来物种进行驯养繁殖的，应当进行隔离引种试验。 隔离引种试验由省、自治区、直辖市林业主管部门指定的科研机构或者专家进行评估，评估通过后方可继续引进和推广。 隔离引种试验应当包含中间试验。中间试验未获成功的，评估不得通过。 在自然保护区、自然保护小区、森林公园、风景名胜区以及自然生态环境特殊或者脆弱的区域，不得开展隔离引种试验。"},{"i":11,"n":"第十一条","txt":"禁止开展陆生野生动物外来物种的野外放生活动。 因科学研究、生物防治、野生动物种群结构调节等特殊情况，需要放生陆生野生动物外来物种的，应当按照《中华人民共和国陆生野生动物保护实施条例》的相关规定执行。"},{"i":12,"n":"第十二条","txt":"经批准从境外引进的陆生野生动物外来物种及其繁殖后代、产品应当依照国家有关规定进行标记。"},{"i":13,"n":"第十三条","txt":"陆生野生动物外来物种发生逃逸的，被许可人应当立即向当地林业主管部门报告，由当地林业主管部门责令其限期捕回或者采取其他补救措施。被责令限期捕回或者采取其他补救措施而拒绝执行的，当地林业主管部门或者其委托的单位可以代为捕回或者采取其他补救措施，并由被许可人承担全部捕回或者采取其他补救措施所需的经费；造成损害的，依照有关法律法规承担法律责任。"},{"i":14,"n":"第十四条","txt":"依法查没的陆生野生动物外来物种，应当由当地县级以上林业主管部门按照国家有关规定处理。"},{"i":15,"n":"第十五条","txt":"国家林业局成立陆生野生动物外来物种咨询科学委员会，负责陆生野生动物外来物种管理的科学论证、评估和咨询。"},{"i":16,"n":"第十六条","txt":"各级林业主管部门应当建立防范陆生野生动物外来物种入侵的预警和应急防范机制。 在野外发现陆生野生动物外来物种的，当地林业主管部门应当立即向同级人民政府和上级林业主管部门报告，并会同有关部门采取监测和防治措施。"},{"i":17,"n":"第十七条","txt":"省、自治区、直辖市之间引进本行政区域内没有天然分布的陆生野生动物外来物种的，按照国家和省、自治区、直辖市的相关规定办理。"},{"i":18,"n":"第十八条","txt":"引进的陆生野生动物属于中国参加的国际公约限制进出口的濒危物种的，必须向国家濒危物种进出口管理机构申请办理允许进出口证明书。"},{"i":19,"n":"第十九条","txt":"本办法自2005年11月1日起施行。"}],"pujixingguowaiyinzhongshizhongmiaopuzigerendingguaeffbb8":[{"i":1,"n":"第一条","txt":"为了防止外来林业有害生物传入国境，规范普及型国外引种试种苗圃资格认定活动，根据《中华人民共和国行政许可法》、《国务院对确需保留的行政审批项目设定行政许可的决定》（国务院令第412号）和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"实施普及型国外引种试种苗圃资格认定的行政许可，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"从事林木种子、苗木和其他繁殖材料生产、经营的单位或者个人，可以申请普及型国外引种试种苗圃资格认定。"},{"i":4,"n":"第四条","txt":"申请普及型国外引种试种苗圃资格认定，应当具备以下条件： （一）苗圃周围一定距离内无与所引种试种植物同科、同属的植物； （二）具有围墙、防疫沟等引种试种隔离条件； （三）具有检疫和除治病虫害的设施、设备； （四）引种试种的管理措施和制度健全； （五）配备林业有害生物防治专业技术人员； （六）苗圃地使用权期限不少于3年。"},{"i":5,"n":"第五条","txt":"申请普及型国外引种试种苗圃资格认定，应当提交以下材料： （一）普及型国外引种试种苗圃资格申请表； （二）从事主要林木种子生产和林木种子经营的，应当提供《林木种子生产经营许可证》复印件； （三）符合本办法第四条规定条件的证明材料。"},{"i":6,"n":"第六条","txt":"国家林业局应当在收到普及型国外引种试种苗圃资格认定申请后，对申请材料齐全、符合法定形式的，即时出具《国家林业局行政许可受理通知书》；对不予受理的，应当即时告知申请人并说明理由，出具《国家林业局行政许可不予受理通知书》；对申请材料不齐或者不符合法定形式的，应当在5日内出具《国家林业局行政许可补正材料通知书》，并一次性告知申请人需要补正的全部内容。"},{"i":7,"n":"第七条","txt":"国家林业局受理普及型国外引种试种苗圃资格认定的申请，需要对申请材料的实质内容进行核实的，应当指派两名以上工作人员进行调查，并告知申请人。 进行调查所需时间，不计算在作出行政许可决定的期限内。"},{"i":8,"n":"第八条","txt":"国家林业局应当自受理申请之日起20日内作出是否准予行政许可的决定，出具《国家林业局准予行政许可决定书》或者《国家林业局不予行政许可决定书》，并告知申请人。"},{"i":9,"n":"第九条","txt":"在法定期限内不能作出行政许可决定的，经国家林业局主管负责人批准，国家林业局应当在法定期限届满前5日办理《国家林业局行政许可延期通知书》，并告知申请人。"},{"i":10,"n":"第十条","txt":"普及型国外引种试种苗圃资格的行政许可决定，应当以适当的方式公示、公告，公众有权查阅。"},{"i":11,"n":"第十一条","txt":"国家林业局应当依法对被许可人从事行政许可事项的活动进行监督检查。"},{"i":12,"n":"第十二条","txt":"被许可人违反法律、法规的规定，致使外来林业有害生物传播蔓延的，应当按照有关法律、法规的规定予以处罚。"},{"i":13,"n":"第十三条","txt":"被许可人以欺骗、贿赂等不正当手段取得普及型国外引种试种苗圃资格的，国家林业局应当依法撤销，并予以公示、公告。 作出撤销行政许可决定的，国家林业局应当以书面形式通知被许可人，并告知其享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":14,"n":"第十四条","txt":"国家林业局的有关工作人员在实施普及型国外引种试种苗圃资格认定的行政许可中，滥用职权、徇私舞弊的，依法给予行政处分；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":15,"n":"第十五条","txt":"本办法自2005年11月1日起施行。"}],"songcaixianchongbingyimujiagongbancaidingdianjiago3847a0":[{"i":1,"n":"第一条","txt":"为了预防和除治松材线虫病，规范松材线虫病疫木加工板材定点加工企业审批行为，根据《中华人民共和国行政许可法》、《国务院对确需保留的行政审批项目设定行政许可的决定》（国务院令第412号）和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"实施松材线虫病疫木加工板材定点加工企业审批的行政许可，应当遵守本办法。 松材线虫病疫木，是指松材线虫病疫区内的松科植物。 松材线虫病疫区，由省、自治区、直辖市人民政府或者国家林业局依法划定。"},{"i":3,"n":"第三条","txt":"从事木材经营加工的企业，可以申请松材线虫病疫木加工板材定点加工企业资格。"},{"i":4,"n":"第四条","txt":"申请松材线虫病疫木加工板材定点加工企业资格，应当具备以下条件： （一）具有符合疫木加工板材要求和标准的生产设施； （二）疫木板材加工工艺流程符合疫木除害处理要求； （三）疫木板材加工管理措施和制度健全。"},{"i":5,"n":"第五条","txt":"申请松材线虫病疫木加工板材定点加工企业资格，应当提交以下材料： （一）申请报告； （二）营业执照、木材经营加工资格批准文件的复印件； （三）符合本办法第四条规定条件的证明材料。"},{"i":6,"n":"第六条","txt":"国家林业局应当在收到松材线虫病疫木加工板材定点加工企业资格申请后，对申请材料齐全、符合法定形式的，即时出具《国家林业局行政许可受理通知书》；对不予受理的，应当即时告知申请人并说明理由，出具《国家林业局行政许可不予受理通知书》；对申请材料不齐或者不符合法定形式的，应当在5日内出具《国家林业局行政许可补正材料通知书》，并一次性告知申请人需要补正的全部内容。"},{"i":7,"n":"第七条","txt":"国家林业局作出行政许可决定，需要组织专家评审论证的，应当自受理之日起10日内，出具《国家林业局行政许可需要听证、招标、拍卖、检验、检测、检疫、鉴定和专家评审通知书》，将专家评审论证所需时间告知申请人。 专家评审论证所需时间不计算在作出行政许可决定的期限内。"},{"i":8,"n":"第八条","txt":"国家林业局应当自受理申请之日起20日内作出是否准予行政许可的决定，出具《国家林业局准予行政许可决定书》或者《国家林业局不予行政许可决定书》并告知申请人。"},{"i":9,"n":"第九条","txt":"在法定期限内不能作出行政许可决定的，经国家林业局主管负责人批准，国家林业局应当在法定期限届满前5日办理《国家林业局行政许可延期通知书》，并告知申请人。"},{"i":10,"n":"第十条","txt":"松材线虫病疫木加工板材定点加工企业资格的行政许可决定，应当以适当的方式公示、公告，公众有权查阅。"},{"i":11,"n":"第十一条","txt":"国家林业局应当依法对被许可人的松材线虫病疫木加工情况进行监督检查。"},{"i":12,"n":"第十二条","txt":"被许可人未按照法律、法规的规定或者有关标准加工松材线虫病疫木板材的，应当按照有关法律、法规的规定予以行政处罚。"},{"i":13,"n":"第十三条","txt":"被许可人以欺骗、贿赂等不正当手段取得松材线虫病疫木加工板材定点加工企业资格的，国家林业局应当依法撤销，并予以公示、公告。 作出撤销行政许可决定的，国家林业局应当以书面形式通知被许可人，并告知其享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":14,"n":"第十四条","txt":"国家林业局的有关工作人员在实施松材线虫病疫木加工板材定点加工企业审批的行政许可中，滥用职权、徇私舞弊的，依法给予行政处分；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":15,"n":"第十五条","txt":"本办法自2005年11月1日起施行。"}],"linyegongzuozhanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强林业工作站的建设与管理，发挥林业工作站在发展林业中的作用，根据《中华人民共和国森林法》、《中华人民共和国农业技术推广法》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"林业工作站的建设和管理，适用本办法。"},{"i":3,"n":"第三条","txt":"林业工作站是设在乡镇的基层林业工作机构，依法对森林、野生动植物资源实行管理和监督，组织和指导农村林业生产经营组织和个人发展林业生产，开展林业社会化服务。"},{"i":4,"n":"第四条","txt":"林业工作站由县级林业主管部门直接领导或者实行由县级林业主管部门和所在地乡镇人民政府双重领导的管理体制。"},{"i":5,"n":"第五条","txt":"国家林业局主管全国林业工作站的建设和管理工作，具体工作由其设立的林业工作站管理总站负责。 县级以上地方林业主管部门主管本行政区域内林业工作站的建设和管理工作，具体工作由其设立或者确定的林业工作站管理机构负责。"},{"i":6,"n":"第六条","txt":"林业工作站承担政策宣传、资源管理、林政执法、生产组织、科技推广和社会化服务等职能,具体职责是： （一）宣传与贯彻执行森林、野生动植物资源保护等法律、法规和各项林业方针、政策； （二）协助县级林业主管部门和乡镇人民政府制定和落实林业发展规划； （三）配合县级林业主管部门开展资源调查、档案管理、造林检查验收、林业统计等工作； （四）协助县级林业主管部门或者乡镇人民政府开展林木采伐等行政许可受理、审核和发证工作； （五）配合县级林业主管部门或者乡镇人民政府开展森林防火、林业有害生物防治、陆生野生动物疫源疫病防控、森林保险和林业重点建设工程等工作； （六）协助有关部门处理森林、林木和林地所有权或者使用权争议，查处破坏森林和野生动植物资源案件； （七）配合乡镇人民政府建立健全乡村护林网络和管理乡村护林队伍； （八）推广林业科学技术，开展林业技术培训、技术咨询和技术服务等林业社会化服务； （九）承"},{"i":7,"n":"第七条","txt":"有林业生产和经营管理任务的地方，应当在乡镇设立林业工作站；林业生产和经营管理任务相对较轻的地方，可以设立区域林业工作站。 不具备设立林业工作站条件的，乡镇人民政府应当依法设专职或者兼职人员负责林业工作。"},{"i":8,"n":"第八条","txt":"林业工作站的设立，由县级林业主管部门提出意见或者由县级林业主管部门与当地乡镇人民政府协商后提出意见，按照有关规定报县级人民政府或者有关机构批准。"},{"i":9,"n":"第九条","txt":"林业工作站工作人员的编制，由县级林业主管部门根据国家有关规定和当地实际情况，商机构编制部门确定。 林业工作站新进人员应当主要接收大中专院校毕业生，实行公开招聘，采取考试与考核相结合的办法，择优聘用。"},{"i":10,"n":"第十条","txt":"林业工作站应当设立符合工作需要的专业技术岗位。专业技术人员应当具有相应的专业技术水平，符合岗位职责要求。 林业工作站新进专业技术人员，应当具备大中专以上专业学历。"},{"i":11,"n":"第十一条","txt":"国家对林业工作站的建设给予适当扶持。林业工作站所需事业经费，根据国家有关规定纳入地方预算。 林业工作站承担林业重点工程项目等专项任务的，下达专项任务的部门或者单位应当按照有关规定列支必要的专项工作经费。"},{"i":12,"n":"第十二条","txt":"林业工作站应当具有必要的房屋、交通、通讯工具等设施。 任何单位和个人不得非法侵占、平调、拍卖或者出租林业工作站的房屋、交通、通讯工具等设施和其他资产。"},{"i":13,"n":"第十三条","txt":"林业工作站的撤销或者变更，由县级林业主管部门提出意见或者由县级林业主管部门与当地乡镇人民政府协商后提出意见，报原批准设立的机关批准。"},{"i":14,"n":"第十四条","txt":"林业工作站负责人的任免，由县级林业主管部门负责或者按照所在地人事管理规定办理。"},{"i":15,"n":"第十五条","txt":"县级以上地方林业主管部门应当有计划地对林业工作站的工作人员进行业务培训。 对达到相应技术水平的林业工作站人员，应当按照国家有关规定聘任相应的技术职务。"},{"i":16,"n":"第十六条","txt":"林业工作站应当建立健全岗位责任制、目标管理责任制和技术承包责任制，制定和完善各项工作制度。"},{"i":17,"n":"第十七条","txt":"林业工作站应当建立健全人事、财务会计、国有资产管理以及廉政建设等各项制度，并接受县级林业主管部门或者乡镇人民政府的监督和检查。"},{"i":18,"n":"第十八条","txt":"县级以上地方林业主管部门应当在同级人民政府的指导下，采取措施，保障和改善林业工作站工作人员的工作条件、生活条件和待遇，并按照国家规定给予补贴。"},{"i":19,"n":"第十九条","txt":"对成绩显著的林业工作站及其工作人员，应当给予奖励。"},{"i":20,"n":"第二十条","txt":"对有滥用职权、徇私舞弊、索贿受贿或者玩忽职守等行为的林业工作站工作人员，依照国家有关规定处理。"},{"i":21,"n":"第二十一条","txt":"新疆生产建设兵团设立的团场林业工作站以及国有农场设立的林业工作站的建设与管理，参照本办法执行。"},{"i":22,"n":"第二十二条","txt":"本办法自2016年1月1日起施行。2000年3月13日国家林业局发布的《林业工作站管理办法》同时废止。"}],"linyexingzhengchufatingzhengguize":[{"i":1,"n":"第一条","txt":"为了规范林业行政处罚听证行为，保障林业行政主管部门正确实施林业行政处罚，保护当事人的合法权益，根据《中华人民共和国行政处罚法》和国务院的有关规定，制定本规则。"},{"i":2,"n":"第二条","txt":"林业行政主管部门举行林业行政处罚听证，适用本规则。 本规则所称听证，是指林业行政主管部门对属于听证范围的林业行政处罚案件在作出行政处罚前，依法听取听证参加人的陈述、申辩和质证的程序。"},{"i":3,"n":"第三条","txt":"林业行政主管部门举行听证，应当遵循下列规定： （一）保障和便利当事人行使陈述权、申辩权和质证权； （二）公开、公正、效率； （三）不得向当事人收取组织听证的费用。"},{"i":4,"n":"第四条","txt":"听证由作出行政处罚的林业行政主管部门组织，具体实施工作由其法制工作机构负责。法制工作机构与执法机构为同一机构或者没有设立专门法制工作机构的，应当遵循听证与案件调查取证职责分离的原则，由林业行政主管部门行政负责人指定非本案调查人员主持听证。 受委托行使林业行政处罚权的组织作出行政处罚前需要举行听证的，由委托的行政机关组织。"},{"i":5,"n":"第五条","txt":"林业行政主管部门依法作出责令停产停业、吊销许可证或者执照、较大数额罚款等林业行政处罚决定之前，应当告知当事人有要求举行听证的权利，并制作林业行政处罚听证权利告知书。 前款所称较大数额的罚款，按照省、自治区、直辖市人大常委会或者省级人民政府的规定执行。 国家林业局依法作出十万元以上（含十万元）罚款决定的，应当告知当事人有要求举行听证的权利。"},{"i":6,"n":"第六条","txt":"林业行政处罚听证权利告知书应当包括下列内容： （一）当事人的姓名或者名称； （二）当事人的违法事实； （三）拟作出的林业行政处罚决定、理由和依据； （四）当事人享有要求听证的权利、提出听证的期限和组织听证的机关。"},{"i":7,"n":"第七条","txt":"当事人要求举行听证的，应当在林业行政主管部门告知之日起三日内提出书面申请或者口头申请；口头申请的，林业行政主管部门应当制作笔录，并由当事人签字或者盖章。 当事人自林业行政主管部门告知之日起三日内未提出听证申请的，视为放弃要求举行听证的权利，由林业行政主管部门记录附卷。"},{"i":8,"n":"第八条","txt":"林业行政主管部门收到听证申请后，应当在五日内进行审查。对符合听证规定的，应当受理；对不符合听证规定的，决定不予受理，并告知当事人。"},{"i":9,"n":"第九条","txt":"本规则所称听证参加人，是指林业行政处罚案件的案件调查人员、当事人及其代理人、第三人及其代理人。 当事人是指要求举行听证的公民、法人或者其他组织。 第三人是指向听证主持人申请要求参加听证的，或者由听证主持人通知其参加听证、与所听证的案件有利害关系的公民、法人或者其他组织。"},{"i":10,"n":"第十条","txt":"林业行政主管部门应当指定一至三人担任听证主持人。听证主持人为两人以上的，应当指定其中一人为首席听证主持人。 听证主持人应当指定本部门的一名工作人员作为书记员，具体承担听证准备和听证记录工作。"},{"i":11,"n":"第十一条","txt":"听证主持人有下列情形之一的，应当自行回避；当事人有权申请回避： （一）参与本案调查取证的； （二）与本案当事人或者与当事人的近亲属有利害关系的； （三）与案件处理结果有利害关系，可能影响对案件公正听证的。 前款规定，适用于书记员、翻译人员、鉴定人。 听证主持人的回避由林业行政主管部门行政负责人决定。书记员、翻译人员、鉴定人的回避由听证主持人或者首席听证主持人决定。"},{"i":12,"n":"第十二条","txt":"听证主持人行使下列职权： （一）决定举行听证的时间、地点； （二）按照程序主持听证； （三）要求听证参加人提供或者补充证据； （四）就案件的事实和适用的法律进行询问； （五）维护听证秩序，对违反听证秩序的人员进行警告或者批评； （六）按规定决定听证的延期、中止或者终结； （七）就案件的处理向林业行政主管部门行政负责人提出书面建议； （八）本规则赋予的其他职权。"},{"i":13,"n":"第十三条","txt":"听证主持人承担下列义务： （一）公正地履行主持听证的职责，不得妨碍听证参加人行使陈述权、申辩权和质证权，不得徇私枉法，包庇纵容违法行为； （二）根据听证认定的证据，依法独立、客观、公正地作出判断并写出书面建议。"},{"i":14,"n":"第十四条","txt":"当事人、第三人可以委托一至二人代理参加听证。 委托他人代理参加听证的，应当向林业行政主管部门提交由委托人签名或者盖章的授权委托书。 授权委托书应当载明委托事项及权限，委托代理人代为放弃行使听证权的，必须有委托人的特别授权。"},{"i":15,"n":"第十五条","txt":"案件调查人员应当参加听证。"},{"i":16,"n":"第十六条","txt":"当事人依法享有下列权利： （一）质证权，就本案的证据向调查人员及证人提出问题并进行对质的权利； （二）申辩权，就本案的事实与法律问题进行申述、辩解的权利； （三）最后陈述权，听证结束前就本案的事实、法律及处理进行最后陈述的权利。"},{"i":17,"n":"第十七条","txt":"当事人依法承担下列义务： （一）按时参加听证； （二）如实回答听证主持人的询问； （三）遵守听证纪律。"},{"i":18,"n":"第十八条","txt":"林业行政主管部门应当自决定受理听证申请之日起三日内，确定听证主持人或者首席听证主持人。"},{"i":19,"n":"第十九条","txt":"案件调查人员应当按照听证主持人的要求在三日内将案卷移送听证主持人。"},{"i":20,"n":"第二十条","txt":"听证主持人应当自接到案件调查人员移送的案卷之日起五日内确定听证的时间、地点，并应当在举行听证七日前，将举行听证的时间、地点通知当事人和案件调查人员。通知案件调查人员时，应当同时退回案卷。 听证应当在受理听证申请之日起二十日内举行。"},{"i":21,"n":"第二十一条","txt":"除涉及国家秘密、商业秘密或者个人隐私外，听证应当公开举行。 公开举行听证的，应当公开当事人姓名或者名称，案由以及举行听证的时间和地点。"},{"i":22,"n":"第二十二条","txt":"听证由听证主持人主持，设有首席听证主持人的，由首席听证主持人主持。"},{"i":23,"n":"第二十三条","txt":"当事人无正当理由拒不到场，又未委托代理人到场参加听证的，或者未经听证主持人允许中途退场的，视为放弃听证权。 案件调查人员无正当理由拒不到场参加听证的，或者未经听证主持人允许中途退场的，听证主持人有权责令其到场参加听证；案件调查人员拒不到场参加听证的，不得对当事人作出林业行政处罚决定。"},{"i":24,"n":"第二十四条","txt":"参加听证应当遵守下列纪律： （一）未经听证主持人允许，不得发言、提问； （二）未经听证主持人允许，不得录音、录像和摄影； （三）未经听证主持人允许，听证参加人不得中途退场； （四）不得使用侮辱性和其他不文明语言； （五）在听证会场不得使用通讯工具，不得鼓掌、喧哗、吵闹或者进行其他妨碍听证活动的行为。 对违反听证纪律的，听证主持人有权予以制止；情节严重的，可以责令退出听证会场。"},{"i":25,"n":"第二十五条","txt":"听证应当按照下列程序进行： （一）由听证主持人宣布听证开始，宣布听证纪律，核对听证参加人身份，宣布案由，宣布听证主持人、书记员、翻译人员名单； （二）告知听证参加人在听证中的权利和义务，询问当事人是否申请回避； （三）案件调查人员提出当事人违法的事实、证据，适用的法律、法规或者规章，以及拟作出的林业行政处罚决定； （四）当事人或者其代理人就案件事实进行申辩，并提交证据材料； （五）第三人或者其代理人进行陈述； （六）询问当事人或者其代理人、案件调查人员、证人和其他有关人员，并对有关证据材料进行质证； （七）当事人或者其代理人和案件调查人员就本案的事实和法律问题进行辩论； （八）当事人最后陈述； （九）听证主持人宣布听证结束。"},{"i":26,"n":"第二十六条","txt":"有下列情形之一的，可以延期举行听证： （一）当事人因不可抗力无法到场的； （二）当事人临时提出回避申请，需要重新确定听证主持人的； （三）发现有新的重要事实需要调查核实的； （四）其他应当延期的情形。"},{"i":27,"n":"第二十七条","txt":"有下列情形之一的，可以中止听证： （一）当事人死亡或者解散，需要确定权利义务继承人的； （二）当事人或者案件调查人员因不可抗拒的理由，无法继续参加听证的； （三）需要通知新的证人到场或者需要对有关证据重新调查、鉴定的； （四）其他需要中止听证的情形。 中止听证的情形消除后，听证主持人应当恢复听证。"},{"i":28,"n":"第二十八条","txt":"有下列情形之一的，应当终止听证： （一）当事人死亡或者解散三个月后，未确定权利义务继承人的； （二）当事人无正当理由，不参加或者中途退出听证的； （三）其他需要终止听证的情形。"},{"i":29,"n":"第二十九条","txt":"听证应当制作林业行政处罚听证笔录，由听证主持人和书记员签字。 听证笔录在听证结束后，应当交由听证参加人审核无误或者补正后，由听证参加人当场签字或者盖章。拒绝签字或者盖章的，由听证主持人记明情况，在听证笔录中予以载明。"},{"i":30,"n":"第三十条","txt":"所有与认定案件事实相关的证据都必须在听证中出示，并通过质证进行认定；未经质证认定的证据不得作为林业行政处罚的依据。"},{"i":31,"n":"第三十一条","txt":"听证结束后，听证主持人应当根据听证确定的事实和证据，依照有关法律、法规、规章对原拟作出的处罚决定及其事实、理由和依据进行复核，向林业行政主管部门行政负责人提出对听证案件处理的听证报告。 林业行政主管部门应当根据听证报告确定的事实、证据和给予处罚的依据，依据《中华人民共和国行政处罚法》第三十八条的规定作出决定。"},{"i":32,"n":"第三十二条","txt":"听证报告应当包括以下内容： （一）听证的案由； （二）听证主持人和听证参加人的基本情况； （三）听证的时间、地点； （四）听证认定的案件事实、证据； （五）给予处罚的依据； （六）处理意见和建议。"},{"i":33,"n":"第三十三条","txt":"森林公安机关、森林植物检疫机构、自然保护区管理机构等依法以自己的名义作出林业行政处罚的单位举行听证的，由该单位依照本规则的规定自行组织。"},{"i":34,"n":"第三十四条","txt":"林业行政主管部门依照《中华人民共和国森林法》第三十四条第二款作出收缴采伐许可证、中止林木采伐的行政措施，不适用本规则的规定。"},{"i":35,"n":"第三十五条","txt":"本规则所规定的林业行政处罚听证文书的送达，依照民事诉讼法的有关规定办理。"},{"i":36,"n":"第三十六条","txt":"林业行政主管部门应当保障听证经费，提供组织听证所必需的场地、设备以及其他便利条件。"},{"i":37,"n":"第三十七条","txt":"本规则由国家林业局负责解释。"},{"i":38,"n":"第三十八条","txt":"本规则自2002年12月15日起施行。"}],"linyexingzhengchufaanjianwenshuzhizuoguanliguiding":[{"i":1,"n":"第一条","txt":"为了规范林业行政处罚案件文书制作，正确实施林业行政处罚，保障公民、法人和其他组织的合法权益，根据《中华人民共和国行政处罚法》和《林业行政处罚程序规定》等有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"制作林业行政处罚案件文书，适用本规定。"},{"i":3,"n":"第三条","txt":"林业行政处罚案件文书格式由国家林业局统一制定。省、自治区、直辖市林业主管部门根据需要补充制定相应文书格式的，应当报国家林业局备案。法律、法规对文书格式另有规定的，从其规定。"},{"i":4,"n":"第四条","txt":"林业行政处罚案件文书由省、自治区、直辖市林业主管部门统一印制、统一管理。 采用计算机印制方式制作林业行政处罚案件文书的，应当符合规定的格式，并经省、自治区、直辖市林业主管部门同意。"},{"i":5,"n":"第五条","txt":"制作林业行政处罚案件文书，应当内容完整、准确，填写字迹清楚、文字规范、文面清洁。"},{"i":6,"n":"第六条","txt":"林业行政处罚案件文书应当用蓝色、黑色的水笔或者签字笔填写。用计算机制作的，可以用打印方式填写。 填写林业行政处罚案件文书因书写错误需要进行修改的，可以用杠线划去修改处，在其上方或者接下处写上正确内容，并在改动处加盖修正专用印章，或者由当事人签名、盖章。"},{"i":7,"n":"第七条","txt":"林业行政处罚案件文书首页不够记录的，可以附页。附页应当加盖印章并经当事人签字。"},{"i":8,"n":"第八条","txt":"林业行政处罚询问笔录、勘验、检查笔录、听证会笔录等文书，在当场交由有关当事人审阅或者向当事人宣读后，由当事人在笔录上书写“以上笔录属实”并签字确认。当事人认为记录有遗漏或者有差错的，应当予以补充或者修改，并在改动处签名或者盖章。"},{"i":9,"n":"第九条","txt":"林业行政处罚案件文书中有关同类栏目的填写要求如下： （一）“案件性质”栏目，填写对违反林业法律、法规、规章的行为进行定性确认的案件类别，如盗伐林木案件、无木材运输证运输木材案件等。 （二）“简要案情”栏目，应当根据案件来源材料或者经过调查取证、审查认定的情况，用准确、简练的语言文字，将案件发生的时间、地点、当事人和案件事实经过、后果等情况概括清楚。"},{"i":10,"n":"第十条","txt":"林业行政处罚当场处罚决定书，适用于案情简单、违法事实清楚、证据确凿、依法可以当场作出林业行政处罚决定的违法案件。 “违法事实”栏目，应当填写违法行为发生的时间和违法行为实施或者行为后果发生的地点，简明、扼要叙述违法事实的经过。 填写适用的法律、法规、规章应当列明具体条款，可以不写条款的具体内容。 填写处罚内容应当具体明确。 林业行政处罚当场处罚决定书可以事先加盖处罚机关的印章。"},{"i":11,"n":"第十一条","txt":"林业行政处罚立案登记表，是林业主管部门依据法律、法规、规章的规定，对涉嫌违法行为是否立案报送行政机关负责人审批的文书。 “案件来源”栏目，按照本机关发现、单位或者群众举报、受害人控告、有关单位移送、上级机关交办和违法行为人主动交代等据实填写。 “受案人意见”栏目，填写受案人根据案情提出立案或者不予立案等意见，并签名、署明提出意见的日期。 “行政机关负责人批示”栏目，填写行政机关负责人对受案人意见进行审查后，批示立案或者不予立案等内容，并签名、署明批示的日期。"},{"i":12,"n":"第十二条","txt":"林业行政处罚登记保存通知单，是林业主管部门在办理林业行政处罚案件中，认为证据可能灭失或者以后难以取得的，经行政机关负责人批准，对证据实施登记保存的文书。 “被登记保存人”栏目，填写内容应当完整、详细，以便查找。 登记保存原因是发现被登记保存人所持有的“物品”属涉案的重要证据，有登记保存必要；适用法律、法规、规章的依据是《中华人民共和国行政处罚法》第三十七条第二款或者《林业行政处罚程序规定》第二十六条。 “物品”栏目的名称、数量、计量单位、登记保存地点应当具体明确。 登记保存单位的印章，必须使用行政机关或者法律、法规授权的组织的印章。"},{"i":13,"n":"第十三条","txt":"林业行政处罚询问笔录，是为了查明案件事实，收集证据，向案件当事人、证人或者其他有关人员调查了解有关情况时所作记录的文书。 询问内容，应当记录被询问人提供的与案件有关的全部情况，包括案件发生的时间、地点、事实经过、因果关系、后果等。记录应当准确真实，不得使用推测性词语，涉及案件主要事实和重要线索的内容应当完整记录。"},{"i":14,"n":"第十四条","txt":"林业行政处罚勘验、检查笔录，是林业行政执法人员对与案件有关的场所、物品等进行勘验或者检查所作文字记载的文书。 “勘验、检查地点”栏目，应当写清具体的地点和方位。 “勘验、检查事项及结果”栏目，应当按照勘验、检查的顺序，全面客观地记录；对现场位置、周围环境、现场状况以及其他与案件相关的情况作详尽的记录。"},{"i":15,"n":"第十五条","txt":"林业行政处罚意见书，是林业行政执法人员在案件调查结束时，对案件提出如何处理的具体意见的文书。 “执法人”栏目，填写本案主办人员的姓名，不能少于2人。 “查处时间”栏目，填写自立案之日起至提出处罚意见之日止。 “违法行为人”栏目，按调查掌握的实际情况详细填写。 “执法人意见”栏目，应当写明所依据的法律、法规、规章的条、款、项、目和拟定的处理意见，由本案林业行政执法人员签名或者加盖本案主办机构的印章。 “法制工作机构意见”栏目，应当写明具体审核意见，由审核人签名或者加盖法制工作机构的印章。"},{"i":16,"n":"第十六条","txt":"林业行政处罚决定书，是对违反林业法律、法规、规章的违法行为人，依法作出行政处罚决定并送达违法行为人的文书。 “违法事实和证据”栏目中的“证据”，填写调查获取的证据种类。 所依据的法律、法规、规章，应当写明条、款、项、目。 决定给予的行政处罚，应当主次分明并写明处罚种类、数额。 罚款履行方式，应当填写指定的收款银行名称和帐号，不能空格不填，但依法当场收缴罚款的除外。 行政复议机关的名称应当填写全称；向行政机关所在地人民法院起诉的期限是3个月，法律有特别规定的，从其规定。 “承办人”栏目，应当填写负责查处本案的2名以上林业行政执法人员的姓名。"},{"i":17,"n":"第十七条","txt":"林业行政处罚文书送达回证，是将林业行政处罚当场处罚决定书交付当事人或者将林业行政处罚决定书交付、送达当事人，证明当事人已经收到的法律文书。 因受送达人拒收、拒绝签名、盖章，或者代收人拒绝代收、拒绝签名、盖章而留置送达的，以及委托送达、邮寄送达、转交送达和公告送达的，应当在“备注”栏内注明。"},{"i":18,"n":"第十八条","txt":"林业行政处罚罚没实物收据，是根据依法作出的行政处罚决定，记录被处罚人的被罚没实物的文书。 罚没内容应当将实物名称、规格、数量等记录清楚。"},{"i":19,"n":"第十九条","txt":"暂扣木材通知单，是负责检查木材运输的木材检查站对无证运输的木材予以暂扣的文书。 暂扣木材的原因是无木材运输证运输木材，适用法律的依据是《中华人民共和国森林法实施条例》第三十七条。"},{"i":20,"n":"第二十条","txt":"林业行政处罚委托书，是林业主管部门依照法律、法规或者规章的规定，在其法定职责内，委托符合《中华人民共和国行政处罚法》第十九条规定条件的组织，实施林业行政处罚的文书。 委托的内容，应当分别填写所依据的法律、法规、规章的条、款、项、目。"},{"i":21,"n":"第二十一条","txt":"林业行政处罚听证权利告知书，是对适用听证程序的林业行政处罚案件作出行政处罚决定前，向当事人告知有权要求举行听证的文书。 告知书应当写明违法行为，违反的法律、法规、规章条款，拟作出的行政处罚决定的法律依据、行政处罚的种类和数额，听证机关的地址、邮政编码、联系电话、联系人等。"},{"i":22,"n":"第二十二条","txt":"林业行政处罚听证申请笔录，是在当事人收到林业行政处罚听证权利告知书后要求听证，记录当事人的听证请求、申请听证的事实和理由的文书。"},{"i":23,"n":"第二十三条","txt":"林业行政处罚听证案件不予受理通知书，是负责进行听证的林业主管部门对当事人的林业行政处罚听证申请笔录进行审查后，认为不符合听证条件而决定不予受理的文书。"},{"i":24,"n":"第二十四条","txt":"听证通知书，是由有权要求举行听证的当事人提出，林业主管部门向当事人发出的决定举行听证的书面通知文书。"},{"i":25,"n":"第二十五条","txt":"林业行政处罚听证会笔录，是对听证过程和内容进行记录的文书。 “委托代理人”栏目，应当写明代理人的姓名、性别、工作单位等。 “听证内容记录”栏目，应当写明当事人提出的主要事实和证据，第三人提出的与本案有关的观点和证据，鉴定和勘验结论，案件承办人提出的事实、证据和行政处罚建议等。"},{"i":26,"n":"第二十六条","txt":"本规定自2005年7月1日起施行。"}],"linyexingzhengchufachengxuguiding":[{"i":1,"n":"第一条","txt":"为了规范林业行政处罚，保障和监督林业行政主管部门有效实施行政管理，维护公共利益和社会秩序，保护公民、法人或者其他组织的合法权益，根据有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"依法实施林业行政处罚适用本规定。"},{"i":3,"n":"第三条","txt":"实施林业行政处罚必须以事实为依据，以法律为准绳，遵循公正、公开、及时的原则。 实施林业行政处罚，纠正违法行为，应当坚持处罚与教育相结合，教育公民、法人或者其他组织自觉守法。"},{"i":4,"n":"第四条","txt":"公民、法人或者其他组织对林业行政主管部门所给予的林业行政处罚，享有陈述权、申辩权；对林业行政处罚不服的，有权依法申请行政复议或者提起行政诉讼。 公民、法人或者其他组织因林业行政主管部门违法给予行政处罚受到损害的，有权依法提出赔偿要求。"},{"i":5,"n":"第五条","txt":"违法行为构成犯罪，应当依法追究刑事责任，不得以行政处罚代替刑事处罚。"},{"i":6,"n":"第六条","txt":"实施林业行政处罚的机关，必须是县级以上林业行政主管部门，法律、法规授权的组织以及林业行政主管部门依法委托的组织。其他任何机关和组织，不得实施林业行政处罚。 林业行政主管部门依法委托实施林业行政处罚，必须办理书面委托手续，并由委托的林业行政主管部门报上一级林业行政主管部门备案。委托的林业行政主管部门对受委托的组织实施行政处罚的行为负责监督，并对该行为的后果承担法律责任。 受委托组织在委托范围内，以委托的林业行政主管部门名义实施行政处罚，不得再委托其他组织或者个人实施行政处罚。"},{"i":7,"n":"第七条","txt":"地州级以上林业行政主管部门的法制工作机构统一管理林业行政处罚工作。 县级林业行政主管部门可以确定一个内部机构统一管理林业行政处罚工作。"},{"i":8,"n":"第八条","txt":"县级林业行政主管部门管辖本辖区内的林业行政处罚。 地州级和省级林业行政主管部门管辖本辖区内重大、复杂的林业行政处罚。 林业部管辖全国重大、复杂的林业行政处罚。"},{"i":9,"n":"第九条","txt":"林业行政处罚由违法行为发生地的林业行政主管部门管辖。"},{"i":10,"n":"第十条","txt":"上级林业行政主管部门在必要的时候可以处理下一级林业行政主管部门管辖的林业行政处罚，也可以把自己管辖的林业行政处罚交由下一级林业行政主管部门处理；下一级林业行政主管部门认为重大、复杂的林业行政处罚需要由上一级林业行政主管部门处理的，可以报请上一级林业行政主管部门决定。"},{"i":11,"n":"第十一条","txt":"几个同级林业行政主管部门都有管辖权的林业行政处罚，由最初受理的林业行政主管部门处理；主要违法行为地的林业行政主管部门处理更为适宜的，可以移送主要违法行为地的林业行政主管部门处理。 林业行政处罚管辖权发生争议的，报请共同上一级林业行政主管部门指定管辖。"},{"i":12,"n":"第十二条","txt":"法律、法规授权的组织和林业行政主管部门依法委托的组织，管辖授权、委托范围内的林业行政处罚。"},{"i":13,"n":"第十三条","txt":"违法行为在二年内未被发现的，不再给予林业行政处罚。法律另有规定的除外。"},{"i":14,"n":"第十四条","txt":"林业行政执法人员调查处理林业行政处罚案件时，应当向当事人或者有关人员出示执法证件。执法证件由林业部统一制发，省级以上林业行政主管部门法制工作机构负责执法证件的发放和管理工作。"},{"i":15,"n":"第十五条","txt":"林业行政执法人员在调查处理林业行政处罚案件时与当事人有利害关系的，应当自行回避。 当事人认为林业行政执法人员与本案有利害关系或者其他关系可能影响公正处理的，有权申请林业行政执法人员回避。 林业行政执法人员的回避，由行政负责人决定；行政负责人的回避由集体讨论决定。 回避未被决定以前，不得停止对案件的调查处理。"},{"i":16,"n":"第十六条","txt":"林业行政执法人员在调查处理林业行政处罚案件时应当依法收取证据。 证据主要有以下几种： （一）书证； （二）物证； （三）视听资料； （四）证人证言； （五）当事人的陈述； （六）鉴定结论； （七）勘验笔录、现场笔录。 证据必须经过查证属实，才能作为认定案件事实的根据。"},{"i":17,"n":"第十七条","txt":"公民、法人或者其他组织违反林业行政管理秩序的行为，依法应当给予林业行政处罚的，林业行政主管部门必须查明事实；违法事实不清的，不得给予林业行政处罚。"},{"i":18,"n":"第十八条","txt":"林业行政主管部门在林业行政处罚决定书送达之前，应当告知当事人作出林业行政处罚决定的事实、理由及依据，并告知当事人依法享有的权利。"},{"i":19,"n":"第十九条","txt":"当事人有权进行陈述和申辩。林业行政主管部门必须充分听取当事人的意见，对当事人提出的事实、理由和证据，应当进行复核；当事人提出的事实、理由或者证据成立的，林业行政主管部门应当采纳。 林业行政主管部门不得因当事人申辩而加重处罚。"},{"i":20,"n":"第二十条","txt":"凡给予林业行政处罚的，应当具备下述条件： （一）有明确的违法行为人； （二）有具体的违法事实和证据； （三）法律、法规和规章规定应当给予林业行政处罚的； （四）属于查处的机关管辖。"},{"i":21,"n":"第二十一条","txt":"违法事实确凿并有法定依据，对公民处以五十元以下、对法人或者其他组织处以一千元以下罚款或者警告的行政处罚的，可以当场作出林业行政处罚决定。当事人应当依照本规定的有关条款履行林业行政处罚决定。"},{"i":22,"n":"第二十二条","txt":"执法人员当场作出林业行政处罚决定的，可以由一人进行，应当向当事人出示执法身份证件，制作《林业行政处罚当场处罚笔录》，填写《林业行政处罚当场处罚决定书》，按规定格式载明当事人的违法行为、行政处罚依据、罚款数额或者警告、时间、地点以及本行政主管部门名称，由林业行政执法人员签名或者盖章，当场交付当事人。 执法人员当场作出的林业行政处罚决定，必须报所属林业行政主管部门备案。"},{"i":23,"n":"第二十三条","txt":"除本规定第二十一条规定的可以当场作出的行政处罚外，林业行政主管部门必须按照一般程序规定实施林业行政处罚。"},{"i":24,"n":"第二十四条","txt":"凡发现或者接到举报、控告、移送、上级交办、主动交代等违反林业法律、法规、规章的行为，应当填写《林业行政处罚登记表》，报行政负责人审批。对认为需要给予林业行政处罚的，在七日内予以立案；对认为不需要给予林业行政处罚的，不予立案。 立案必须符合下列条件： （一）有违法行为发生； （二）违法行为是应受处罚的行为； （三）属于本机关管辖； （四）属于一般程序适用范围。 林业行政处罚案件立案以后，经调查并报行政负责人审批，没有违法事实的，撤销立案；不属于自己管辖的，移送有关主管部门；需要追究刑事责任的，移送司法机关处理。"},{"i":25,"n":"第二十五条","txt":"调查处理林业行政处罚案件不得少于二人。"},{"i":26,"n":"第二十六条","txt":"林业行政主管部门收集证据时，在证据可能灭失或者以后难以取得的情况下，经行政机关负责人批准，可以先行登记保存，填写《林业行政处罚登记保存通知单》，并应当在七日内及时作出处理决定，在此期间，当事人或者有关人员不得销毁或者转移证据。"},{"i":27,"n":"第二十七条","txt":"林业行政执法人员应当全面、公正、客观地收集、调取各种证据。必要时，可以会同有关部门共同收集、调取各种证据。收集、调取证据应当制作笔录，由调查人和有关当事人在笔录上签名或者盖章。"},{"i":28,"n":"第二十八条","txt":"林业行政执法人员调查处理林业行政处罚案件应当询问当事人或者其他知情人（以下称被询问人），并制作《林业行政处罚询问笔录》。被询问人拒绝回答的，不影响根据证据对案件事实的认定。 询问笔录应当交被询问人核对，对于没有阅读能力的，应当向其宣读；被询问人提出补充或者改正的，应当允许；被询问人确认笔录无误后，应当在笔录上签名或者盖章；被询问人拒绝签名或者盖章的，应当在笔录上注明，询问人也应当在笔录上签名或者盖章。被询问人要求自行书写的，应当允许；必要时，林业行政执法人员也可以要求被询问人自行书写，自行书写的应当有本人的签名或者盖章。"},{"i":29,"n":"第二十九条","txt":"林业行政执法人员对与违法行为有关的场所、物品可以进行勘验、检查。必要时，可以指派或者聘请具有专门知识的人进行勘验、检查，并可以邀请与案件无关的见证人和有关的当事人参加。当事人拒绝参加的，不影响勘验、检查的进行。 勘验、检查应当制作《林业行政处罚勘验、检查笔录》，由参加勘验、检查的人和被邀请的见证人、有关的当事人签名或者盖章。"},{"i":30,"n":"第三十条","txt":"为解决林业行政处罚案件中某些专门性问题，林业行政主管部门可以指派或者聘请有专门知识的人进行鉴定。 鉴定人进行鉴定后，应当提出书面鉴定结论并签名或者盖章，注明本人身份。"},{"i":31,"n":"第三十一条","txt":"林业行政处罚案件经调查事实清楚、证据确凿的，应当填写《林业行政处罚意见书》，并连同《林业行政处罚登记表》和证据等有关材料，由林业行政执法人员送法制工作机构提出初步意见后，再交由本行政主管部门负责人审查决定。 情节复杂或者重大违法行为需要给予较重行政处罚的，林业行政主管部门的负责人应当集体讨论决定。"},{"i":32,"n":"第三十二条","txt":"凡决定给予林业行政处罚的，应当制作《林业行政处罚决定书》，按照规定格式载明下列事项： （一）当事人的姓名或者名称、地址； （二）违反法律、法规或者规章的事实和证据； （三）林业行政处罚的种类和依据； （四）林业行政处罚的履行方式和期限； （五）不服林业行政处罚决定，申请行政复议或者提起行政诉讼的途径和期限； （六）作出林业行政处罚决定的林业行政主管部门名称和作出决定的日期。"},{"i":33,"n":"第三十三条","txt":"林业行政主管部门或其委托的组织作出的林业行政处罚，应当在《林业行政处罚决定书》上盖林业行政主管部门的印章。 法律、法规授权的组织作出的林业行政处罚，应当在《林业行政处罚决定书》上盖本组织的印章。"},{"i":34,"n":"第三十四条","txt":"林业行政处罚案件自立案之日起，应当在一个月内办理完毕；经行政负责人批准可以延长，但不得超过三个月；特殊情况下三个月内不能办理完毕的，报经上级林业行政主管部门批准，可以延长。"},{"i":35,"n":"第三十五条","txt":"林业行政主管部门及其执法人员在作出林业行政处罚决定之前，不依照规定向当事人告知给予行政处罚的事实、理由和依据，或者拒绝听取当事人的陈述、申辩，行政处罚不能成立；当事人放弃陈述或者申辩权利的除外。"},{"i":36,"n":"第三十六条","txt":"公民、法人或者其他组织对林业行政主管部门或者行政执法人员作出的行政处罚有权提出申诉和检举；林业行政主管部门应当认真审查，发现确有错误的，应当主动改正。 作出林业行政处罚决定的林业行政主管部门负责人认为作出的林业行政处罚决定确有错误的，有权提请集体讨论，决定是否重新处理。"},{"i":37,"n":"第三十七条","txt":"林业行政主管部门作出责令停产停业、吊销许可证、较大数额罚款等行政处罚决定之前，应当告知当事人有要求举行听证的权利；当事人要求听证的，林业行政主管部门应当组织听证，制发《举行听证通知》，制作《林业行政处罚听证笔录》。当事人不承担林业行政主管部门组织听证的费用。听证依照法定程序进行。"},{"i":38,"n":"第三十八条","txt":"听证结束后，林业行政主管部门依照本规定第三十一条，作出决定。"},{"i":39,"n":"第三十九条","txt":"《林业行政处罚决定书》应当及时送达被处罚人，并由被处罚人在《林业行政处罚送达回证》上签名或者盖章；被处罚人不在，可以交给其成年家属或者所在单位的负责人员代收，并在送达回证上签名或者盖章。 被处罚人或者代收人拒绝接收或者签名、盖章的，送达人可以邀请其邻居或者其单位有关人员到场，说明情况，把《林业行政处罚决定书》留在其住处或者其单位，并在送达回证上记明拒绝的事由、送达的日期，由送达人签名，即视为送达。 被处罚人不在本地的，可以委托被处罚人所在地的林业行政主管部门代为送达，也可以挂号邮寄送达。邮寄送达的，以挂号回执上注明的收件日期为送达日期。"},{"i":40,"n":"第四十条","txt":"除依照本规定第四十一条、第四十二条规定当场收缴的罚款外，作出林业行政处罚决定的林业行政主管部门及其执法人员不得自行收缴罚款。 当事人应当自收到林业行政处罚决定书之日起十五日内，到指定的银行缴纳罚款。"},{"i":41,"n":"第四十一条","txt":"依照本规定第二十一条可以当场作出林业行政处罚决定，有下列情形之一的，执法人员可以当场收缴罚款： （一）依法给予二十元以下的罚款的； （二）不当场收缴事后难以执行的。"},{"i":42,"n":"第四十二条","txt":"在边远、水上、交通不便地区，林业行政主管部门及其执法人员作出罚款决定后，当事人向指定的银行缴纳罚款确有困难，经当事人提出，林业行政主管部门及其执法人员可以当场收缴罚款。"},{"i":43,"n":"第四十三条","txt":"林业行政主管部门及其执法人员当场收缴罚款的，必须向当事人出具省、自治区、直辖市财政部门统一制发的罚款收据；不出具财政部门统一制发的罚款收据的，当事人有权拒绝缴纳罚款。"},{"i":44,"n":"第四十四条","txt":"执法人员当场收缴的罚款，应当自收缴罚款之日起二日内，交至林业行政主管部门；在水上当场收缴的罚款，应当自抵岸之日起二日内交至林业行政主管部门；林业行政主管部门应当在二日内将罚款缴付指定的银行。"},{"i":45,"n":"第四十五条","txt":"当事人逾期不履行林业行政处罚决定的，作出行政处罚决定的林业行政主管部门可以采取下列措施： （一）到期不缴纳罚款的，每日按罚款数额的百分之三加处罚款； （二）根据法律规定，将查封、扣押的财物拍卖或者将冻结的存款划拨抵缴罚款； （三）申请人民法院强制执行。"},{"i":46,"n":"第四十六条","txt":"当事人确有经济困难，需要延期或者分期缴纳罚款的，经当事人申请和作出处罚决定的林业行政主管部门审查批准，可以暂缓或者分期缴纳。"},{"i":47,"n":"第四十七条","txt":"除依法应当予以销毁的物品外，依法没收的非法财物必须按照国家规定公开拍卖或者按照国家有关规定处理。 罚款、没收违法所得或者没收非法财物拍卖的款项，按照国家有关规定处理。"},{"i":48,"n":"第四十八条","txt":"《林业行政处罚决定书》送达后，承办人应当将案件材料立卷。 林业行政处罚案件卷宗一般包括：卷皮、目录、案件登记表、证据材料、林业行政处罚意见书、林业行政处罚决定书和其他材料。 林业行政处罚案件办理终结，承办人应当根据一案一卷的原则，将案件的全部材料立卷归档。"},{"i":49,"n":"第四十九条","txt":"上级交办的林业行政处罚案件办理终结，承办的单位应当将案件的处理结果向交办单位报告。"},{"i":50,"n":"第五十条","txt":"本规定中规定的林业行政处罚案件包括破坏陆生野生动物资源的行政处罚案件。"},{"i":51,"n":"第五十一条","txt":"本规定中规定的签名或者盖章，当事人因故不能履行的，可以按指印。"},{"i":52,"n":"第五十二条","txt":"本规定由林业部负责解释。"},{"i":53,"n":"第五十三条","txt":"本规定自一九九六年十月一日起施行。"}],"linyexingzhengzhifajiandubanfa":[{"i":1,"n":"第一条","txt":"为了保障林业法律、法规、规章的正确实施，监督林业行政执法，保护当事人合法权益，根据有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"各级林业行政主管部门进行林业行政执法监督适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称林业行政执法监督包括行政执法内部监督和行政执法层级监督。 行政执法内部监督是指各级林业行政主管部门对本部门内部的执法机构和执法人员实施林业行政执法进行的监督活动。 行政执法层级监督是指上级林业行政主管部门对下级林业行政主管部门和林业行政执法人员的林业行政执法进行的监督活动。"},{"i":4,"n":"第四条","txt":"林业行政执法监督遵循有法必依、执法必严、违法必究和以事实为依据、以法律为准绳的原则。"},{"i":5,"n":"第五条","txt":"各级林业行政主管部门的法制工作机构负责本辖区内林业行政执法监督工作。 各级林业行政主管部门应当根据工作需要，确立本机关法制工作机构。"},{"i":6,"n":"第六条","txt":"下级林业行政主管部门认为上级林业行政主管部门进行的林业行政执法或者监督活动不合法或者不适当，有权向上级林业行政主管部门提出改正建议。"},{"i":7,"n":"第七条","txt":"林业行政主管部门在实施林业行政执法监督时，被监督的单位和执法人员应当积极配合，自觉接受监督。"},{"i":8,"n":"第八条","txt":"林业行政执法内部监督的主要内容： （一）执法人员是否具备执法资格，执法是否持有有效的执法证件； （二）受委托组织是否在委托范围和权限内依法实施行政处罚； （三）案件的办理人员是否应当回避而没有回避； （四）执法人员是否有超越职权、滥用职权、行贿受贿、包庇纵容、徇私舞弊、玩忽职守等违法行为； （五）案件是否依法受理； （六）案件的事实是否清楚、证据是否确凿； （七）适用法律、法规、规章是否正确； （八）案件的办理是否符合法定程序； （九）林业行政处罚决定的执行是否符合法律、法规、规章的规定； （十）案件档案管理制度是否健全； （十一）其他应当监督的执法活动。"},{"i":9,"n":"第九条","txt":"依法需要举行听证程序的林业行政处罚案件，应当由林业行政主管部门组织听证，指定非本案调查人员主持，主持人与本案有直接利害关系的，应当自行回避，当事人也有权申请回避。"},{"i":10,"n":"第十条","txt":"案件调查终结，在报行政负责人审查决定前，林业行政执法人员应当将全部案件材料送法制工作机构提出初步意见。"},{"i":11,"n":"第十一条","txt":"情节复杂或者重大违法行为需要给予较重行政处罚的，林业行政主管部门的负责人应当集体讨论决定。"},{"i":12,"n":"第十二条","txt":"作出罚款决定的林业行政主管部门应当与收缴罚款的机构分离，除依法可以当场收缴的罚款外，作出行政处罚的林业行政主管部门及其工作人员不得自行收缴罚款。"},{"i":13,"n":"第十三条","txt":"公民、法人或者其他组织对林业行政主管部门或行政执法人员作出具体行政行为提出的申诉和检举，林业行政主管部门应当认真审查，发现确有错误的，应当主动改正。"},{"i":14,"n":"第十四条","txt":"林业行政执法层级监督的主要内容： （一）林业规范性文件是否合法； （二）林业行政案件是否依法查处； （三）具体行政行为是否合法、适当： （１）行政执法主体是否合法； （２）是否履行了法定职责； （３）是否符合法定权限和程序； （４）事实是否清楚，证据是否确凿； （５）适用法律、法规、规章是否正确； （６）行政处罚文书的使用和填写是否规范； （７）罚没财物是否按规定处置； （四）林业行政复议案件是否依法受理和审理； （五）林业行政赔偿是否依法处理； （六）其他需要进行监督的事项。"},{"i":15,"n":"第十五条","txt":"地方各级林业行政主管部门制定的规范性文件应在发布后１５日内报送上一级林业行政主管部门。 依法制定的林业地方性法规和规章以及民族自治地方依法制定的林业自治条例、单行条例发布后，本级林业行政主管部门应当在３０日内报送上级林业行政主管部门。"},{"i":16,"n":"第十六条","txt":"新的法律、法规发布后，各级林业行政主管部门应及时对有关的林业法规、规章和规范性文件进行清理，做好制订、修改、废止工作。"},{"i":17,"n":"第十七条","txt":"地方各级林业行政主管部门应当在每年１月１５日前将前一年度本辖区内林业法律、法规和规章的实施情况、实施效果、存在问题及建议，以书面形式报送上一级林业行政主管部门。"},{"i":18,"n":"第十八条","txt":"地方各级林业行政主管部门对本辖区内责令停产停业、吊销许可证、没收较大数额的违法所得或者非法财物、较大数额的罚款等重大复杂的林业行政处罚，应在作出处罚决定之日起１５日内，将有关材料报送上一级林业行政主管部门备案。 备案的有关材料包括：处罚案件简要介绍；主要证据材料复印件；处罚决定书复印件等。"},{"i":19,"n":"第十九条","txt":"地方各级林业行政主管部门应当将本部门作出的行政赔偿案件或者由人民法院判决作出的行政赔偿案件的情况于３０日内报告上一级林业行政主管部门。"},{"i":20,"n":"第二十条","txt":"上级林业行政主管部门应定期抽查下级林业行政主管部门的林业行政处罚案件档案。 上级林业行政主管部门调阅案卷和有关材料，下级林业行政主管部门应及时提供。"},{"i":21,"n":"第二十一条","txt":"地方各级林业行政主管部门应按规定填写《林业行政处罚案件年度统计表》、《行政复议和行政应诉案件统计表》，并由省级林业行政主管部门汇总后于每年３月１５日前报林业部。"},{"i":22,"n":"第二十二条","txt":"对国家权力机关、人民政府交办和群众举报或者通过其他途径获取的林业行政违法案件，林业行政主管部门经审查后属于自己管辖的，应及时立案；属于上级林业行政主管部门管辖的，应及时移送；属于下级林业行政主管部门管辖的，应发送《林业行政案件督办通知书》，督促及时依法查处，下级林业行政主管部门应在案件处理后３０日内将处理情况报告督办机关。"},{"i":23,"n":"第二十三条","txt":"公民、法人或者其他组织对林业行政主管部门和林业行政执法人员作出具体行政行为提出的申诉和检举，上级林业行政主管部门应当认真审查，对符合复议条件的，应当告知申诉人或检举人向有管辖权的机关申请行政复议；对不符合复议条件，或者在法定的期限内，当事人既未申请复议，又未提起行政诉讼，发现具体行政行为确有错误的，应当根据森林和野生动植物资源下管一级的原则，由上一级林业行政主管部门责令下一级林业行政主管部门改正或者予以撤销、变更。"},{"i":24,"n":"第二十四条","txt":"有下列事迹之一的单位和个人，县级以上林业行政主管部门应当给予奖励： （一）模范执行林业法律、法规和规章，并能自觉接受上级领导机关和主管部门的监督，不徇私情，秉公执法，事迹突出的； （二）在林业行政执法工作中成绩显著的； （三）在查处重大林业违法案件中有突出贡献的； （四）对林业法制建设有明显促进作用的； （五）从事林业行政执法工作１０年以上，工作有成绩的。"},{"i":25,"n":"第二十五条","txt":"林业行政执法监督人员，应遵纪守法，忠于职守。对工作成绩显著的，按照有关规定给予表扬或者奖励；对工作失职的，给予行政处分。"},{"i":26,"n":"第二十六条","txt":"林业行政主管部门违反本办法第九条、第十条、第十一条、第十二条、第十三条的规定，应当主动改正；已经作出具体行政行为的，应当自行补正、撤销或重新作出；执法人员负有责任的，应当责令改正并给予相应的行政处分。"},{"i":27,"n":"第二十七条","txt":"林业行政主管部门违反本办法第十五条、第十六条、第十七条、第十八条、第十九条、第二十条、第二十一条的规定，由上级林业行政主管部门或者有关部门责令限期改正，可以对直接负责的主管人员和其他直接责任人员依法给予行政处分。"},{"i":28,"n":"第二十八条","txt":"林业行政执法监督中发现与法律、法规相抵触的规章和规范性文件，林业行政主管部门应当提请有权的机关予以废止或者修订。"},{"i":29,"n":"第二十九条","txt":"有下列行为之一的，林业行政主管部门应主动改正或者上级林业行政主管部门责令下级林业行政主管部门限期改正，可以对直接负责的主管人员和其他直接责任人员依法给予行政处分；有下述第（五）项、第（六）项行为的，由林业行政主管部门予以收缴销毁；有下述第（七）项、第（八）项行为的，能够恢复原状的，应恢复原状，不能恢复原状的，林业行政主管部门应当依法予以赔偿，赔偿义务机关赔偿损失后，应当责令有故意或者重大过失的工作人员承担部分或者全部费用： （一）具体行政行为不合法或者不适当的； （二）违反国家规定自行收缴罚款的； （三）为牟取本单位私利，对应当依法移交司法机关追究刑事责任的不移交，以行政处罚代替刑事处罚的； （四）玩忽职守，对应制止、处罚的违法行为不予制止、处罚，致使公民、法人或者其他组织的合法权益、公共利益和社会秩序遭受损害的； （五）对当事人实施罚款、没收财物处罚，未开具或者擅自使用非法单据的；"},{"i":30,"n":"第三十条","txt":"在实施林业行政执法监督过程中作出处理决定的，应当由林业行政主管部门的负责人集体讨论决定，并制作《林业行政执法监督处理决定书》，及时送达被监督单位。 被监督单位在接到前款文书后，应及时做出处理，并在３０日内将处理结果报告实施监督行为的林业行政主管部门。"},{"i":31,"n":"第三十一条","txt":"本办法规定的《林业行政处罚案件年度统计表》、《林业行政案件督办通知书》、《林业行政执法监督处理决定书》由林业部另行制定。"},{"i":32,"n":"第三十二条","txt":"本办法由林业部负责解释。"},{"i":33,"n":"第三十三条","txt":"本办法自一九九六年十月一日起施行。"}],"linyexingzhengxuketingzhengbanfa":[{"i":1,"n":"第一条","txt":"为了规范林业行政许可听证程序，根据《中华人民共和国行政许可法》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"县级以上人民政府林业主管部门（以下简称林业主管部门）举行林业行政许可听证，适用本办法。"},{"i":3,"n":"第三条","txt":"举行林业行政许可听证，应当遵循公开、公平、公正的原则。"},{"i":4,"n":"第四条","txt":"林业行政许可听证工作，由林业主管部门法制工作机构负责。"},{"i":5,"n":"第五条","txt":"法律、法规、规章规定实施林业行政许可应当听证的事项，或者林业主管部门认为需要听证的其他涉及公共利益的重大林业行政许可事项，应当向社会公告，并举行听证。"},{"i":6,"n":"第六条","txt":"直接涉及申请人与他人之间重大利益关系的林业行政许可事项，林业行政许可申请人、利害关系人提出听证申请的，林业主管部门应当举行听证。"},{"i":7,"n":"第七条","txt":"听证人员包括：听证主持人、听证员和记录员。 听证主持人，由林业主管部门法制工作机构工作人员担任。 听证员和记录员由听证主持人指定。"},{"i":8,"n":"第八条","txt":"听证参加人包括：林业行政许可事项的审查人员、申请人和利害关系人。"},{"i":9,"n":"第九条","txt":"听证主持人履行下列职责： （一）决定举行听证的时间、地点； （二）审查听证参加人的资格； （三）主持听证会，并维护听证秩序； （四）针对听证事项进行询问； （五）核实听证笔录。"},{"i":10,"n":"第十条","txt":"听证人员应当维护听证参加人的陈述、申辩和质证权利，保守听证事项涉及的国家秘密和商业秘密。"},{"i":11,"n":"第十一条","txt":"听证主持人与林业行政许可事项有直接利害关系的，应当主动回避。申请人、利害关系人认为听证主持人与林业行政许可事项有直接利害关系的，有权申请回避。 听证主持人的回避由林业主管部门负责人决定。"},{"i":12,"n":"第十二条","txt":"申请人和利害关系人享有下列权利： （一）申请听证主持人回避； （二）委托代理人参加听证； （三）针对听证事项进行陈述、申辩和质证； （四）确认听证笔录。"},{"i":13,"n":"第十三条","txt":"林业行政许可事项的审查人员，在听证时应当提供审查意见的依据、理由，并进行陈述、申辩和质证。"},{"i":14,"n":"第十四条","txt":"林业主管部门按照本办法第五条规定举行林业行政许可听证的，应当于举行听证会的二十日前向社会公告。 公告内容包括：听证事项、时间、地点和听证参加人的产生方式等。"},{"i":15,"n":"第十五条","txt":"林业主管部门在作出本办法第六条规定的林业行政许可决定前，应当告知申请人、利害关系人享有要求听证的权利，并送达林业行政许可听证申请权利告知书。"},{"i":16,"n":"第十六条","txt":"申请人、利害关系人要求听证的，应当在收到林业行政许可听证申请权利告知书之日起五日内提出听证申请。"},{"i":17,"n":"第十七条","txt":"林业主管部门应当在收到听证申请之日起二十日内组织听证。"},{"i":18,"n":"第十八条","txt":"林业主管部门应当于举行听证会的七日前向听证参加人送达林业行政许可听证通知书。"},{"i":19,"n":"第十九条","txt":"听证会应当公开举行，但涉及国家秘密和商业秘密的除外。"},{"i":20,"n":"第二十条","txt":"申请人、利害关系人申请听证主持人回避的，应当于举行听证会三日前提出，并说明理由。"},{"i":21,"n":"第二十一条","txt":"听证会按照下列程序进行： （一）查明听证参加人身份； （二）听证主持人宣读听证事由、听证人员和听证参加人名单,并宣布听证会开始； （三）林业行政许可事项的审查人员进行陈述； （四）申请人、利害关系人进行陈述； （五）听证参加人进行申辩、质证； （六）听证主持人宣布听证会结束。"},{"i":22,"n":"第二十二条","txt":"听证会应当制作听证笔录。听证笔录应当载明下列内容： （一）听证事项； （二）听证人员和听证参加人； （三）听证时间和地点； （四）听证参加人进行陈述、申辩和质证的情况； （五）其他事项。 听证笔录由听证主持人核实、听证参加人确认后签字或者盖章。"},{"i":23,"n":"第二十三条","txt":"林业主管部门应当根据听证笔录，作出林业行政许可决定。"},{"i":24,"n":"第二十四条","txt":"林业主管部门举行听证，不得向申请人、利害关系人收取任何费用。"},{"i":25,"n":"第二十五条","txt":"本办法自2008年10月1日起施行。"}],"linmulindiquanshuzhengyichulibanfa":[{"i":1,"n":"第一条","txt":"为了公正、及时地处理林木、林地权属争议，维护当事人的合法权益，保障社会安定团结，促进林业发展，根据《中华人民共和国森林法》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称林木、林地权属争议，是指因森林、林木、林地所有权或者使用权的归属而产生的争议。 处理森林、林木、林地的所有权或者使用权争议（以下简称林权争议），必须遵守本办法。"},{"i":3,"n":"第三条","txt":"处理林权争议，应当尊重历史和现实情况，遵循有利于安定团结，有利于保护、培育和合理利用森林资源，有利于群众的生产生活的原则。"},{"i":4,"n":"第四条","txt":"林权争议由各级人民政府依法作出处理决定。 林业部、地方各级人民政府林业行政主管部门或者人民政府设立的林权争议处理机构（以下统称林权争议处理机构）按照管理权限分别负责办理林权争议处理的具体工作。"},{"i":5,"n":"第五条","txt":"林权争议发生后，当事人所在地林权争议处理机构应当及时向所在地人民政府报告，并采取有效措施防止事态扩大。 在林权争议解决以前，任何单位和个人不得采伐有争议的林木，不得在有争议的林地上从事基本建设或者其他生产活动。"},{"i":6,"n":"第六条","txt":"县级以上人民政府或者国务院授权林业部依法颁发的森林、林木、林地的所有权或者使用权证书（以下简称林权证），是处理林权争议的依据。"},{"i":7,"n":"第七条","txt":"尚未取得林权证的，下列证据作为处理林权争议的依据： （一）土地改革时期，人民政府依法颁发的土地证； （二）土地改革时期，《中华人民共和国土地改革法》规定不发证的林木、林地的土地清册； （三）当事人之间依法达成的林权争议处理协议、赠送凭证及附图； （四）人民政府作出的林权争议处理决定； （五）对同一起林权争议有数次处理协议或者决定的，以上一级人民政府作出的最终决定或者所在地人民政府作出的最后一次决定为依据； （六）人民法院作出的裁定、判决。"},{"i":8,"n":"第八条","txt":"土地改革后至林权争议发生时，下列证据可以作为处理林权争议的参考依据： （一）国有林业企业事业单位设立时，该单位的总体设计书所确定的经营管理范围及附图； （二）土地改革、合作化时期有关林木、林地权属的其他凭证； （三）能够准确反映林木、林地经营管理状况的有关凭证； （四）依照法律、法规和有关政策规定，能够确定林木、林地权属的其他凭证。"},{"i":9,"n":"第九条","txt":"土地改革前有关林木、林地权属的凭证，不得作为处理林权争议的依据或者参考依据。"},{"i":10,"n":"第十条","txt":"处理林权争议时，林木、林地权属凭证记载的四至清楚的，应当以四至为准；四至不清楚的，应当协商解决；经协商不能解决的，由当事人共同的人民政府确定其权属。"},{"i":11,"n":"第十一条","txt":"当事人对同一起林权争议都能够出具合法凭证的，应当协商解决；经协商不能解决的，由当事人共同的人民政府按照双方各半的原则，并结合实际情况确定其权属。"},{"i":12,"n":"第十二条","txt":"土地改革后营造的林木，按照“谁造林、谁管护、权属归谁所有”的原则确定其权属，但明知林地权属有争议而抢造的林木或者法律、法规另有规定的除外。"},{"i":13,"n":"第十三条","txt":"林权争议发生后，当事人应当主动、互谅、互让地协商解决。经协商依法达成协议的，当事人应当在协议书及附图上签字或者盖章，并报所在地林权争议处理机构备案；经协商不能达成协议的，按照本办法规定向林权争议处理机构申请处理。"},{"i":14,"n":"第十四条","txt":"林权争议由当事人共同的林权争议处理机构负责办理具体处理工作。"},{"i":15,"n":"第十五条","txt":"申请处理林权争议的，申请人应当向林权争议处理机构提交《林木林地权属争议处理申请书》。 《林木林地权属争议处理申请书》应当包括以下内容： （一）当事人的姓名、地址及其法定代表人的姓名、职务； （二）争议的现状，包括争议面积、林木蓄积，争议地所在的行政区域位置、四至和附图； （三）争议的事由，包括发生争议的时间、原因； （四）当事人的协商意见。 《林木林地权属争议处理申请书》由省、自治区、直辖市人民政府林权争议处理机构统一印制。"},{"i":16,"n":"第十六条","txt":"林权争议处理机构在接到《林木林地权属争议处理申请书》后，应当及时组织办理。"},{"i":17,"n":"第十七条","txt":"当事人对自己的主张应当出具证据。当事人不能出具证据的，不影响林权争议处理机构依据有关证据认定争议事实。"},{"i":18,"n":"第十八条","txt":"林权争议经林权争议处理机构调解达成协议的，当事人应当在协议书上签名或者盖章，并由调解人员署名，加盖林权争议处理机构印章，报同级人民政府或者林业行政主管部门备案。"},{"i":19,"n":"第十九条","txt":"林权争议经林权争议处理机构调解未达成协议的，林权争议处理机构应当制作处理意见书，报同级人民政府作出决定。 处理意见书应当写明下列内容： （一）当事人的姓名、地址及其法定代表人的姓名、职务； （二）争议的事由、各方的主张及出具的证据； （三）林权争议处理机构认定的事实、理由和适用的法律、法规及政策规定； （四）处理意见。"},{"i":20,"n":"第二十条","txt":"当事人之间达成的林权争议处理协议或者人民政府作出的林权争议处理决定，凡涉及国有林业企业、事业单位经营范围变更的，应当事先征得原批准机关同意。"},{"i":21,"n":"第二十一条","txt":"当事人之间达成的林权争议处理协议，自当事人签字之日起生效；人民政府作出的林权争议处理决定，自送达之日起生效。"},{"i":22,"n":"第二十二条","txt":"当事人对人民政府作出的林权争议处理决定不服的，可以依法提出申诉或者向人民法院提起诉讼。"},{"i":23,"n":"第二十三条","txt":"在林权争议处理工作中做出突出贡献的单位和个人，由县级以上人民政府林业行政主管部门给予奖励。"},{"i":24,"n":"第二十四条","txt":"伪造、变造、涂改本办法规定的林木、林地权属凭证的，由林权争议处理机构收缴其伪造、变造、涂改的林木、林地权属凭证，并可视情节轻重处以１０００元以下罚款。"},{"i":25,"n":"第二十五条","txt":"违反本办法规定，在林权争议解决以前，擅自采伐有争议的林木或者在有争议的林地上从事基本建设及其他生产活动的，由县级以上人民政府林业行政主管部门依照《森林法》等法律、法规给予行政处罚。"},{"i":26,"n":"第二十六条","txt":"在处理林权争议过程中，林权争议处理机构工作人员玩忽职守，徇私舞弊的，由其所在单位或者有关机关依法给予行政处分。"},{"i":27,"n":"第二十七条","txt":"本办法由林业部负责解释。"},{"i":28,"n":"第二十八条","txt":"本办法自发布之日起施行。"}],"linmuzhongzishengchanjingyingxukezhengguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范林木种子生产经营许可证的管理，根据《中华人民共和国种子法》、《中华人民共和国行政许可法》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事林木种子生产经营许可证的申请、审核、核发和管理等活动，适用本办法。 本办法所称林木种子生产经营许可证，是指县级以上人民政府林业主管部门核发的准予从事林木种子生产经营活动的证件。"},{"i":3,"n":"第三条","txt":"本办法所称林木种子是指林木的种植材料（苗木）或者繁殖材料，具体是指乔木、灌木、藤本、竹类、花卉以及绿化和药用草本植物的籽粒、果实、根、茎、苗、芽、叶、花等。"},{"i":4,"n":"第四条","txt":"从事林木种子经营和主要林木种子生产的单位和个人应当取得林木种子生产经营许可证，按照林木种子生产经营许可证载明的事项从事生产经营活动。"},{"i":5,"n":"第五条","txt":"县级以上人民政府林业主管部门负责林木种子生产经营许可证的审核、核发和管理工作，具体工作可以由其委托的林木种苗管理机构负责。"},{"i":6,"n":"第六条","txt":"从事林木种子经营和主要林木种子生产的单位和个人，应当向县级以上人民政府林业主管部门申请林木种子生产经营许可证。"},{"i":7,"n":"第七条","txt":"申请林木种子生产经营许可证的单位和个人，应当提交下列材料： （一）林木种子生产经营许可证申请表。 （二）营业执照或者法人证书复印件、身份证件复印件；单位还应当提供章程。 （三）经营场所、生产用地权属证明材料以及生产用地的用途证明材料。 （四）林木种子生产、加工、检验、储藏等设施和仪器设备的所有权或者使用权说明材料以及照片。 （五）林木种子生产、检验、加工、储藏等技术人员基本情况的说明材料以及劳动合同。"},{"i":8,"n":"第八条","txt":"申请林木种子生产经营许可证属于下列情形的，申请人还应当提交下列材料： （一）从事林木种子生产的，应当提供生产地点无检疫性有害生物证明。其中从事籽粒、果实等有性繁殖材料生产的，还应当提供具有安全隔离条件的说明材料、县级以上人民政府林业主管部门确定的采种林分证明以及照片。 （二）从事具有植物新品种权林木种子生产经营的，应当提供品种权人的书面同意或者国务院林业主管部门品种权转让公告、强制许可决定。 （三）从事林木良种种子生产经营的，应当提供林木良种证明材料。 （四）实行选育生产经营相结合的，应当提供育种科研团队、试验示范测试基地以及自主研发的林木品种等相关证明材料。 （五）生产经营引进外来林木品种种子的，应当提交引种成功的证明材料。 （六）从事林木种子进出口业务的，应当提供按照国家有关规定取得的种子进出口许可证明。 （七）从事转基因林木种子生产经营的，应当提供转基因林木安全证书。"},{"i":9,"n":"第九条","txt":"申请林木种子进出口业务的林木种子生产经营许可证的，申请人应当向省、自治区、直辖市人民政府林业主管部门提出申请，经省、自治区、直辖市人民政府林业主管部门审核后，由国务院林业主管部门核发。 申请林木良种种子的生产经营和选育生产经营相结合的林木种子生产经营许可证的，申请人应当向所在地县级人民政府林业主管部门提出申请，经县级人民政府林业主管部门审核后，由省、自治区、直辖市人民政府林业主管部门核发。 申请前两款以外的其他林木种子生产经营许可证的，由生产经营者所在地县级以上地方人民政府林业主管部门核发。 只从事非主要林木种子生产的，不需办理林木种子生产经营许可证。"},{"i":10,"n":"第十条","txt":"申请林木种子生产经营许可证的，应当具备下列条件： （一）具有与林木种子生产经营的种类和数量相适应的生产经营场所。从事籽粒、果实等有性繁殖材料生产的，必须具有晒场、种子库。 （二）具有与林木种子生产经营的种类和数量相适应的设施、设备等。从事籽粒、果实等有性繁殖材料生产的，必须具有种子烘干、风选、精选机等生产设备和恒温培养箱、光照培养箱、干燥箱、扦样器、天平、电冰箱等种子检验仪器设备。 （三）具有林木种子相关专业中专以上学历、初级以上技术职称或者同等技术水平的生产、检验、加工、储藏等技术人员。"},{"i":11,"n":"第十一条","txt":"申请林木种子生产经营许可证从事籽粒、果实等有性繁殖材料生产的，除第十条规定外，还应当具备下列条件： （一）具有繁殖种子的隔离和培育条件。 （二）具有无检疫性有害生物的生产地点或者县级以上人民政府林业主管部门确定的采种林。 申请林木种子生产经营许可证从事苗木生产的，除第十条规定外，还应当具有无检疫性有害生物的生产地点。"},{"i":12,"n":"第十二条","txt":"负责审核的林业主管部门应当自受理申请之日起二十个工作日内完成审查；负责核发的林业主管部门应当自受理申请或者收到审查材料之日起二十个工作日内作出行政许可决定，并将行政许可决定抄送负责审核的林业主管部门。二十个工作日内不能作出行政许可决定的，经本级林业主管部门负责人批准，可以延长十个工作日，并应当将延长期限的理由告知申请人。 核发林木种子生产经营许可证需要组织检验检测的，应当自受理之日起五个工作日内书面告知申请人。检验检测所需时间不得超过六十日。 检验检测所需时间不计入核发林木种子生产经营许可证工作日之内。"},{"i":13,"n":"第十三条","txt":"对申请材料齐全、符合第十条以及第十一条规定条件的，林业主管部门应当核发林木种子生产经营许可证。对不符合第十条、第十一条规定条件的，林业主管部门应当作出不予核发林木种子生产经营许可证的行政许可决定，并告知不予许可的理由。"},{"i":14,"n":"第十四条","txt":"林木种子生产经营许可证有效期限为五年，地方性法规、政府规章另有规定的除外。"},{"i":15,"n":"第十五条","txt":"林木种子生产经营许可证有效期届满需要延续的，生产经营者应当在有效期届满三十日前向原发证机关提出延续的书面申请。申请者应当提交林木种子生产经营许可证延续申请表和上一年度生产经营情况说明。 林木种子生产经营许可证损坏、遗失的，生产经营者应当在有效期届满前向原发证机关提出补发的书面申请并说明理由，同时将已损坏的林木种子生产经营许可证交回原发证机关。 原发证机关应当根据申请，在林木种子生产经营许可证有效期届满前作出是否准予延期或者补发的决定。"},{"i":16,"n":"第十六条","txt":"林木种子生产经营许可证应当载明生产经营者名称、地址、法定代表人、生产经营种类、生产地点、有效期限、有效区域等事项。 从事林木良种种子生产经营的，林木种子生产经营许可证应当载明审（认）定的林木良种名称、编号。 林木种子生产经营许可证注明事项发生变更的，生产经营者应当自变更之日起三十日内，向原发证机关提出变更的书面申请。申请者应当提交变更申请和相应的项目变更证明材料，同时将林木种子生产经营许可证交回原发证机关。 有效期限和有效区域不得申请变更。"},{"i":17,"n":"第十七条","txt":"林木种子生产经营许可证的有效区域由发证机关在其管辖范围内确定。生产经营者在林木种子生产经营许可证载明的有效区域设立分支机构的，专门经营不再分装的包装种子的，或者受具有林木种子生产经营许可证的生产经营者以书面委托生产、代销其种子的，不需要办理林木种子生产经营许可证。但应当在变更营业执照或者获得书面委托后十五日内，将林木种子生产经营许可证复印件、营业执照复印件或者书面委托合同等证明材料报生产经营者所在地县级人民政府林业主管部门备案。 生产经营者在林木种子生产经营许可证载明的有效区域外设立分支机构的，应当重新申请办理林木种子生产经营许可证。 实行选育生产经营相结合的种子企业的林木种子生产经营许可证的有效区域为全国。"},{"i":18,"n":"第十八条","txt":"县级以上人民政府林业主管部门及其工作人员，不得参与和从事林木种子生产经营活动。"},{"i":19,"n":"第十九条","txt":"县级以上人民政府林业主管部门应当按照公开、公平、公正的原则，开展对生产经营者林木种子生产经营活动的监督检查，并将监督检查情况立卷、归档，实行动态监督管理。监督检查的主要内容包括： （一）开展林木种子生产经营活动情况。 （二）林木种子生产经营档案制度执行情况。 （三）生产经营的林木种子质量情况。 对监督检查中发现的问题，应当按照《中华人民共和国种子法》等规定予以处理。"},{"i":20,"n":"第二十条","txt":"县级以上人民政府林业主管部门应当建立林木种子生产经营许可证管理档案，具体内容包括：申请材料、审核、核发材料及有关法律、法规规定的文件等。 林木种子生产经营许可证管理档案应当从林木种子生产经营许可证被注销或者自动失效之日起至少保留五年。 省、自治区、直辖市人民政府林业主管部门应当于每年三月底前将上一年度林木种子生产经营许可证管理情况上报国家林业局。"},{"i":21,"n":"第二十一条","txt":"生产经营者应当按照林木种子生产经营许可证的规定进行生产经营，建立林木种子生产经营档案。"},{"i":22,"n":"第二十二条","txt":"申请者故意隐瞒有关情况或者提供虚假材料申请林木种子生产经营许可证的，申请人在一年内不得再次申请林木种子生产经营许可证。 生产经营者以欺骗、贿赂等不正当手段取得林木种子生产经营许可证的，生产经营者在三年内不得再次申请林木种子生产经营许可证。"},{"i":23,"n":"第二十三条","txt":"有下列情形之一的，县级以上人民政府林业主管部门应当注销林木种子生产经营许可证，并予以公告： （一）林木种子生产经营许可证有效期届满未延续的。 （二）林木种子生产经营许可证被吊销的。 （三）取得林木种子生产经营许可证后，无正当理由满六个月未开展相关生产经营活动或者停止相关生产经营活动满一年的。 （四）生产经营者的营业执照被吊销的。 （五）法律、法规规定的应当注销的其他情形。"},{"i":24,"n":"第二十四条","txt":"林木种子生产经营许可证载明的林木良种被撤销审定或者认定到期的，生产经营者应当自公告发布之日起三十日内到原发证机关申请变更或者注销。"},{"i":25,"n":"第二十五条","txt":"本办法中选育生产经营相结合企业，是指同时具备以下三个条件的林木种子生产经营企业： 1.具有育种科研团队。 2.具有试验示范测试基地。 3.具有自主研发的林木品种。"},{"i":26,"n":"第二十六条","txt":"林木种子生产经营许可证和申请表的格式由国家林业局制定。"},{"i":27,"n":"第二十七条","txt":"本办法自2016年6月1日起施行。国家林业局于2002年12月2日发布、2011年1月25日第一次修改、2015年4月30日第二次修改的《林木种子生产、经营许可证管理办法》同时废止。"}],"linmuzhongzizhiliangguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强林木种子质量管理，根据《中华人民共和国种子法》（以下简称《种子法》）第四十三条的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"从事林木种子的生产、加工、包装、检验、贮藏等质量管理活动，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"本办法所称林木种子，是指乔木、灌木、木质藤本等木本植物和用于林业生产、国土绿化的草本植物的种植材料（苗木）或者繁殖材料，包括籽粒、果实和根、茎、苗、芽、叶等。"},{"i":4,"n":"第四条","txt":"县级以上人民政府林业主管部门及其委托的林木种苗管理机构依法负责林木种子质量的管理工作。"},{"i":5,"n":"第五条","txt":"任何单位和个人有权就林木种子质量问题，向林业主管部门举报，接受举报的部门应当依法负责处理。"},{"i":6,"n":"第六条","txt":"禁止在林木种子不成熟季节、不成熟林分抢采掠青以及损坏母树的树皮、树干、枝条和幼果等，禁止在劣质林内、劣质母树上采集林木种子。"},{"i":7,"n":"第七条","txt":"采集林木种子应当在采种期内进行。 采种期由当地县级人民政府林业主管部门根据林木种子成熟情况及有关规定确定，并在采种期起始日一个月前，利用报刊、电视、广播、因特网等形式对外公布。"},{"i":8,"n":"第八条","txt":"林木种子生产者应当按照国家有关标准对采集的林木种子及时进行脱粒、干燥、净种、分级等加工处理。"},{"i":9,"n":"第九条","txt":"生产主要林木商品种子的，应当按照国家有关标准进行质量检验。 质量低于国家规定的种用标准的林木种子，不得用于销售。"},{"i":10,"n":"第十条","txt":"生产、销售籽粒、果实等有性繁殖材料的林木种子，应当按照国家有关标准进行包装；种植材料（苗木）、无性繁殖材料和其他不能包装的林木种子，可以不经过包装。"},{"i":11,"n":"第十一条","txt":"已经包装的林木种子需要进行分装的，应当注明分装单位和分装日期。"},{"i":12,"n":"第十二条","txt":"销售的林木种子应当附有林木种子标签。 林木种子标签分绿色、白色两种。林木良种种子使用绿色标签、注明品种审定或者认定编号，普通林木种子使用白色标签。"},{"i":13,"n":"第十三条","txt":"林木种子标签的格式由各省、自治区、直辖市林业主管部门统一规定，由生产者和经营者依照规定的格式印制使用。"},{"i":14,"n":"第十四条","txt":"属于繁殖材料的林木种子的生产、经营和使用者应当按照国家有关标准在林木种子库中贮藏林木种子。"},{"i":15,"n":"第十五条","txt":"林木种子库应当具备与所贮藏的林木种子相适应的干燥、净种、检验设备及温度、湿度测量和调节仪器设备。"},{"i":16,"n":"第十六条","txt":"林木种子入库贮藏前和出库时，种子库的管理者应当进行质量检验，将林木种子的净度、含水量和发芽率等质量指标记载于林木种子质量检验证书中。 林木种子质量检验证书的式样，由省、自治区、直辖市人民政府林业主管部门根据国家有关标准制定。"},{"i":17,"n":"第十七条","txt":"在贮藏期间，种子库的管理者应当定期检查检验，及时记载温度、湿度、霉变和病虫害情况，发现问题应当及时采取措施，确保贮藏期间林木种子的质量。"},{"i":18,"n":"第十八条","txt":"县级以上人民政府林业主管部门应当加强林木种子质量监督和管理，根据林木种子的生产、经营情况，制定并组织实施林木种子质量抽查方案。"},{"i":19,"n":"第十九条","txt":"林木种子质量抽查的对象和重点是： （一）主要林木种子生产者、经营者贮藏的用于销售的林木种子； （二）国家投资或者以国家投资为主的造林项目和国有林业单位使用的林木种子。"},{"i":20,"n":"第二十条","txt":"林木种子质量抽查任务可以由县级以上人民政府林业主管部门委托林木种子质量检验机构执行。 承担质量抽查工作的林木种子质量检验机构应当符合《种子法》的有关规定，具备相应的检测条件和能力，并经省级以上人民政府林业主管部门考核合格。"},{"i":21,"n":"第二十一条","txt":"执行林木种子质量抽查任务时，应当由县级以上人民政府林业主管部门向林木种子质量检验机构下达《林木种子质量抽查通知书》。 林木种子质量检验机构应当持《林木种子质量抽查通知书》，按照国家有关标准抽取样品并进行检验。"},{"i":22,"n":"第二十二条","txt":"林木种子质量检验机构完成质量抽查任务后，应当在规定时间内将抽查结果报送下达任务的林业主管部门。 质量抽查结果主要包括以下内容： （一）抽查总结； （二）抽查结果汇总表； （三）林木种子质量总体状况评价； （四）有关单位提出异议、复验等问题的处理情况说明； （五）其他需要说明的情况。"},{"i":23,"n":"第二十三条","txt":"县级以上人民政府林业主管部门应当根据质量抽查结果，及时公布林木种子质量抽查通报。"},{"i":24,"n":"第二十四条","txt":"林木种子质量抽查结果不合格的，由县级以上人民政府林业主管部门依据《种子法》有关规定对其生产者、经营者予以处罚。"},{"i":25,"n":"第二十五条","txt":"违反本办法规定，生产、加工、包装、检验和贮藏林木种子的，由县级以上人民政府林业主管部门依照《种子法》的规定处理；《种子法》未规定的，县级以上人民政府林业主管部门可以根据情节给予警告、限期整改，有违法所得的，可以并处违法所得一倍以上三倍以下且不超过三万元的罚款；没有违法所得的，属于非经营活动的，可以并处一千元以下罚款，属于经营活动的，可以并处一万元以下罚款。"},{"i":26,"n":"第二十六条","txt":"本办法自2007年1月1日起施行。"}],"linmuzhongzhiziyuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强林木种质资源保护和管理，根据《中华人民共和国种子法》的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"从事林木种质资源收集、整理、鉴定、登记、保存、交流、利用和管理等活动，适用本办法。"},{"i":3,"n":"第三条","txt":"依照《中华人民共和国种子法》的规定，林木种质资源是指林木遗传多样性资源和选育新品种的基础材料，包括森林植物的栽培种、野生种的繁殖材料以及利用上述繁殖材料人工创造的遗传材料。 林木种质资源的形态，包括植株、苗、果实、籽粒、根、茎、叶、芽、花、花粉、组织、细胞和DNA、DNA片段及基因等。"},{"i":4,"n":"第四条","txt":"国家林业局负责全国林木种质资源的保护和管理工作，具体工作由其所属的林木种苗管理机构负责。 省、自治区、直辖市人民政府林业主管部门负责本行政区域内林木种质资源的保护和管理工作，具体工作由其所属的林木种苗管理机构负责。"},{"i":5,"n":"第五条","txt":"国家扶持林木种质资源保护工作。县级以上人民政府林业主管部门应当采取有效措施，加强林木种质资源保护管理工作。"},{"i":6,"n":"第六条","txt":"县级以上人民政府林业主管部门应当积极组织开展林木种质资源科学研究，培训林木种质资源专门技术人员，提高林木种质资源保护管理工作水平。"},{"i":7,"n":"第七条","txt":"国家林业局和省、自治区、直辖市人民政府林业主管部门应当组织林木种质资源普查，建立健全林木种质资源档案。 林木种质资源普查结果等数据资料，应当作为制定林木种质资源保护发展方案、制定和调整可供利用的林木种质资源目录的依据。"},{"i":8,"n":"第八条","txt":"全国林木种质资源普查方案由国家林业局制定；地方林木种质资源普查方案由省、自治区、直辖市人民政府林业主管部门制定。"},{"i":9,"n":"第九条","txt":"县级以上人民政府林业主管部门应当根据保护林木种质资源的需要，有计划地组织收集林木种质资源。"},{"i":10,"n":"第十条","txt":"收集林木种质资源的单位和个人，应当建立原始档案并完整保存档案资料。原始档案记载的内容和格式由国家林业局统一规定。"},{"i":11,"n":"第十一条","txt":"因工程建设、自然灾害等特殊情况使林木种质资源受到威胁的，县级以上人民政府林业主管部门应当及时组织抢救性收集。"},{"i":12,"n":"第十二条","txt":"国家林业局和省、自治区、直辖市人民政府林业主管部门应当组织有关专家对收集的林木种质资源进行鉴定。进行林木种质资源鉴定应当严格执行国家标准和行业标准。"},{"i":13,"n":"第十三条","txt":"国家林业局和省、自治区、直辖市人民政府林业主管部门应当对经过鉴定的林木种质资源或者经批准从境外引进的林木种质资源进行登记。林木种质资源登记实行全国统一编号，编号方法由国家林业局规定。任何单位和个人不得更改或者另行编号。"},{"i":14,"n":"第十四条","txt":"国家林业局建立国家林木种质资源库，根据需要保存具有重要价值或者珍贵的林木种质资源。省、自治区、直辖市人民政府林业主管部门可以建立林木种质资源库、林木种质资源保护区或者林木种质资源保护地，根据需要保存乡土树种、地方主要造林树种等林木种质资源。"},{"i":15,"n":"第十五条","txt":"县级以上人民政府应当分别情况采取原地保存或者建立异地保存库、设施保存库等方式，保存林木种质资源，保障国家和地方林木种质资源库、保护区和保护地正常运转和种质资源安全。异地保存库和设施保存库的林木种质资源应当按照有关规定进行定期检查和检测，及时更新和补充。"},{"i":16,"n":"第十六条","txt":"国家林业局和省、自治区、直辖市人民政府林业主管部门应当根据林木种质资源普查结果及鉴定和保存情况，公布可供利用的林木种质资源目录。"},{"i":17,"n":"第十七条","txt":"利用从林木种质资源库获取的林木种质资源，申请植物新品种权或者其他专利权的，应当事先与林木种质资源管理单位签订协议，并分别报省、自治区、直辖市人民政府林业主管部门或者国家林业局备查。"},{"i":18,"n":"第十八条","txt":"利用林木种质资源库的林木种质资源的单位和个人，应当与林木种质资源库管理单位签订协议，按照协议要求承担反馈利用信息的义务。"},{"i":19,"n":"第十九条","txt":"禁止采集或者采伐国家重点保护的天然林木种质资源。因科学研究、良种选育、文化交流、种质资源更新等特殊情况需要采集或者采伐的，除按照有关法律、法规的规定办理采集或者采伐批准文件外，还应当按照本条第二款、第三款的规定办理审批手续。 采集或者采伐国家林木种质资源库内的，申请人应当向国家林业局提交《采集或者采伐林木种质资源申请表》及申请说明，说明内容应当包括采集或者采伐的理由、用途、方案等；国家林业局应当自受理之日起20个工作日内作出审批决定，并出具《采集或者采伐林木种质资源许可表》；不予审批的，应当书面告知申请人并说明理由。 采集或者采伐国家林木种质资源库以外的，应当经省、自治区、直辖市人民政府林业主管部门批准，批准结果报国家林业局备查。"},{"i":20,"n":"第二十条","txt":"国家林业局和省、自治区、直辖市人民政府林业主管部门应当建立林木种质资源信息数据库，开展林木种质资源动态监测。"},{"i":21,"n":"第二十一条","txt":"国家对林木种质资源享有主权。任何单位和个人向境外提供林木种质资源的，应当经国家林业局批准。"},{"i":22,"n":"第二十二条","txt":"向境外提供或者从境外引进林木种质资源的，应当按照以下程序办理审批手续： （一）向国家林业局提交《向境外提供林木种质资源申请表》或者《从境外引进林木种质资源申请表》及其说明； （二）从境外引进林木种质资源的，应当提交引进林木种质资源的用途证明和试验方案材料； （三）向境外提供林木种质资源的，应当提供相关的项目或者协议文本； （四）为境外制种引进林木种质资源的，应当提交对外制种协议文本； （五）国家林业局应当自受理之日起20个工作日内作出审批决定，并出具《向境外提供林木种质资源许可表》或者《从境外引进林木种质资源许可表》；不予审批的，应当书面告知申请人并说明理由。"},{"i":23,"n":"第二十三条","txt":"从境外引进林木种质资源的，应当依法办理检疫审批手续。从境外引进转基因林木种质资源的，应当按照国家林业局公布的《开展林木转基因工程活动审批管理办法》的有关规定办理。"},{"i":24,"n":"第二十四条","txt":"向境外提供的林木种质资源属于国家重点保护野生植物，从境外引进或者向境外提供的林木种质资源属于中国参加的国际公约所限制进出口的野生植物的，除按照本办法第二十一条、第二十二条、第二十三条的规定办理外，还应当按照国家野生植物保护法律法规或者中国参加的国际公约的有关规定办理进出口审批手续。"},{"i":25,"n":"第二十五条","txt":"从境外引进林木种质资源的单位和个人，应当自林木种质资源引进之日起一年之内，向所在地省、自治区、直辖市人民政府林业主管部门提供适量的种质材料，经其登记后移交林木种质资源库保存，并将有关材料报送国家林业局备查。"},{"i":26,"n":"第二十六条","txt":"在林木种质资源普查、收集、鉴定、保存等工作中成绩显著的单位和个人，由县级以上人民政府林业主管部门给予奖励。"},{"i":27,"n":"第二十七条","txt":"林业主管部门及其所属林木种苗管理机构的工作人员在林木种质资源保护管理工作中，滥用职权、玩忽职守、徇私舞弊的，依照国家有关规定给予处分；情节严重、构成犯罪的，依法追究刑事责任。"},{"i":28,"n":"第二十八条","txt":"本办法自2007年11月1日起施行。"}],"linmuliangzhongtuiguangshiyongguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强林木良种推广使用管理，发展高产、优质、高效益的林业，根据《中华人民共和国种子法》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称林木良种，是指经省级以上林木良种审定委员会审定或者认定通过并发给合格证书的林木种子。 未具有林木良种审定或者认定合格证书的林木种子，不得作为林木良种推广使用。"},{"i":3,"n":"第三条","txt":"本办法所称林木良种推广使用，是指通过试验、示范、培训、指导以及咨询服务等，把林木良种应用于林业生产的活动。 从事林木良种推广使用活动，必须遵守本办法。"},{"i":4,"n":"第四条","txt":"县级以上林业行政主管部门应当取采措施鼓励选育林木良种，并对选育林木良种成绩显著的单位或者个人给予奖励。"},{"i":5,"n":"第五条","txt":"县级以上林业行政主管部门负责本行政区域内的林木良种推广使用管理工作。具体工作由其设置的林木种子管理机构组织实施。 县级以上林业行政主管部门应当加强对林木良种推广使用管理工作的领导，将林木良种推广使用管理工作作为领导任期责任制的内容，进行考核。"},{"i":6,"n":"第六条","txt":"县级以上林业行政主管部门应当建立由林木种子管理机构、林业科技推广机构、林业科研单位和院校以及群众科技组织相结合的林木良种推广体系。 县级以上林业行政主管部门应当建立林木良种推广使用示范基地。"},{"i":7,"n":"第七条","txt":"林木良种推广使用计划，由省级以上林业行政主管部门根据林业发展规划和林木良种生产能力制定并组织实施。"},{"i":8,"n":"第八条","txt":"林业科技推广机构的主要任务是： （一）提供与林木良种推广使用有关的技术、信息服务； （二）对推广使用的林木良种进行试验、示范； （三）指导下级林业科技推广机构、群众性科技组织的林木良种推广使用工作。"},{"i":9,"n":"第九条","txt":"林业科研单位和院校应当根据林业经济发展的需要，开展林木良种技术开发和推广工作，加快林木良种的推广使用。 国有林场和苗圃应当带头进行林木良种推广使用示范，并为林农提供推广使用技术服务。"},{"i":10,"n":"第十条","txt":"从事林木良种推广使用工作的专业技术人员，应当具有中专以上学历，经县级以上林业行政主管部门考核并发给资格证书；对专业技术人员的职称评定应当以考核其林木良种推广使用工作的业务水平和实绩为主。 县级以上林业行政主管部门应当有计划组织对从事林木良种推广使用工作的人员进行技术培训和考核。"},{"i":11,"n":"第十一条","txt":"营造速生丰产用材林和经济林，应当使用林木良种。 前款规定之外的工程造林、其他使用国家投资或者由国家扶持造林的项目和国有林场造林，应当根据林木良种推广使用计划分别不同的树种核定良种使用率，实行目标管理，逐步实现造林良种化。 国家投资或者国家投资为主的造林项目和国有林业单位造林，应当根据林业行政主管部门制定的计划使用林木良种，实行目标管理，逐步实现造林良种化。"},{"i":12,"n":"第十二条","txt":"在推广林木良种时，推广林木良种的单位或者个人应当同时向造林单位或者个人提供林木良种的育苗、培育等配套技术。"},{"i":13,"n":"第十三条","txt":"对推广使用林木良种的单位和个人，可以给予适当的经济补贴。具体补贴办法执行各省、自治区、直辖市林业行政主管部门的规定。"},{"i":14,"n":"第十四条","txt":"县级以上林业行政主管部门应当按照《中华人民共和国农业技术推广法》第二十三条的规定，向同级人民政府争取在财政拨款和农业发展基金中安排一定比例的资金份额，用于林木良种的推广使用。 县级以上林业行政主管部门应当安排适当的资金，用于林木良种的推广使用。 任何单位或者个人不得截留或者挪用林木良种推广使用资金。"},{"i":15,"n":"第十五条","txt":"县级以上林业行政主管部门应当加强对林木良种推广使用工作的监督。 对必须使用林木良种的造林项目，县级以上林木种子管理机构应当派人参加造林验收。对国家投资或者国家投资为主的造林项目和国有林业单位造林，应当将使用林木良种的情况作为验收内容。"},{"i":16,"n":"第十六条","txt":"未按照规定使用林木良种造林的项目，林业行政主管部门可以取消林木良种推广使用的经济补贴，并可酌减或者停止该项目下一年度的投资。 对前款行为，林业行政主管部门可以给予警告，并可处1000元以下的罚款。"},{"i":17,"n":"第十七条","txt":"伪造林木良种证书的，由林业行政主管部门或者其委托林木种子管理机构予以没收，并可处1000元以下的罚款；有违法所得的，可处违法所得3倍以内的罚款，但最多不得超过30000元。"},{"i":18,"n":"第十八条","txt":"在林木良种推广使用工作中有突出或者显著贡献的单位或者个人，林业行政主管部门应当给予奖励。"},{"i":19,"n":"第十九条","txt":"本办法由林业部负责解释。"},{"i":20,"n":"第二十条","txt":"本办法自发布之日起施行。"}],"senlinziyuanjiandugongzuoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强森林资源保护管理，规范森林资源监督行为，根据《中华人民共和国森林法实施条例》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国家林业局依照有关规定向各地区、单位派驻森林资源监督专员办事处（以下简称森林资源监督专员办）。"},{"i":3,"n":"第三条","txt":"本办法所称的森林资源监督是指森林资源监督专员办对驻在地区和单位的森林资源保护、利用和管理情况实施监督检查的行为。 森林资源监督是林业行政执法的重要组成部分，是加强森林资源管理的重要措施。"},{"i":4,"n":"第四条","txt":"森林资源监督专员办实施森林资源监督，适用本办法。"},{"i":5,"n":"第五条","txt":"国家林业局设立森林资源监督管理办公室，负责森林资源监督专员办的协调管理和监督业务工作。 国家林业局森林资源管理司归口管理森林资源监督管理办公室和森林资源监督专员办。"},{"i":6,"n":"第六条","txt":"森林资源监督专员办应当按照国家林业局的有关规定，结合实际，建立和健全内部管理制度及岗位责任制度，并报国家林业局备案。"},{"i":7,"n":"第七条","txt":"森林资源监督管理办公室应当加强对森林资源监督专员办的管理，严格考核工作实绩，组织开展业务培训，检查内部管理制度和岗位责任制度落实情况。"},{"i":8,"n":"第八条","txt":"森林资源监督专员办负责实施国家林业局指定范围内的森林资源监督工作，对国家林业局负责。其主要职责是： （一）监督驻在地区、单位的森林资源和林政管理； （三）监督驻在地区、单位建立和执行保护、发展森林资源目标责任制，并负责审核有关执行情况的报告； （三）承担国家林业局确定的和驻在省、自治区、直辖市人民政府或者驻在单位委托的有关森林资源监督的职责； （四）按年度向国家林业局和驻在省、自治区、直辖市人民政府或者单位分别提交森林资源监督报告； （五）承担国家林业局委托的行政审批、行政许可等其他工作。"},{"i":9,"n":"第九条","txt":"森林资源监督专员办在履行职责时，可以依法采取下列措施： （一）责令被监督检查单位停止违反林业法律、法规、政策的行为； （二）要求被监督检查单位提供与监督检查事项有关的材料； （三）要求被监督检查单位对监督检查事项涉及的问题做出书面说明； （四）法律、法规规定可以采取的其他措施。"},{"i":10,"n":"第十条","txt":"森林资源监督专员办对履行职责中发现的问题，应当及时向当地林业主管部门或者有关单位提出处理建议，并对处理建议的落实情况进行跟踪监督，结果报国家林业局。 对省、自治区、直辖市人民政府林业主管部门管辖的、有重大影响的破坏森林资源行为，森林资源监督专员办应当向国家林业局或者驻在省、自治区、直辖市人民政府报告并提出处理意见。 对破坏森林资源行为负有领导责任的人员，森林资源监督专员办应当向其所在单位或者上级机关、监察机关提出给予处分的建议。 破坏森林资源行为涉嫌构成犯罪的，森林资源监督专员办应当督促有关单位将案件移送司法机关。"},{"i":11,"n":"第十一条","txt":"县级以上地方人民政府林业主管部门或者有关单位对森林资源监督专员办提出的处理建议应当及时核实，依法查处，并将处理结果向森林资源监督专员办通报。 县级以上地方人民政府林业主管部门或者有关单位对森林资源监督专员办提出的处理建议有异议的，应当向森林资源监督专员办提出书面意见。 对森林资源监督专员办提出的处理建议，既不依法查处，又不提交书面陈述的，森林资源监督专员办应当向省、自治区、直辖市人民政府提出督办建议，同时报告国家林业局。"},{"i":12,"n":"第十二条","txt":"森林资源监督专员办应当积极支持县级以上地方人民政府林业主管部门加强森林资源管理工作，建立和实行以下工作制度： （一）向省、自治区、直辖市人民政府林业主管部门通报国家有关林业政策和重大林业工作事项； （二）与驻在省、自治区、直辖市人民政府建立工作沟通机制，及时向其通报森林资源监督工作情况； （三）与省、自治区、直辖市人民政府林业主管部门建立林业行政执法联合工作机制； （四）根据需要，适时与省、自治区、直辖市人民政府林业主管部门召开联席会议。"},{"i":13,"n":"第十三条","txt":"县级以上地方人民政府林业主管部门应当积极配合森林资源监督专员办履行职责： （一）向森林资源监督专员办及时提供贯彻国家有关林业政策法规、加强森林资源和林政管理等方面的情况； （二）积极听取森林资源监督专员办反映的问题和建议，研究、落实改进措施； （三）在研究涉及森林资源和林政管理的重大问题时，应当征询森林资源监督专员办的意见。"},{"i":14,"n":"第十四条","txt":"森林资源监督专员办的工作人员应当具备以下条件： （一）遵守法律和职业道德； （二）熟悉林业法律法规和林业方针政策； （三）具备从事森林资源监督工作相适应的专业知识和业务能力； （四）新录用人员具有大学本科以上学历； （五）适应履行监督职责需要的其他条件。"},{"i":15,"n":"第十五条","txt":"森林资源监督专员办工作人员开展森林资源监督工作，应当客观公正，实事求是，廉洁奉公，保守秘密。"},{"i":16,"n":"第十六条","txt":"森林资源监督专员办的工作人员滥用职权、玩忽职守、徇私舞弊的，依法依纪给予处分；构成犯罪的，依法追究刑事责任。"},{"i":17,"n":"第十七条","txt":"东北、内蒙古重点国有林区林业（森工）主管部门派驻森工企业局的森林资源监督机构，其主要负责人的任免应当事前征求国家林业局派驻本地区或者单位的森林资源监督专员办的意见；其森林资源监督业务工作接受国家林业局派驻本地区或者单位的森林资源监督专员办的指导。"},{"i":18,"n":"第十八条","txt":"本办法自2008年1月1日起施行。"}],"zhiwujianyitiaolishishixize":[{"i":1,"n":"第一条","txt":"根据《植物检疫条例》的规定，制定本细则。"},{"i":2,"n":"第二条","txt":"林业部主管全国森林植物检疫（以下简称森检）工作。县级以上地方林业主管部门主管本地区的森检工作。 县级以上地方林业主管部门应当建立健全森检机构，由其负责执行本地区的森检任务。 国有林业局所属的森检机构负责执行本单位的森检任务，但是，须经省级以上林业主管部门确认。"},{"i":3,"n":"第三条","txt":"森检员应当由具有林业专业、森保专业助理工程师以上技术职称的人员或者中等专业学校毕业、连续从事森保工作两年以上的技术员担任。 森检员应当经过省级以上林业主管部门举办的森检培训班培训并取得成绩合格证书，由省、自治区、直辖市林业主管部门批准，发给《森林植物检疫员证》。 森检员执行森检任务时，必须穿着森检制服、佩戴森检标志和出示《森林植物检疫员证》。"},{"i":4,"n":"第四条","txt":"县级以上地方林业主管部门或者其所属的森检机构可以根据需要在林业工作站、国有林场、国有苗圃、贮木场、自然保护区、木材检查站及有关车站、机场、港口、仓库等单位，聘请兼职森检员协助森检机构开展工作。 兼职森检员应当经过县级以上地方林业主管部门举办的森检培训班培训并取得成绩合格证书，由县级以上地方林业主管部门批准，发给兼职森检员证。 兼职森检员不得签发《植物检疫证书》。"},{"i":5,"n":"第五条","txt":"森检人员在执行森检任务时有权行使下列职权： （一）进入车站、机场、港口、仓库和森林植物及其产品的生产、经营、存放等场所，依照规定实施现场检疫或者复检，查验植物检疫证书和进行疫情监测调查； （二）依法监督有关单位或者个人进行消毒处理、除害处理、隔离试种和采取封锁、消灭等措施； （三）依法查阅、摘录或者复制与森检工作有关的资料，收集证据。"},{"i":6,"n":"第六条","txt":"应施检疫的森林植物及其产品包括： （一）林木种子、苗木和其他繁殖材料； （二）乔木、灌木、竹类、花卉和其他森林植物； （三）木材、竹材、药材、果品、盆景和其他林产品。"},{"i":7,"n":"第七条","txt":"确定森检对象及补充森检对象，按照《森林植物检疫对象确定管理办法》的规定办理，补充森检对象名单应当报林业部备案，同时通报有关省、自治区、直辖市林业主管部门。"},{"i":8,"n":"第八条","txt":"疫区、保护区应当按照有关规定划定、改变或者撤销，并采取严格的封锁、消灭等措施，防止森检对象传出或者传入。 在发生疫情的地区，森检机构可以派人参加当地的道路联合检查站或者木材检查站；发生特大疫情时，经省、自治区、直辖市人民政府批准可以设立森检检查站，开展森检工作。"},{"i":9,"n":"第九条","txt":"地方各级森检机构应当每隔三至五年进行一次森检对象普查。 省级林业主管部门所属的森检机构编制森检对象分布至县的资料，报林业部备查；县级林业主管部门所属的森检机构编制森检对象分布至乡的资料，报上一级森检机构备查。 危险性森林病、虫疫情数据由林业部指定的单位编制印发。"},{"i":10,"n":"第十条","txt":"属于森检对象，国外新传入或者国内突发危险性森林病、虫的特大疫情由林业部发布；其他疫情由林业部授权的单位公布。"},{"i":11,"n":"第十一条","txt":"森检机构对新发现的森检对象和其它危险性森林病、虫，应当及时查清情况，立即报告当地人民政府和所在省、自治区、直辖市林业主管部门，采取措施，彻底消灭，并由省、自治区、直辖市林业主管部门向林业部报告。"},{"i":12,"n":"第十二条","txt":"生产、经营应实施检疫的森林植物及其产品的单位和个人，应当在生产和经营之前向当地森检机构备案，并在生产期间或者调运之前向当地森检机构申请产地检疫。对检疫合格的，由森检机构发给《产地检疫合格证》；对检疫不合格的，由森检机构发给《检疫处理通知单》。产地检疫的技术要求按照《国内森林植物检疫技术规程》的规定执行"},{"i":13,"n":"第十三条","txt":"林木种子、苗木和其他繁殖材料的繁育单位，必须有计划地建立无森检对象的种苗繁育基地、母树林基地。 禁止使用带有危险性森林病、虫的林木种子、苗木和其他繁殖材料育苗或者造林。"},{"i":14,"n":"第十四条","txt":"应施检疫的森林植物及其产品运出发生疫情的县级行政区域之前以及调运林木种子、苗木和其他繁殖材料必须经过检疫，取得《植物检疫证书》。 《植物检疫证书》由省、自治区、直辖市森检机构按规定格式统一印制。 《植物检疫证书》按一车（即同一运输工具）一证核发。"},{"i":15,"n":"第十五条","txt":"省际间调运应施检疫的森林植物及其产品，调入单位必须事先征得所在地的省、自治区、直辖市森检机构同意并向调出单位提出检疫要求；调出单位必须根据该检疫要求向所在地的省、自治区、直辖市森检机构或其委托的单位申请检疫。对调入的应施检疫的森林植物及其产品，调入单位所在地的省、自治区、直辖市的森检机构应当查验检疫证书，必要时可以复检。 检疫要求应当根据森检对象，补充森检对象的分布资料和危险性森林病、虫疫情数据提出。"},{"i":16,"n":"第十六条","txt":"出口的应施检疫的森林植物及其产品，在省际间调运时应当按照本细则的规定实施检疫。 从国外进口的应施检疫的森林植物及其产品再次调运出省、自治区、直辖市时，存放时间在一个月以内的，可以凭原检疫单证发给《植物检疫证书》，不收检疫费和证书工本费；存放时间虽未超过一个月但存放地疫情比较严重、可能染疫的，应当按照本细则的规定实施检疫。"},{"i":17,"n":"第十七条","txt":"调运检疫时，森检机构应当按照《国内森林植物检疫技术规程》的规定受理报检和实施检疫，根据当地疫情普查资料、产地检疫合格证和现场检疫检验、室内检疫检验结果，确认是否带有森检对象，补充森检对象或者检疫要求中提出的危险性森林病、虫。对检疫合格的，发给《植物检疫证书》；对发现森检验对象、补充森检对象或者危险性森林病、虫的，发给《检疫处理通知单》，责令托运人在指定地点进行除害处理，合格后发给《植物检疫证书》对无法进行彻底除害处理的，应当停止调运，责令改变用途，控制使用或者就地销毁。"},{"i":18,"n":"第十八条","txt":"森检机构应当自受理检疫申请之日起二十日内实施检疫并核发检疫单证。二十日内不能作出决定的，经森检机构所属的林业主管部门负责人批准，可以延长十日，并告知申请人。"},{"i":19,"n":"第十九条","txt":"调运检疫时，森检机构对可能被森检对象，补充森检对象或者检疫要求中的危险性森林病、虫污染的包装材料、运载工具、场地、仓库等也应实施检疫。如已被污染，托运人应按森检机构的要求进行除害处理。 因实施检疫发生的车船停留、货物搬运、开拆、取样、储存、消毒处理等费用，由托运人承担。复检时发现森检对象，补充森检对象或者检疫要求中的危险性森林病、虫的，除害处理费用由收货人承担。"},{"i":20,"n":"第二十条","txt":"调运应施检疫的森林植物及其产品时，《植物检疫证书》（正本）应当交给交通运输部门或者邮政部门随货运寄，由收货人保存备查。"},{"i":21,"n":"第二十一条","txt":"未取得《植物检疫证书》调运应施检疫的森林植物及其产品的，森检机构应当进行补检，在调运途中被发现的，向托运人收取补检费；在调入地被发现的，向收货人收取补检费。"},{"i":22,"n":"第二十二条","txt":"对省际间发生的森检技术纠纷，由有关省、自治区、直辖市森检机构协商解决；协商解决不了的，报林业部指定的单位或者专家认定。"},{"i":23,"n":"第二十三条","txt":"从国外引进林木种子、苗木和其他繁殖材料，引进单位或者个人应当向所在地的省、自治区、直辖市森检机构提出申请，填写《引进林木种子、苗木和其他繁殖材料检疫审批单》，办理引进检疫审批手续；国务院有关部门所属的在京单位从国外引进林木种子、苗木和其他繁殖材料时，应当向林业部森检管理机构或者其指定的森检单位申请办理检疫审批手续。引进后需要分散到省、自治区、直辖市种植的，应当在申请办理引种检疫审批手续前征得分散种植地所在省、自治区、直辖市林检机构的同意。 引进单位或者个人应当在有关的合同或者协议中订明审批的检疫要求。 森检机构应当自受理引进申请后二十日内作出决定。"},{"i":24,"n":"第二十四条","txt":"从国外引进的林木种子、苗木和其他繁殖材料，有关单位或者个人应当按照审批机关确认的地点和措施进行种植。对可能潜伏有危险性森林病、虫的，一年生植物必须隔离试种一个生长周期，多年生植物至少隔离试种二年以上。经省、自治区、直辖市森检机构检疫，证明确实不带危险性森林病、虫的，方可分散种植。"},{"i":25,"n":"第二十五条","txt":"对森检对象的研究，不得在该森检对象的非疫情发生区进行。因教学、科研需要在非疫情发生区进行时，应当经省、自治区、直辖市林业主管部门批准，并采取严密措施防止扩散。"},{"i":26,"n":"第二十六条","txt":"森检机构收取的检疫费只能用于宣传教育、业务培训、检疫工作补助、临时工工资，购置和维修检疫实验用品、通讯和仪器设备等森检事业，不得挪作他用。"},{"i":27,"n":"第二十七条","txt":"按照《植物检疫条例》第十六条的规定，进行疫情调查和采取消灭措施所需的紧急防治费和补助费，由省、自治区、直辖市在每年的农村造林和林木保护补助费中安排。"},{"i":28,"n":"第二十八条","txt":"各级林业主管部门应当根据森检工作的需要，建设检疫检验室、除害处理设施、检疫隔离试种苗圃等设施。"},{"i":29,"n":"第二十九条","txt":"有下列成绩之一的单位和个人，由人民政府或者林业主管部门给予奖励： （一）与违反森检法规行为作斗争事迹突出的； （二）在封锁、消灭森检对象工作中有显著成绩的； （三）在森检技术研究和推广工作中获得重大成果或者显著效益的； （四）防止危险性森林病、虫传播蔓延作出重要贡献的。"},{"i":30,"n":"第三十条","txt":"有下列行为之一的，森检机构应当责令纠正，可以处以５０元至２０００元罚款；造成损失的，应当责令赔偿；构成犯罪的，由司法机关依法追究刑事责任： （一）未依照规定办理《植物检疫证书》或者在报检过程中弄虚作假的； （二）伪造、涂改、买卖、转让植物检疫单证、印章、标志、封识的； （三）未依照规定调运、隔离试种或者生产应施检疫的森林植物及其产品的； （四）违反规定，擅自开拆森林植物及其产品的包装，调换森林植物及其产品，或者擅自改变森林植物及其产品的规定用途的； （五）违反规定，引起疫情扩散的。 有前款第（一）、（二）、（三）、（四）项所列情形之一，尚不构成犯罪的，森检机构可以没收非法所得。 对违反规定调运的森林植物及其产品，森检机构有权予以封存、没收、销毁或者责令改变用途。销毁所需费用由责任人承担。"},{"i":31,"n":"第三十一条","txt":"森检人员在工作中徇私舞弊、玩忽职守造成重大损失的，由其所在单位或者上级主管机关给予行政处分；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"当事人对森检机构的行政处罚决定不服的，可以自接到处罚通知书之日起六十日内提起行政复议；对复议决定不服的，可以自接到复议决定书之日起十五日内向人民法院提起诉讼。当事人逾期不申请复议或者不起诉又不履行行政处罚决定的，森检机构可以申请人民法院强制执行或者依法强制执行。"},{"i":33,"n":"第三十三条","txt":"本细则中规定的《植物检疫证书》、《产地检疫合格证》、《检疫处理通知单》、《森林植物检疫员证》和《引进林木种子、苗木和其他繁殖材料检疫审批单》等检疫单证的格式，由林业部制定。"},{"i":34,"n":"第三十四条","txt":"本细则由林业部负责解释。"},{"i":35,"n":"第三十五条","txt":"本细则自发布之日起施行。1984年9月17日林业部发布的《<植物检疫条例>实施细则（林业部分）》同时废止。"}],"shidibaohuguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强湿地保护管理，履行《关于特别是作为水禽栖息地的国际重要湿地公约》（以下简称“国际湿地公约”），根据法律法规和有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称湿地，是指常年或者季节性积水地带、水域和低潮时水深不超过6米的海域，包括沼泽湿地、湖泊湿地、河流湿地、滨海湿地等自然湿地，以及重点保护野生动物栖息地或者重点保护野生植物原生地等人工湿地。"},{"i":3,"n":"第三条","txt":"国家对湿地实行全面保护、科学修复、合理利用、持续发展的方针。"},{"i":4,"n":"第四条","txt":"国家林业局负责全国湿地保护工作的组织、协调、指导和监督，并组织、协调有关国际湿地公约的履约工作。 县级以上地方人民政府林业主管部门按照有关规定负责本行政区域内的湿地保护管理工作。"},{"i":5,"n":"第五条","txt":"县级以上人民政府林业主管部门及有关湿地保护管理机构应当加强湿地保护宣传教育和培训，结合世界湿地日、世界野生动植物日、爱鸟周和保护野生动物宣传月等开展宣传教育活动，提高公众湿地保护意识。 县级以上人民政府林业主管部门应当组织开展湿地保护管理的科学研究，应用推广研究成果，提高湿地保护管理水平。"},{"i":6,"n":"第六条","txt":"县级以上人民政府林业主管部门应当鼓励和支持公民、法人以及其他组织，以志愿服务、捐赠等形式参与湿地保护。"},{"i":7,"n":"第七条","txt":"国家林业局会同国务院有关部门编制全国和区域性湿地保护规划，报国务院或者其授权的部门批准。 县级以上地方人民政府林业主管部门会同同级人民政府有关部门，按照有关规定编制本行政区域内的湿地保护规划，报同级人民政府或者其授权的部门批准。"},{"i":8,"n":"第八条","txt":"湿地保护规划应当包括下列内容： （一）湿地资源分布情况、类型及特点、水资源、野生生物资源状况； （二）保护和合理利用的指导思想、原则、目标和任务； （三）湿地生态保护重点建设项目与建设布局； （四）投资估算和效益分析； （五）保障措施。"},{"i":9,"n":"第九条","txt":"经批准的湿地保护规划必须严格执行；未经原批准机关批准，不得调整或者修改。"},{"i":10,"n":"第十条","txt":"国家林业局定期组织开展全国湿地资源调查、监测和评估，按照有关规定向社会公布相关情况。 湿地资源调查、监测、评估等技术规程，由国家林业局在征求有关部门和单位意见的基础上制定。 县级以上地方人民政府林业主管部门及有关湿地保护管理机构应当组织开展本行政区域内的湿地资源调查、监测和评估工作，按照有关规定向社会公布相关情况。"},{"i":11,"n":"第十一条","txt":"县级以上人民政府林业主管部门可以采取湿地自然保护区、湿地公园、湿地保护小区等方式保护湿地，健全湿地保护管理机构和管理制度，完善湿地保护体系，加强湿地保护。"},{"i":12,"n":"第十二条","txt":"湿地按照其生态区位、生态系统功能和生物多样性等重要程度，分为国家重要湿地、地方重要湿地和一般湿地。"},{"i":13,"n":"第十三条","txt":"国家林业局会同国务院有关部门制定国家重要湿地认定标准和管理办法，明确相关管理规则和程序，发布国家重要湿地名录。"},{"i":14,"n":"第十四条","txt":"省、自治区、直辖市人民政府林业主管部门应当在同级人民政府指导下，会同有关部门制定地方重要湿地和一般湿地认定标准和管理办法，发布地方重要湿地和一般湿地名录。"},{"i":15,"n":"第十五条","txt":"符合国际湿地公约国际重要湿地标准的，可以申请指定为国际重要湿地。 申请指定国际重要湿地的，由国务院有关部门或者湿地所在地省、自治区、直辖市人民政府林业主管部门向国家林业局提出。国家林业局应当组织论证、审核，对符合国际重要湿地条件的，在征得湿地所在地省、自治区、直辖市人民政府和国务院有关部门同意后，报国际湿地公约秘书处核准列入《国际重要湿地名录》。"},{"i":16,"n":"第十六条","txt":"国家林业局对国际重要湿地的保护管理工作进行指导和监督，定期对国际重要湿地的生态状况开展检查和评估，并向社会公布结果。 国际重要湿地所在地的县级以上地方人民政府林业主管部门应当会同同级人民政府有关部门对国际重要湿地保护管理状况进行检查，指导国际重要湿地保护管理机构维持国际重要湿地的生态特征。"},{"i":17,"n":"第十七条","txt":"国际重要湿地保护管理机构应当建立湿地生态预警机制，制定实施管理计划，开展动态监测，建立数据档案。"},{"i":18,"n":"第十八条","txt":"因气候变化、自然灾害等造成国际重要湿地生态特征退化的，省、自治区、直辖市人民政府林业主管部门应当会同同级人民政府有关部门进行调查，指导国际重要湿地保护管理机构制定实施补救方案，并向同级人民政府和国家林业局报告。 因工程建设等造成国际重要湿地生态特征退化甚至消失的，省、自治区、直辖市人民政府林业主管部门应当会同同级人民政府有关部门督促、指导项目建设单位限期恢复，并向同级人民政府和国家林业局报告；对逾期不予恢复或者确实无法恢复的，由国家林业局会商所在地省、自治区、直辖市人民政府和国务院有关部门后，按照有关规定处理。"},{"i":19,"n":"第十九条","txt":"具备自然保护区建立条件的湿地，应当依法建立自然保护区。 自然保护区的建立和管理按照自然保护区管理的有关规定执行。"},{"i":20,"n":"第二十条","txt":"以保护湿地生态系统、合理利用湿地资源、开展湿地宣传教育和科学研究为目的，并可供开展生态旅游等活动的湿地，可以设立湿地公园。 湿地公园分为国家湿地公园和地方湿地公园。"},{"i":21,"n":"第二十一条","txt":"国家湿地公园实行晋升制。符合下列条件的，可以申请晋升为国家湿地公园： （一）湿地生态系统在全国或者区域范围内具有典型性，或者湿地区域生态地位重要，或者湿地主体生态功能具有典型示范性，或者湿地生物多样性丰富，或者集中分布有珍贵、濒危的野生生物物种； （二）具有重要或者特殊科学研究、宣传教育和文化价值； （三）成为省级湿地公园两年以上（含两年）； （四）保护管理机构和制度健全； （五）省级湿地公园总体规划实施良好； （六）土地权属清晰，相关权利主体同意作为国家湿地公园； （七）湿地保护、科研监测、科普宣传教育等工作取得显著成效。"},{"i":22,"n":"第二十二条","txt":"申请晋升为国家湿地公园的，由省、自治区、直辖市人民政府林业主管部门向国家林业局提出申请。 国家林业局在收到申请后，组织论证审核，对符合条件的，晋升为国家湿地公园。"},{"i":23,"n":"第二十三条","txt":"省级以上人民政府林业主管部门应当对国家湿地公园的建设和管理进行监督检查和评估。 因自然因素或者管理不善导致国家湿地公园条件丧失的，或者对存在问题拒不整改或者整改不符合要求的，国家林业局应当撤销国家湿地公园的命名，并向社会公布。"},{"i":24,"n":"第二十四条","txt":"地方湿地公园的设立和管理，按照地方有关规定办理。"},{"i":25,"n":"第二十五条","txt":"因保护湿地给湿地所有者或者经营者合法权益造成损失的，应当按照有关规定予以补偿。"},{"i":26,"n":"第二十六条","txt":"县级以上人民政府林业主管部门及有关湿地保护管理机构应当组织开展退化湿地修复工作，恢复湿地功能或者扩大湿地面积。"},{"i":27,"n":"第二十七条","txt":"县级以上人民政府林业主管部门及有关湿地保护管理机构应当开展湿地动态监测，并在湿地资源调查和监测的基础上，建立和更新湿地资源档案。"},{"i":28,"n":"第二十八条","txt":"县级以上人民政府林业主管部门应当对开展生态旅游等利用湿地资源的活动进行指导和监督。"},{"i":29,"n":"第二十九条","txt":"除法律法规有特别规定的以外，在湿地内禁止从事下列活动： （一）开（围）垦、填埋或者排干湿地； （二）永久性截断湿地水源； （三）挖沙、采矿； （四）倾倒有毒有害物质、废弃物、垃圾； （五）破坏野生动物栖息地和迁徙通道、鱼类洄游通道，滥采滥捕野生动植物； （六）引进外来物种； （七）擅自放牧、捕捞、取土、取水、排污、放生； （八）其他破坏湿地及其生态功能的活动。"},{"i":30,"n":"第三十条","txt":"建设项目应当不占或者少占湿地，经批准确需征收、占用湿地并转为其他用途的，用地单位应当按照“先补后占、占补平衡”的原则，依法办理相关手续。 临时占用湿地的，期限不得超过2年；临时占用期限届满，占用单位应当对所占湿地限期进行生态修复。"},{"i":31,"n":"第三十一条","txt":"县级以上地方人民政府林业主管部门应当会同同级人民政府有关部门，在同级人民政府的组织下建立湿地生态补水协调机制，保障湿地生态用水需求。"},{"i":32,"n":"第三十二条","txt":"县级以上人民政府林业主管部门应当按照有关规定开展湿地防火工作，加强防火基础设施和队伍建设。"},{"i":33,"n":"第三十三条","txt":"县级以上人民政府林业主管部门应当会同同级人民政府有关部门协调、组织、开展湿地有害生物防治工作；湿地保护管理机构应当按照有关规定承担湿地有害生物防治的具体工作。"},{"i":34,"n":"第三十四条","txt":"县级以上人民政府林业主管部门应当会同同级人民政府有关部门开展湿地保护执法活动，对破坏湿地的违法行为依法予以处理。"},{"i":35,"n":"第三十五条","txt":"本规定自2013年5月1日起施行。"}],"tufalinyeyouhaishengwushijianchuzhibanfa":[{"i":1,"n":"第一条","txt":"为了及时处置突发林业有害生物事件，控制林业有害生物传播、蔓延，减少灾害损失，根据《森林病虫害防治条例》和《植物检疫条例》等有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称林业有害生物,是指危害森林、林木和林木种子正常生长并造成经济损失的病、虫、杂草等有害生物。"},{"i":3,"n":"第三条","txt":"本办法所称突发林业有害生物事件,是指发生暴发性、危险性或者大面积的林业有害生物危害事件,包括: （一）林业有害生物直接危及人类健康的; （二）从国(境)外新传入林业有害生物的; （三）新发生林业检疫性有害生物疫情的; （四）林业非检疫性有害生物导致叶部受害连片成灾面积1万公顷以上、枝干受害连片成灾面积0.1万公顷以上的。"},{"i":4,"n":"第四条","txt":"突发林业有害生物事件分为一级和二级。 直接危及人类健康的突发林业有害生物事件，为一级突发林业有害生物事件；一级突发林业有害生物事件以外的其他突发林业有害生物事件，为二级突发林业有害生物事件。"},{"i":5,"n":"第五条","txt":"一级突发林业有害生物事件，由国家林业局确认；二级突发林业有害生物事件，由省、自治区、直辖市人民政府林业主管部门确认。 属于从国(境)外新传入的林业有害生物,以及首次在省、自治区、直辖市范围内发生的林业检疫性有害生物,应当经过国家林业局林业有害生物检验鉴定中心鉴定。"},{"i":6,"n":"第六条","txt":"国家林业局负责组织、协调和指导全国突发林业有害生物事件的处置工作。 县级以上地方人民政府林业主管部门在人民政府领导下,具体负责本辖区内突发林业有害生物事件的处置工作。"},{"i":7,"n":"第七条","txt":"国家林业局负责组织制定一级突发林业有害生物事件应急预案。省、自治区、直辖市人民政府林业主管部门负责组织制定本辖区的二级突发林业有害生物事件应急预案。 突发林业有害生物事件应急预案的主要内容是:应急处置指挥体系及其工作职责、预警和预防机制、应急响应、后期评估与善后处理、保障措施等。"},{"i":8,"n":"第八条","txt":"县级人民政府林业主管部门应当根据突发林业有害生物事件应急预案,制定本辖区的突发林业有害生物事件应急实施方案。 突发林业有害生物事件应急实施方案的主要内容是： （一）应急处置指挥机构和人员； （二）应急处置工作职责和程序； （三）林业有害生物控制和防治措施； （四）林业有害生物应急处置物质保障。"},{"i":9,"n":"第九条","txt":"县级以上人民政府林业主管部门应当加强林业有害生物测报试验室、检疫检验试验室、林木种苗及木材除害设施、物资储备仓库、通讯设备等基础设施建设,做好药剂、器械等有关物资的储备。"},{"i":10,"n":"第十条","txt":"县级人民政府林业主管部门应当组织对突发林业有害生物事件应急处置救灾人员的专业技术培训,开展技术演练,提高应急处置技能。"},{"i":11,"n":"第十一条","txt":"县级以上人民政府林业主管部门的森林病虫害防治机构及其中心测报点,应当及时对林业有害生物进行调查与监测,综合分析测报数据,提出防治方案。 森林病虫害防治机构及其中心测报点,应当建立林业有害生物监测档案,掌握林业有害生物的动态变化情况。 乡(镇)林业站工作人员、护林员按照县级以上人民政府林业主管部门的要求,参加林业有害生物的调查与监测工作。"},{"i":12,"n":"第十二条","txt":"森林病虫害防治机构及其中心测报点,发现疑似突发林业有害生物事件等异常情况的,应当立即向所在地县级人民政府林业主管部门报告。 公民、法人或者其他组织发现有疑似突发林业有害生物事件等异常情况的,应当向县级以上人民政府林业主管部门反映。"},{"i":13,"n":"第十三条","txt":"县级人民政府林业主管部门接到疑似突发林业有害生物事件等异常情况的报告或者有关情况反映的，应当及时开展调查核实；认为属于突发林业有害生物事件的，应当按照有关规定逐级上报国家林业局。 突发林业有害生物事件的报告,主要包括有害生物的种类、发生地点和时间、级别、危害程度、已经采取的措施以及相关图片材料等内容。"},{"i":14,"n":"第十四条","txt":"国家林业局或者省、自治区、直辖市人民政府林业主管部门应当组织专家和有关人员对县级人民政府林业主管部门报告的情况进行调查和论证，确认是否属于突发林业有害生物事件。 经确认属于一级突发林业有害生物事件的，国家林业局应当启动应急预案；经确认属于二级突发林业有害生物事件的，省、自治区、直辖市人民政府林业主管部门应当启动应急预案。"},{"i":15,"n":"第十五条","txt":"国家林业局应当按照国务院有关灾害报告制度的规定,及时向国务院报告突发林业有害生物事件的有关情况。 一级突发林业有害生物事件的有关信息,由国家林业局按照规定发布。二级突发林业有害生物事件的有关信息,由省、自治区、直辖市人民政府林业主管部门按照规定发布。"},{"i":16,"n":"第十六条","txt":"突发林业有害生物事件应急预案批准启动实施后,发生地的县级人民政府林业主管部门应当相应启动应急实施方案,立即采取紧急控制措施,切断传播途径,防止扩散蔓延。"},{"i":17,"n":"第十七条","txt":"应急预案和应急实施方案符合规定的终止条件的,方可终止。"},{"i":18,"n":"第十八条","txt":"省、自治区、直辖市人民政府林业主管部门应当根据突发林业有害生物事件应急处理的需要,依法提出疫区划定方案和检疫检查站设立计划,报省、自治区、直辖市人民政府批准后实施。"},{"i":19,"n":"第十九条","txt":"发生一级突发林业有害生物事件,由国家林业局组织专家开展科学研究,收集相关资料,提出综合评估报告;发生二级突发林业有害生物事件,由省、自治区、直辖市人民政府林业主管部门组织专家开展科学研究,收集相关资料,提出综合评估报告。 县级人民政府林业主管部门应当根据综合评估报告修改、完善应急实施方案。"},{"i":20,"n":"第二十条","txt":"对直接危及人类健康、从国(境)外新传入或者跨省、自治区、直辖市传播的林业有害生物,国家林业局和有关省、自治区、直辖市人民政府林业主管部门应当及时组织科研力量研究防治措施,制定相关的检验检疫技术标准,并依法确定是否列为林业检疫性有害生物。"},{"i":21,"n":"第二十一条","txt":"林业主管部门、森林病虫害防治机构及其中心测报点的工作人员玩忽职守、徇私舞弊,造成林业有害生物传播、蔓延的,依法给予处分;情节严重、构成犯罪的,依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"本办法自2005年7月1日起施行。"}],"yinglixingzhishaguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范营利性治沙管理活动，保障从事营利性治沙活动的单位和个人的合法权益，根据《中华人民共和国防沙治沙法》（以下简称防沙治沙法）有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在全国防沙治沙规划确定范围内从事营利性治沙活动适用本办法。 营利性治沙活动是指不具有沙化土地所有权或者使用权的单位和个人，在依法取得土地使用权后，以获取一定经济收益为目的，采取各种措施对沙化土地进行治理的治沙活动。"},{"i":3,"n":"第三条","txt":"县级以上地方人民政府林业行政主管部门负责营利性治沙活动的受理申请和检查验收等管理工作。"},{"i":4,"n":"第四条","txt":"从事营利性治理国家所有的沙化土地的单位和个人，应当与法律授权管理该沙化土地的主管部门或者该沙化土地的使用权人签定治理协议，依法取得该沙化土地的土地使用权。 从事营利性治理集体所有、尚未承包到户的沙化土地的单位和个人，应当与该集体经济组织签订治理协议，依法取得该沙化土地的土地使用权。 从事营利性治理集体所有、但已承包到户的沙化土地的单位和个人，应当与该土地的承包人签订治理协议，依法取得该沙化土地的土地使用权。"},{"i":5,"n":"第五条","txt":"营利性治沙涉及的沙化土地在县级行政区域范围内的，由所在地的县级人民政府林业行政主管部门负责受理申请；跨县（市）、设区的市、自治州行政区域范围的，由其共同上一级地方人民政府林业行政主管部门负责受理申请。"},{"i":6,"n":"第六条","txt":"从事营利性治沙活动的单位和个人应当依照防沙治沙法第二十六条第二款规定提供有关材料，向林业行政主管部门提出治理申请，并填写治理申请表。其中有关治理协议的主要内容应当包括：治理单位名称或者个人姓名、协议双方的权利和义务、拟治理沙化土地的四至界限、面积、治理期限、违约责任等。"},{"i":7,"n":"第七条","txt":"防沙治沙法第二十七条第六项规定的其他需要载明的事项应当包括：被治理的沙化土地的现状，治理后该土地的利用方向，治理项目的投资概算及资金来源等。"},{"i":8,"n":"第八条","txt":"林业行政主管部门应当在收到治理申请和有关文件后7个工作日内，对申请材料进行初步审查；治理申请和有关文件符合本办法第六条和第七条规定的，林业行政主管部门应当予以受理；不符合规定的，不予受理，并书面通知申请人，说明理由或者要求补充有关材料。"},{"i":9,"n":"第九条","txt":"林业行政主管部门对决定受理的申请，应当组织有关专家对治理方案进行技术论证，并可以根据实际工作需要，组织工作人员对提出营利性治沙活动申请涉及的沙化土地以及提交的有关文件内容进行实地核实和调查。 核实和调查的工作人员应当不少于2人。"},{"i":10,"n":"第十条","txt":"林业行政主管部门在决定受理申请之日起30个工作日内，对符合防沙治沙法和本办法规定的，应当予以公示，并书面通知申请人。公示应当载明下列主要内容： （一）申请单位名称或者个人姓名； （二）治理的沙化土地范围、四至以及面积； （三）治理的沙化土地的所有权或者使用权情况，以及发放有关权属证书情况； （四）治理方案的主要内容。"},{"i":11,"n":"第十一条","txt":"有以下情况之一的，林业行政主管部门应当不予公示，并书面通知申请人： （一）治理地点不符合国家和当地防沙治沙规划的； （二）未取得治理范围内土地使用权的； （三）资金没有保障的； （四）治理方案未通过专家技术论证的。"},{"i":12,"n":"第十二条","txt":"从事营利性治沙的单位和个人，必须按照公示的治理方案进行治理。"},{"i":13,"n":"第十三条","txt":"需要变更原治理方案的，应当向原公示的林业行政主管部门提出变更治理方案的书面申请。"},{"i":14,"n":"第十四条","txt":"变更治理方案的书面申请应当包括以下内容： （一）原书面公示文件； （二）原治理方案； （三）治理方案变更的具体内容和理由。 变更的治理方案中规定的治理技术指标应当优于原治理方案规定的治理技术指标。"},{"i":15,"n":"第十五条","txt":"林业行政主管部门应当在接到变更申请后15个工作日内，做出同意变更或者不同意变更的决定，并书面通知提出变更的申请人。 未经原批准的林业行政主管部门批准，任何单位和个人不得改变公示的治理方案。"},{"i":16,"n":"第十六条","txt":"从事营利性治沙的单位和个人可以要求林业行政主管部门给予指导。林业行政主管部门应当根据从事营利性治沙的单位和个人的要求，在下列方面给予指导： （一）有关防沙治沙工作的政策和法规咨询； （二）编制治理方案； （三）编制年度作业设计； （四）提供相关的技术培训。"},{"i":17,"n":"第十七条","txt":"从事营利性治沙的单位和个人在完成治理方案规定的治理任务后，应当向原公示的林业行政主管部门提出验收申请，并填写营利性治沙验收申请表。"},{"i":18,"n":"第十八条","txt":"林业行政主管部门在收到验收申请后30个工作日内，应当按照治理方案确定的各项技术指标组织检查验收。 对验收合格的，林业行政主管部门应当发给治理合格证明文件；对验收不合格的，从事营利性治沙的单位和个人应当继续治理。 对验收合格的森林、林木和林地，从事营利性治沙的单位和个人应当持治理合格证明文件，依法申请森林、林木和林地权属登记。"},{"i":19,"n":"第十九条","txt":"从事营利性治沙的单位和个人可以依照防沙治沙法的规定，享受资金补助、财政贴息以及税费减免等政策优惠。"},{"i":20,"n":"第二十条","txt":"林业行政主管部门依照防沙治沙法第四十一条的规定，对从事营利性治沙活动中不按照治理方案进行治理，或者经林业行政主管部门验收不合格又不按要求继续治理的单位和个人，依法予以处罚。"},{"i":21,"n":"第二十一条","txt":"林业行政主管部门工作人员在管理活动中滥用职权、玩忽职守、徇私舞弊的，依法给予行政处分，构成犯罪的，依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"依照防沙治沙法第二十六条第二款规定，由县级以上地方人民政府指定的其他行政主管部门负责营利性治沙活动的受理申请和检查验收的，可以参照本办法规定执行。"},{"i":23,"n":"第二十三条","txt":"治理申请表和营利性治沙验收表的格式由国家林业局规定，省、自治区和直辖市人民政府林业行政主管部门印制。"},{"i":24,"n":"第二十四条","txt":"本办法于2004年9月1日起施行。"}],"yeshengdongzhiwujinchukouzhengshuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范野生动植物进出口证书管理，根据《中华人民共和国濒危野生动植物进出口管理条例》、《国务院对确需保留的行政审批项目设定行政许可的决定》及《濒危野生动植物种国际贸易公约》（以下简称公约）等规定，制定本办法。"},{"i":2,"n":"第二条","txt":"通过货运、邮递、快件和旅客携带等方式进出口野生动植物及其产品的，适用本办法的规定。"},{"i":3,"n":"第三条","txt":"依法进出口野生动植物及其产品的，实行野生动植物进出口证书管理。 野生动植物进出口证书包括允许进出口证明书和物种证明。 进出口列入《进出口野生动植物种商品目录》（以下简称商品目录）中公约限制进出口的濒危野生动植物及其产品、出口列入商品目录中国家重点保护的野生动植物及其产品的，实行允许进出口证明书管理。 进出口列入前款商品目录中的其他野生动植物及其产品的，实行物种证明管理。 商品目录由中华人民共和国濒危物种进出口管理办公室（以下简称国家濒管办）和海关总署共同制定、调整并公布。"},{"i":4,"n":"第四条","txt":"允许进出口证明书和物种证明由国家濒管办核发；国家濒管办办事处代表国家濒管办核发允许进出口证明书和物种证明。 国家濒管办办事处核发允许进出口证明书和物种证明的管辖区域由国家濒管办确定并予以公布。 允许进出口证明书和物种证明由国家濒管办组织统一印制。"},{"i":5,"n":"第五条","txt":"国家濒管办及其办事处依法对被许可人使用允许进出口证明书和物种证明进出口野生动植物及其产品的情况进行监督检查。"},{"i":6,"n":"第六条","txt":"禁止进出口列入国家《禁止进出口货物目录》的野生动植物及其产品。"},{"i":7,"n":"第七条","txt":"申请核发允许进出口证明书的，申请人应当根据申请的内容和国家濒管办公布的管辖区域向国家濒管办或者其办事处提出申请。"},{"i":8,"n":"第八条","txt":"申请核发允许进出口证明书的，申请人应当提交下列材料： （一）允许进出口证明书申请表。申请人为单位的，应当加盖本单位印章；申请人为个人的，应当有本人签字或者印章。 （二）国务院野生动植物主管部门的进出口批准文件。 （三）进出口合同。但是以非商业贸易为目的个人所有的野生动植物及其产品进出口的除外。 （四）身份证明材料。申请人为单位的，应当提交营业执照复印件或者其他身份证明；申请人为个人的，应当提交身份证件复印件。 （五）进出口含野生动植物成份的药品、食品等产品的，应当提交物种成份含量表和产品说明书。 （六）出口野生动植物及其产品的，应当提交证明野外或者人工繁育等来源类型的材料。 （七）国家濒管办公示的其他应当提交的材料。"},{"i":9,"n":"第九条","txt":"申请进出口公约附录所列的野生动植物及其产品的，申请人还应当提交下列材料： （一）进口公约附录所列野生动植物及其产品的，应当提交境外公约管理机构核发的允许出口证明材料。公约规定由进口国先出具允许进口证明材料的除外。 （二）进出口活体野生动物的，应当提交证明符合公约规定的装运条件的材料。其中，进口公约附录I所列活体野生动物的，还应当提交接受者在笼舍安置、照管等方面的文字和图片材料。 （三）出口公约附录I所列野生动植物及其产品，或者进口后再出口公约附录I所列活体野生动植物的，应当提交境外公约管理机构核发的允许进口证明材料。公约规定由出口国先出具允许出口证明材料的除外。 与非公约缔约国之间进行野生动植物及其产品进出口的，申请人提交的证明材料应当是在公约秘书处注册的机构核发的允许进出口证明材料。"},{"i":10,"n":"第十条","txt":"进口后再出口野生动植物及其产品的，应当提交经海关签注的允许进出口证明书复印件和海关进口货物报关单复印件。进口野生动植物原料加工后再出口的，还应当提交相关生产加工的转换计划及说明；以加工贸易方式进口后再出口野生动植物及其产品的，提交海关核发的加工贸易手册复印件或者电子化手册、电子账册相关内容（表头及相关表体部分）打印件。 以加工贸易方式进口野生动植物及其产品的，应当提交海关核发的加工贸易手册复印件或者电子化手册、电子账册相关内容（表头及相关表体部分）打印件。"},{"i":11,"n":"第十一条","txt":"申请人委托代理人代为申请的，应当提交代理人身份证明和委托代理合同；申请商业性进出口的，还应当提交申请人或者代理人允许从事对外贸易经营活动的资质证明。"},{"i":12,"n":"第十二条","txt":"国家濒管办及其办事处在收到核发允许进出口证明书的申请后，对申请材料齐全、符合法定形式的，应当出具受理通知书；对申请材料不齐或者不符合法定形式的，应当出具补正材料通知书，并一次性告知申请人需要补正的全部内容。对依法应当不予受理的，应当告知申请人并说明理由，出具不予受理通知书。"},{"i":13,"n":"第十三条","txt":"国家濒管办及其办事处核发允许进出口证明书，需要咨询国家濒危物种进出口科学机构意见的、需要向境外相关机构核实允许进出口证明材料的，或者需要对出口的野生动植物及其产品进行实地核查的，应当在出具受理通知书时，告知申请人。 咨询意见、核实允许进出口证明材料和实地核查所需时间不计入核发允许进出口证明书工作日之内。"},{"i":14,"n":"第十四条","txt":"有下列情形之一的，国家濒管办及其办事处不予核发允许进出口证明书： （一）申请内容不符合《中华人民共和国濒危野生动植物进出口管理条例》或者公约规定的。 （二）申请内容与国务院野生动植物主管部门的进出口批准文件不符的。 （三）经国家濒危物种进出口科学机构认定可能对本物种或者其他相关物种野外种群的生存造成危害的。 （四）因申请人的原因，致使核发机关无法进行实地核查的。 （五）提供虚假申请材料的。"},{"i":15,"n":"第十五条","txt":"国家濒管办及其办事处自收到申请之日起20个工作日内，对准予行政许可的，应当核发允许进出口证明书；对不予行政许可的，应当作出不予行政许可的书面决定，并说明理由，同时告知申请人享有的权利。 国家濒管办及其办事处作出的不予行政许可的书面决定应当抄送国务院野生动植物主管部门。 在法定期限内不能作出决定的，经国家濒管办负责人批准，可以延长10个工作日，并将延长期限的理由告知申请人。"},{"i":16,"n":"第十六条","txt":"对准予核发允许进出口证明书的，申请人在领取允许进出口证明书时，应当按照国家规定缴纳野生动植物进出口管理费。"},{"i":17,"n":"第十七条","txt":"允许进出口证明书的有效期不得超过180天。"},{"i":18,"n":"第十八条","txt":"被许可人需要对允许进出口证明书上记载的进出口口岸、境外收发货人进行变更的，应当在允许进出口证明书有效期届满前向原发证机关提出书面变更申请。 被许可人需要延续允许进出口证明书有效期的，应当在允许进出口证明书有效期届满15日前向原发证机关提出书面延期申请。 原发证机关应当根据申请，在允许进出口证明书有效期届满前作出是否准予变更或者延期的决定。"},{"i":19,"n":"第十九条","txt":"允许进出口证明书损坏的，被许可人可以在允许进出口证明书有效期届满前向原发证机关提出补发的书面申请并说明理由，同时将已损坏的允许进出口证明书交回原发证机关。 原发证机关应当根据申请，在允许进出口证明书有效期届满前作出是否准予补发的决定。"},{"i":20,"n":"第二十条","txt":"进出口野生动植物及其产品的，被许可人应当在自海关放行之日起30日内，将海关验讫的允许进出口证明书副本和海关进出口货物报关单复印件交回原发证机关。进口野生动植物及其产品的，还应当同时交回境外公约管理机构核发的允许出口证明材料正本。 未实施进出口野生动植物及其产品活动的，被许可人应当在允许进出口证明书有效期届满后30日内将允许进出口证明书退回原发证机关。"},{"i":21,"n":"第二十一条","txt":"有下列情形之一的，国家濒管办及其办事处应当注销允许进出口证明书： （一）允许进出口证明书依法被撤回、撤销的。 （二）允许进出口证明书有效期届满未延续的。 （三）被许可人死亡或者依法终止的。 （四）因公约或者法律法规调整致使允许进出口证明书许可事项不能实施的。 （五）因不可抗力致使允许进出口证明书许可事项无法实施的。"},{"i":22,"n":"第二十二条","txt":"允许进出口证明书被注销的，申请人不得继续使用该允许进出口证明书从事进出口活动，并应当及时将允许进出口证明书交回原发证机关。"},{"i":23,"n":"第二十三条","txt":"申请核发物种证明的，申请人应当根据申请的内容和国家濒管办公布的管辖区域向国家濒管办或者其办事处提出申请。"},{"i":24,"n":"第二十四条","txt":"申请核发物种证明的，申请人应当提交下列材料： （一）物种证明申请表。申请人为单位的，应当加盖本单位印章；申请人为个人的，应当有本人签字或者加盖印章。 （二）进出口合同。但是以非商业贸易为目的个人所有的野生动植物及其产品进出口的除外。 （三）身份证明材料。申请人为单位的，应当提交营业执照复印件或者其他身份证明；申请人为个人的，应当提交身份证件复印件。 （四）进出口含野生动植物成份的药品、食品等产品的，应当提交物种成份含量表和产品说明书。 （五）出口野生动植物及其产品的，应当提交合法来源证明材料。 （六）进口野生动植物及其产品的，应当提交境外相关机构核发的原产地证明、植物检疫证明或者提货单等能够证明进口野生动植物及其产品真实性的材料。 （七）进口的活体野生动物属于外来陆生野生动物的，应当提交国务院陆生野生动物主管部门同意引进的批准文件。 （八）进口后再出口野生动植物及其产品的，应当提交加盖"},{"i":25,"n":"第二十五条","txt":"申请人委托代理人代为申请的，应当提交代理人身份证明和委托代理合同；申请商业性进出口的，还应当提交申请人或者代理人允许从事对外贸易经营活动的资质证明。"},{"i":26,"n":"第二十六条","txt":"国家濒管办及其办事处在收到核发物种证明的申请后，对申请材料齐全、符合法定形式的，应当出具受理通知书；对申请材料不齐或者不符合法定形式的，应当出具补正材料通知书，并一次性告知申请人需要补正的全部内容。对依法应当不予受理的，应当告知申请人并说明理由，出具不予受理通知书。"},{"i":27,"n":"第二十七条","txt":"有下列情形之一的，国家濒管办及其办事处不予核发物种证明： （一）不能证明其来源合法的。 （二）提供虚假申请材料的。"},{"i":28,"n":"第二十八条","txt":"国家濒管办及其办事处自收到申请之日起20个工作日内，对准予行政许可的，应当核发物种证明；对不予行政许可的，应当作出不予行政许可的书面决定，并说明理由，同时告知申请人享有的权利。 在法定期限内不能作出决定的，经国家濒管办负责人批准，可以延长10个工作日，并将延长期限的理由告知申请人。"},{"i":29,"n":"第二十九条","txt":"物种证明分为一次使用和多次使用两种。"},{"i":30,"n":"第三十条","txt":"对于同一物种、同一货物类型并在同一报关口岸多次进出口野生动植物及其产品的，申请人可以向国家濒管办指定的办事处申请核发多次使用物种证明；但属于下列情形的，不得申请核发多次使用物种证明： （一）出口国家保护的有益的或者有重要经济、科学研究价值的陆生野生动物及其产品的。 （二）进口或者进口后再出口与国家保护的有益的或者有重要经济、科学研究价值的陆生野生动物同名的陆生野生动物及其产品的。 （三）出口与国家重点保护野生植物同名的人工培植来源的野生植物及其产品的。 （四）进口或者进口后再出口与国家重点保护野生动植物同名的野生动植物及其产品的。 （五）进口或者进口后再出口非原产我国的活体陆生野生动物的。 （六）国家濒管办公示的其他情形。"},{"i":31,"n":"第三十一条","txt":"一次使用的物种证明有效期不得超过180天。多次使用的物种证明有效期不得超过360天。"},{"i":32,"n":"第三十二条","txt":"被许可人需要对物种证明上记载的进出口口岸、境外收发货人进行变更的，应当在物种证明有效期届满前向原发证机关提出书面变更申请。 被许可人需要延续物种证明有效期的，应当在物种证明有效期届满15日前向原发证机关提出书面延期申请。 原发证机关应当根据申请，在物种证明有效期届满前作出是否准予变更或者延期的决定。"},{"i":33,"n":"第三十三条","txt":"物种证明损坏的，被许可人可以在物种证明有效期届满前向原发证机构提出补发的书面申请并说明理由，同时将已损坏的物种证明交回原发证机关。 原发证机关应当根据申请，在物种证明有效期届满前作出是否准予补发的决定。"},{"i":34,"n":"第三十四条","txt":"进出口商品目录中的野生动植物及其产品的，应当向海关主动申报并同时提交允许进出口证明书或者物种证明，并按照允许进出口证明书或者物种证明规定的种类、数量、口岸、期限完成进出口活动。"},{"i":35,"n":"第三十五条","txt":"进出口商品目录中的野生动植物及其产品的，其申报内容与允许进出口证明书或者物种证明中记载的事项不符的，由海关依法予以处理。但申报进出口的数量未超过允许进出口证明书或者物种证明规定，且其他申报事项一致的除外。"},{"i":36,"n":"第三十六条","txt":"公约附录所列野生动植物及其产品需要过境、转运、通运的，不需申请核发野生动植物进出口证书。"},{"i":37,"n":"第三十七条","txt":"对下列事项有疑义的，货物进、出境所在地直属海关可以征求国家濒管办或者其办事处的意见： （一）允许进出口证明书或者物种证明的真实性、有效性。 （二）境外公约管理机构核发的允许进出口证明材料的真实性、有效性。 （三）野生动植物物种的种类、数量。 （四）进出境货物或者物品是否为濒危野生动植物及其产品或者是否含有濒危野生动植物种成份。 （五）海关质疑的其他情况。 国家濒管办或者其办事处应当及时回复意见。"},{"i":38,"n":"第三十八条","txt":"海关在允许进出口证明书和物种证明中记载进出口野生动植物及其产品的数量，并在办结海关手续后，将允许进出口证明书副本返还持证者。"},{"i":39,"n":"第三十九条","txt":"在境外与保税区、出口加工区等海关特殊监管区域、保税监管场所之间进出野生动植物及其产品的，申请人应当向海关交验允许进出口证明书或者物种证明。 在境内与保税区、出口加工区等海关特殊监管区域、保税监管场所之间进出野生动植物及其产品的，或者在上述海关特殊监管区域、保税监管场所之间进出野生动植物及其产品的，无须办理允许进出口证明书或者物种证明。"},{"i":40,"n":"第四十条","txt":"本办法所称允许进出口证明书包括濒危野生动植物种国际贸易公约允许进出口证明书和中华人民共和国野生动植物允许进出口证明书。 本办法所称物种证明是指非进出口野生动植物种商品目录物种证明。"},{"i":41,"n":"第四十一条","txt":"从不属于任何国家管辖的海域获得的野生动植物及其产品，进入中国领域的，参照本办法对进口野生动植物及其产品的有关规定管理。"},{"i":42,"n":"第四十二条","txt":"本办法关于期限没有特别规定的，适用行政许可法有关期限的规定。"},{"i":43,"n":"第四十三条","txt":"本办法由国家林业局、海关总署共同解释。"},{"i":44,"n":"第四十四条","txt":"本办法自2014年5月1日起实施。"}],"yeshengdongwujiqizhipinjiazhipinggufangfa":[{"i":1,"n":"第一条","txt":"为了规范野生动物及其制品价值评估标准和方法，根据《中华人民共和国野生动物保护法》第五十七条规定，制定本方法。"},{"i":2,"n":"第二条","txt":"《中华人民共和国野生动物保护法》规定的猎获物价值、野生动物及其制品价值的评估活动，适用本方法。 本方法所称野生动物，是指陆生野生动物的整体（含卵、蛋）；所称野生动物制品，是指陆生野生动物的部分及其衍生物，包括产品。"},{"i":3,"n":"第三条","txt":"国家林业局负责制定、公布并调整《陆生野生动物基准价值标准目录》。"},{"i":4,"n":"第四条","txt":"野生动物整体的价值，按照《陆生野生动物基准价值标准目录》所列该种野生动物的基准价值乘以相应的倍数核算。具体方法是： （一）国家一级保护野生动物，按照所列野生动物基准价值的十倍核算；国家二级保护野生动物，按照所列野生动物基准价值的五倍核算； （二）地方重点保护的野生动物和有重要生态、科学、社会价值的野生动物，按照所列野生动物基准价值核算。 两栖类野生动物的卵、蛋的价值，按照该种野生动物整体价值的千分之一核算；爬行类野生动物的卵、蛋的价值，按照该种野生动物整体价值的十分之一核算；鸟类野生动物的卵、蛋的价值，按照该种野生动物整体价值的二分之一核算。"},{"i":5,"n":"第五条","txt":"野生动物制品的价值，由核算其价值的执法机关或者评估机构根据实际情况予以核算，但不能超过该种野生动物的整体价值。但是，省级以上人民政府林业主管部门对野生动物标本和其他特殊野生动物制品的价值核算另有规定的除外。"},{"i":6,"n":"第六条","txt":"野生动物及其制品有实际交易价格的，且实际交易价格高于按照本方法评估的价值的，按照实际交易价格执行。"},{"i":7,"n":"第七条","txt":"人工繁育的野生动物及其制品的价值，按照同种野生动物及其制品价值的百分之五十执行。 人工繁育的列入《人工繁育国家重点保护野生动物名录》的野生动物及其制品的价值，按照同种野生动物及其制品价值的百分之二十五执行。"},{"i":8,"n":"第八条","txt":"《濒危野生动植物种国际贸易公约》附录所列在我国没有自然分布的野生动物，已经国家林业局核准按照国家重点保护野生动物管理的，该野生动物及其制品的价值按照与其同属、同科或者同目的国家重点保护野生动物的价值核算。 《濒危野生动植物种国际贸易公约》附录所列在我国没有自然分布的野生动物、未经国家林业局核准的，以及其他没有列入《濒危野生动植物种国际贸易公约》附录的野生动物及其制品的价值，按照与其同属、同科或者同目的地方重点保护野生动物或者有重要生态、科学、社会价值的野生动物的价值核算。"},{"i":9,"n":"第九条","txt":"本方法施行后，新增加的重点保护野生动物和有重要生态、科学、社会价值的野生动物，尚未列入《陆生野生动物基准价值标准目录》的，其基准价值按照与其同属、同科或者同目的野生动物的基准价值核算。"},{"i":10,"n":"第十条","txt":"本方法自2017年12月15日起施行。 附件：陆生野生动物基准价值标准目录"}],"yeshengdongwushourongjiuhuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范野生动物收容救护行为，依据《中华人民共和国野生动物保护法》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"从事野生动物收容救护活动的，应当遵守本办法。 本办法所称野生动物，是指依法受保护的陆生野生动物。"},{"i":3,"n":"第三条","txt":"野生动物收容救护应当遵循及时、就地、就近、科学的原则。 禁止以收容救护为名买卖野生动物及其制品。"},{"i":4,"n":"第四条","txt":"国家林业局负责组织、指导、监督全国野生动物收容救护工作。县级以上地方人民政府林业主管部门负责本行政区域内野生动物收容救护的组织实施、监督和管理工作。 县级以上地方人民政府林业主管部门应当按照有关规定明确野生动物收容救护机构，保障人员和经费，加强收容救护工作。 县级以上地方人民政府林业主管部门依照本办法开展收容救护工作，需要跨行政区域的或者需要其他行政区域予以协助的，双方林业主管部门应当充分协商、积极配合。必要时，可以由共同的上级林业主管部门统一协调。"},{"i":5,"n":"第五条","txt":"野生动物收容救护机构应当按照同级人民政府林业主管部门的要求和野生动物收容救护的实际需要，建立收容救护场所，配备相应的专业技术人员、救护工具、设备和药品等。 县级以上地方人民政府林业主管部门及其野生动物收容救护机构可以根据需要，组织从事野生动物科学研究、人工繁育等活动的组织和个人参与野生动物收容救护工作。"},{"i":6,"n":"第六条","txt":"县级以上地方人民政府林业主管部门应当公布野生动物收容救护机构的名称、地址和联系方式等相关信息。 任何组织和个人发现因受伤、受困等野生动物需要收容救护的，应当及时报告当地林业主管部门及其野生动物收容救护机构。"},{"i":7,"n":"第七条","txt":"有下列情况之一的，野生动物收容救护机构应当进行收容救护： （一）执法机关、其他组织和个人移送的野生动物； （二）野外发现的受伤、病弱、饥饿、受困等需要救护的野生动物，经简单治疗后还无法回归野外环境的； （三）野外发现的可能危害当地生态系统的外来野生动物； （四）其他需要收容救护的野生动物。 国家或者地方重点保护野生动物受到自然灾害、重大环境污染事故等突发事件威胁时，野生动物收容救护机构应当按照当地人民政府的要求及时采取应急救助措施。"},{"i":8,"n":"第八条","txt":"野生动物收容救护机构接收野生动物时，应当进行登记，记明移送人姓名、地址、联系方式、野生动物种类、数量、接收时间等事项，并向移送人出具接收凭证。"},{"i":9,"n":"第九条","txt":"野生动物收容救护机构对收容救护的野生动物，应当按照有关技术规范进行隔离检查、检疫，对受伤或者患病的野生动物进行治疗。"},{"i":10,"n":"第十条","txt":"野生动物收容救护机构应当按照以下规定处理收容救护的野生动物： （一）对体况良好、无需再采取治疗措施或者经治疗后体况恢复、具备野外生存能力的野生动物，应当按照有关规定，选择适合该野生动物生存的野外环境放至野外； （二）对收容救护后死亡的野生动物，应当进行检疫；检疫不合格的，应当采取无害化处理措施；检疫合格且按照规定需要保存的，应当采取妥当措施予以保存； （三）对经救护治疗但仍不适宜放至野外的野生动物和死亡后经检疫合格、确有利用价值的野生动物及其制品，属于国家重点保护野生动物及其制品的，依照《中华人民共和国野生动物保护法》的规定由具有相应批准权限的省级以上人民政府林业主管部门统一调配；其他野生动物及其制品，由县级以上地方人民政府林业主管部门依照有关规定调配处理。 处理执法机关查扣后移交的野生动物，事先应当征求原执法机关的意见，还应当遵守罚没物品处理的有关规定。"},{"i":11,"n":"第十一条","txt":"野生动物收容救护机构应当建立野生动物收容救护档案，记录收容救护的野生动物种类、数量、措施、状况等信息。 野生动物收容救护机构应当将处理收容救护野生动物的全过程予以记录，制作书面记录材料；必要时，还应当制作全过程音视频记录。"},{"i":12,"n":"第十二条","txt":"野生动物收容救护机构应当将收容救护野生动物的有关情况，按照年度向同级人民政府林业主管部门报告。 县级以上地方人民政府林业主管部门应当将本行政区域内收容救护野生动物总体情况，按照年度向上级林业主管部门报告。"},{"i":13,"n":"第十三条","txt":"从事野生动物收容救护活动成绩显著的组织和个人，按照《中华人民共和国野生动物保护法》有关规定予以奖励。 参与野生动物收容救护的组织和个人按照林业主管部门及其野生动物收容救护机构的规定开展野生动物收容救护工作，县级以上人民政府林业主管部门可以根据有关规定予以适当补助。"},{"i":14,"n":"第十四条","txt":"县级以上人民政府林业主管部门应当加强对本行政区域内收容救护野生动物活动进行监督检查。"},{"i":15,"n":"第十五条","txt":"野生动物收容救护机构或者其他组织和个人以收容救护野生动物为名买卖野生动物及其制品的，按照《中华人民共和国野生动物保护法》规定予以处理。"},{"i":16,"n":"第十六条","txt":"本办法自2018年1月1日起施行。"}],"lushengyeshengdongwuyiyuanyibingjiancefangkongguan42aca9":[{"i":1,"n":"第一条","txt":"为了加强陆生野生动物疫源疫病监测防控管理，防范陆生野生动物疫病传播和扩散，维护公共卫生安全和生态安全，保护野生动物资源，根据《中华人民共和国野生动物保护法》、《重大动物疫情应急条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"从事陆生野生动物疫源疫病监测防控活动，应当遵守本办法。 本办法所称陆生野生动物疫源是指携带危险性病原体，危及野生动物种群安全，或者可能向人类、饲养动物传播的陆生野生动物；本办法所称陆生野生动物疫病是指在陆生野生动物之间传播、流行，对陆生野生动物种群构成威胁或者可能传染给人类和饲养动物的传染性疾病。"},{"i":3,"n":"第三条","txt":"国家林业局负责组织、指导、监督全国陆生野生动物疫源疫病监测防控工作。县级以上地方人民政府林业主管部门按照同级人民政府的规定，具体负责本行政区域内陆生野生动物疫源疫病监测防控的组织实施、监督和管理工作。 陆生野生动物疫源疫病监测防控实行统一领导，分级负责，属地管理。"},{"i":4,"n":"第四条","txt":"国家林业局陆生野生动物疫源疫病监测机构按照国家林业局的规定负责全国陆生野生动物疫源疫病监测工作。"},{"i":5,"n":"第五条","txt":"县级以上地方人民政府林业主管部门应当按照有关规定确立陆生野生动物疫源疫病监测防控机构，保障人员和经费，加强监测防控工作。"},{"i":6,"n":"第六条","txt":"县级以上人民政府林业主管部门应当建立健全陆生野生动物疫源疫病监测防控体系,逐步提高陆生野生动物疫源疫病检测、预警和防控能力。"},{"i":7,"n":"第七条","txt":"乡镇林业工作站、自然保护区、湿地公园、国有林场的工作人员和护林员、林业有害生物测报员等基层林业工作人员应当按照县级以上地方人民政府林业主管部门的要求，承担相应的陆生野生动物疫源疫病监测防控工作。"},{"i":8,"n":"第八条","txt":"县级以上人民政府林业主管部门应当按照有关规定定期组织开展陆生野生动物疫源疫病调查，掌握疫病的基本情况和动态变化，为制定监测规划、预防方案提供依据。"},{"i":9,"n":"第九条","txt":"省级以上人民政府林业主管部门应当组织有关单位和专家开展陆生野生动物疫情预测预报、趋势分析等活动，评估疫情风险，对可能发生的陆生野生动物疫情，按照规定程序向同级人民政府报告预警信息和防控措施建议，并向有关部门通报。"},{"i":10,"n":"第十条","txt":"县级以上人民政府林业主管部门应当按照有关规定和实际需要，在下列区域建立陆生野生动物疫源疫病监测站： （一）陆生野生动物集中分布区； （二）陆生野生动物迁徙通道； （三）陆生野生动物驯养繁殖密集区及其产品集散地； （四）陆生野生动物疫病传播风险较大的边境地区； （五）其他容易发生陆生野生动物疫病的区域。"},{"i":11,"n":"第十一条","txt":"陆生野生动物疫源疫病监测站，分为国家级陆生野生动物疫源疫病监测站和地方级陆生野生动物疫源疫病监测站。 国家级陆生野生动物疫源疫病监测站的设立，由国家林业局组织提出或者由所在地省、自治区、直辖市人民政府林业主管部门推荐，经国家林业局组织专家评审后批准公布。 地方级陆生野生动物疫源疫病监测站按照省、自治区、直辖市人民政府林业主管部门的规定设立和管理，并报国家林业局备案。 陆生野生动物疫源疫病监测站统一按照“××（省、自治区、直辖市）××（地名）××级（国家级、省级、市级、县级）陆生野生动物疫源疫病监测站”命名。"},{"i":12,"n":"第十二条","txt":"陆生野生动物疫源疫病监测站应当配备专职监测员，明确监测范围、重点、巡查线路、监测点，开展陆生野生动物疫源疫病监测防控工作。 陆生野生动物疫源疫病监测站可以根据工作需要聘请兼职监测员。 监测员应当经过省级以上人民政府林业主管部门组织的专业技术培训；专职监测员应当经省级以上人民政府林业主管部门考核合格。"},{"i":13,"n":"第十三条","txt":"陆生野生动物疫源疫病监测实行全面监测、突出重点的原则，并采取日常监测和专项监测相结合的工作制度。 日常监测以巡护、观测等方式，了解陆生野生动物种群数量和活动状况，掌握陆生野生动物异常情况，并对是否发生陆生野生动物疫病提出初步判断意见。 专项监测根据疫情防控形势需要，针对特定的陆生野生动物疫源种类、特定的陆生野生动物疫病、特定的重点区域进行巡护、观测和检测，掌握特定陆生野生动物疫源疫病变化情况，提出专项防控建议。 日常监测、专项监测情况应当按照有关规定逐级上报上级人民政府林业主管部门。"},{"i":14,"n":"第十四条","txt":"日常监测根据陆生野生动物迁徙、活动规律和疫病发生规律等分别实行重点时期监测和非重点时期监测。 日常监测的重点时期和非重点时期，由省、自治区、直辖市人民政府林业主管部门根据本行政区域内陆生野生动物资源变化和疫病发生规律等情况确定并公布，报国家林业局备案。 重点时期内的陆生野生动物疫源疫病监测情况实行日报告制度；非重点时期的陆生野生动物疫源疫病监测情况实行周报告制度。但是发现异常情况的，应当按照有关规定及时报告。"},{"i":15,"n":"第十五条","txt":"国家林业局根据陆生野生动物疫源疫病防控工作需要，经组织专家论证，制定并公布重点监测陆生野生动物疫病种类和疫源物种目录；省、自治区、直辖市人民政府林业主管部门可以制定本行政区域内重点监测陆生野生动物疫病种类和疫源物种补充目录。 县级以上人民政府林业主管部门应当根据前款规定的目录和本辖区内陆生野生动物疫病发生规律，划定本行政区域内陆生野生动物疫源疫病监测防控重点区域，并组织开展陆生野生动物重点疫病的专项监测。"},{"i":16,"n":"第十六条","txt":"本办法第七条规定的基层林业工作人员发现陆生野生动物疑似因疫病引起的异常情况，应当立即向所在地县级以上地方人民政府林业主管部门或者陆生野生动物疫源疫病监测站报告；其他单位和个人发现陆生野生动物异常情况的，有权向当地林业主管部门或者陆生野生动物疫源疫病监测站报告。"},{"i":17,"n":"第十七条","txt":"县级人民政府林业主管部门或者陆生野生动物疫源疫病监测站接到陆生野生动物疑似因疫病引起异常情况的报告后，应当及时采取现场隔离等措施，组织具备条件的机构和人员取样、检测、调查核实，并按照规定逐级上报到省、自治区、直辖市人民政府林业主管部门，同时报告同级人民政府，并通报兽医、卫生等有关主管部门。"},{"i":18,"n":"第十八条","txt":"省、自治区、直辖市人民政府林业主管部门接到报告后，应当组织有关专家和人员对上报情况进行调查、分析和评估，对确需进一步采取防控措施的，按照规定报国家林业局和同级人民政府，并通报兽医、卫生等有关主管部门。"},{"i":19,"n":"第十九条","txt":"国家林业局接到报告后，应当组织专家对上报情况进行会商和评估，指导有关省、自治区、直辖市人民政府林业主管部门采取科学的防控措施，按照有关规定向国务院报告，并通报国务院兽医、卫生等有关主管部门。"},{"i":20,"n":"第二十条","txt":"县级以上人民政府林业主管部门应当制定突发陆生野生动物疫病应急预案，按照有关规定报同级人民政府批准或者备案。 陆生野生动物疫源疫病监测站应当按照不同陆生野生动物疫病及其流行特点和危害程度，分别制定实施方案。实施方案应当报所属林业主管部门备案。 陆生野生动物疫病应急预案及其实施方案应当根据疫病的发展变化和实施情况，及时修改、完善。"},{"i":21,"n":"第二十一条","txt":"县级以上人民政府林业主管部门应当根据陆生野生动物疫源疫病监测防控工作需要和应急预案的要求，做好防护装备、消毒物品、野外工作等应急物资的储备。"},{"i":22,"n":"第二十二条","txt":"发生重大陆生野生动物疫病时，所在地人民政府林业主管部门应当在人民政府的统一领导下及时启动应急预案，组织开展陆生野生动物疫病监测防控和疫病风险评估，提出疫情风险范围和防控措施建议，指导有关部门和单位做好事发地的封锁、隔离、消毒等防控工作。"},{"i":23,"n":"第二十三条","txt":"在陆生野生动物疫源疫病监测防控中，发现重点保护陆生野生动物染病的，有关单位和个人应当按照野生动物保护法及其实施条例的规定予以救护。 处置重大陆生野生动物疫病过程中，应当避免猎捕陆生野生动物；特殊情况确需猎捕陆生野生动物的，应当按照有关法律法规的规定执行。"},{"i":24,"n":"第二十四条","txt":"县级以上人民政府林业主管部门应当采取措施，鼓励和支持有关科研机构开展陆生野生动物疫源疫病科学研究。 需要采集陆生野生动物样品的，应当遵守有关法律法规的规定。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府林业主管部门及其监测机构应当加强陆生野生动物疫源疫病监测防控的宣传教育，提高公民防范意识和能力。"},{"i":26,"n":"第二十六条","txt":"陆生野生动物疫源疫病监测信息应当按照国家有关规定实行管理，任何单位和个人不得擅自公开。"},{"i":27,"n":"第二十七条","txt":"林业主管部门、陆生野生动物疫源疫病监测站等相关单位的工作人员玩忽职守，造成陆生野生动物疫情处置延误，疫情传播、蔓延的，或者擅自公开有关监测信息、编造虚假监测信息，妨碍陆生野生动物疫源疫病监测工作的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":28,"n":"第二十八条","txt":"本办法自2013年4月1日起施行。"}],"jitilinquanzhidugaigedanganguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强和规范集体林权制度改革档案工作，有效保护和利用集体林权制度改革档案，根据《森林法》和《档案法》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称集体林权制度改革档案是指在集体林权制度改革（以下简称林改）中形成的对国家和社会有保存价值的文字、图表、声像、数据等各种形式或者载体文件材料的总称，是林改的重要成果和历史记录。"},{"i":3,"n":"第三条","txt":"本办法所称林改档案工作是指林改档案的收集、整理、鉴定、保管、编研、利用等工作。"},{"i":4,"n":"第四条","txt":"林改档案工作坚持统一领导、分级管理、集中保管、同步进行、规范运作的原则。 林改档案工作应当与林改工作同步进行和检查验收，并作为评价林改效果的重要依据。"},{"i":5,"n":"第五条","txt":"县级以上林业行政主管部门和档案行政管理部门负责本级林改档案工作，并对本行政区域内的林改档案工作实行监督、指导、检查和验收。 县级以上林业行政主管部门应当设立或者明确林改档案管理机构，配备专职人员，按照《森林法》和《森林法实施条例》等有关规定管理林改档案。"},{"i":6,"n":"第六条","txt":"林改档案管理机构应当履行下列工作职责： （一）贯彻执行国家档案工作的有关法律、法规和方针、政策； （二）按照有关规范和标准，制定林改档案管理制度和工作标准； （三）指导林改文件材料的登记、积累和归档工作； （四）负责林改档案的收集、整理、鉴定、编目、统计等工作； （五）掌握所保管的林改档案情况，依法提供利用； （六）负责组织林改档案工作人员培训； （七）按照国家法律法规以及有关规定，做好林改档案的保管和移交工作。"},{"i":7,"n":"第七条","txt":"县级以上林业行政主管部门应当建立、健全林改文件材料的收集、整理、归档制度，确保林改档案资料的齐全、完整、真实、有效。 县级林业行政主管部门、乡（镇）林业工作站和集体经济组织应当将林改文件材料的收集、整理、归档纳入工作计划。"},{"i":8,"n":"第八条","txt":"林改档案作为文书档案进行管理，按照档案国家标准《文书档案案卷格式》（GB/T9705-88）和档案行业标准《归档文件整理规则》（DA/T22-2000）等有关标准的要求进行整理，并在次年的上半年完成立卷归档工作。"},{"i":9,"n":"第九条","txt":"产生文件材料较多的机关、单位或者组织，应当将林改档案分为大类和属类进行管理。 林改档案大类和属类设定可以参照《集体林权制度改革文件材料归档范围及保管期限表》执行。"},{"i":10,"n":"第十条","txt":"确权和林权登记类中有关确认森林、林木、林地权属、实地勘界、登记和林权证审核发放等文件材料，应当以农户或者宗地为单元，进行整理、归档和管理。"},{"i":11,"n":"第十一条","txt":"林改工作人员应当及时收集在林改中形成的各类文件材料，并交由林改档案管理机构整理、保管和提供利用。 林改工作人员在工作调离前，应当将个人掌握的林改文件材料，按照相关要求整理后移交给林改档案管理机构，不得拒绝移交、销毁或者擅自带离。"},{"i":12,"n":"第十二条","txt":"林改档案保管期限分为永久和定期。 林改档案具有重要查考利用保存价值的，应当永久保存；具有一般利用保存价值的，应当定期保存，期限为30年或者10年。 具体划分办法按照《集体林权制度改革文件材料归档范围及保管期限表》执行。"},{"i":13,"n":"第十三条","txt":"归档的林改文件纸质材料应当字迹工整、数字准确、图样清晰、手续完备。 归档纸质材料应当使用碳素、蓝黑墨水等不易褪色的书写材料，因特殊情况容易产生字迹模糊或者褪变的文件材料应当附一份清晰的复印件。 纸张、装订材料等应当符合档案保护要求。"},{"i":14,"n":"第十四条","txt":"归档的林改文件非纸质材料应当将每一件（盒、盘）作为一个保管单位，单独排列编号，按照内容和年度分类整理并编制档号。其中与纸质文件材料有直接联系的应当编写互见号或者互见卡。 录音、录像材料要保证载体的有效性，电子文件和使用信息系统采集、贮存的专业性数据以及航空照片、遥感数据应当用可记录式光盘保存，重要的应制成纸质拷贝同时归档保存。 照片和图片应当配有文字说明，标明时间、地点、人物和事件。 电子文件产生的软硬件环境及参数须符合有关要求。"},{"i":15,"n":"第十五条","txt":"各级林业行政主管部门应当建立林改档案保管制度，安排林改档案保管专用资金，配备档案用房、柜架，备有防火、防盗、防渍、防有害生物等安全设施，定期开展档案保管状况检查，确保档案安全。"},{"i":16,"n":"第十六条","txt":"县级林业行政主管部门应当按照国家有关法律、行政法规和规章的规定，按时向县级国家档案馆移交林改档案。 经同级林业行政主管部门和档案行政管理部门协商同意，林改档案可以提前移交，并按规定办理移交手续。"},{"i":17,"n":"第十七条","txt":"乡（镇）人民政府档案机构和集体经济组织应当加强林改档案的保管和移交工作。 集体经济组织不具备档案保管条件的可以将林改档案移交乡（镇）人民政府档案机构保管，经县级林业行政主管部门和档案行政管理部门验收后，　依法及时移交县级国家档案馆统一保管。"},{"i":18,"n":"第十八条","txt":"林改档案管理机构撤并时，应当将林改档案整理登记后，妥善移交给主管机关或者接收单位。"},{"i":19,"n":"第十九条","txt":"县级林业行政主管部门、乡（镇）人民政府档案机构在移交档案之前，应当保留备份或者复印件。 森林、林木和林地权属登记、林权证发放等形成的文件资料原件一式两套，一套留县级林业行政主管部门、一套移交同级国家档案馆永久保存。"},{"i":20,"n":"第二十条","txt":"县级国家档案馆应将林改档案纳入档案进馆接收范围，并将其统一归入林业行政主管部门单位全宗序列，对所保存的林改档案严格按照规定整理和保管。"},{"i":21,"n":"第二十一条","txt":"各级林改档案管理机构和国家档案馆应当按照有关规定向社会开放林改档案，为社会提供利用林改档案服务，但涉及国家秘密、个人隐私和法律另有规定的除外。 单位和个人持有合法身份证明，可以依法利用已经开放的林改档案。向国家档案馆移交林改档案的林业行政主管部门和其他经济组织，对其档案享有优先利用的权利。 利用林改档案资料时，除依法收取的复制成本费外，不得收取其他费用。"},{"i":22,"n":"第二十二条","txt":"县级以上林业行政主管部门和档案行政管理部门应当推进林改档案的信息化建设，加强林改电子文件归档和电子档案的规范化管　理，提供网上信息查询服务。"},{"i":23,"n":"第二十三条","txt":"对在林改档案的收集、整理、利用等各项工作中做出突出成绩的单位或个人，由各级人民政府及林业行政主管部门、档案行政管理　部门给予奖励。"},{"i":24,"n":"第二十四条","txt":"对于违反有关规定，造成林改档案失真、损毁或丢失的，依法追究相关人员的法律责任；情节严重的依法移送司法机关处理。"},{"i":25,"n":"第二十五条","txt":"省、自治区、直辖市林业行政主管部门、档案行政管理部门可以根据有关法律、法规，结合本办法和本地实际，制定林改档案工作有关规定。"},{"i":26,"n":"第二十六条","txt":"法律、行政法规、国务院决定对林改档案的管理另有规定的，从其规定。"},{"i":27,"n":"第二十七条","txt":"本办法自2013年6月22日起施行。 附件：集体林权制度改革文件材料归档范围及保管期限表"}]};
